  font-weight: 600;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}

/* ===== Next original style block ===== */

/* ─── RESET & TOKENS ─── */

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --ivory: #F9F7F4;
  --ivory-dk: #F0ECE6;
  --gold: #B89968;
  --gold-lt: #D4B896;
  --gold-pale: #F5EFE4;
  --forest: #2D4A3E;
  --forest-lt: #779186;
  --forest-deep: #20362D;
  --forest-deeper: #162720;
  --charcoal: #2A2A2A;
  --muted: rgba(42,42,42,.55);
  --border: rgba(184,153,104,.30);
  --border-dk: rgba(42,42,42,.15);
  --red: #C0392B;
  --red-pale: #FDEAEA;
  --amber: #E67E22;
  --amber-pale: #FEF3E2;
  --green: #27acae;
  --green-pale: #E9F7EF;
  --radius: 8px;
  --shadow: 0 2px 12px rgba(42,42,42,.08);
  --sidebar-w: 220px;
  --font-serif: "Cormorant Garamond", "EB Garamond", Georgia, serif;
  --font-sans: Inter, "Noto Sans", Arial, sans-serif;
}

html {
  font-size: 15px;
}

/* Nudge the base (sans) body-copy size up a touch for readability.
   Serif headings are pinned back to their original scale just below so
   only the sans body text grows. */
html {
  font-size: 106.25%; /* 16px -> 17px base */
}

body {
  font-family: var(--font-sans);
  background: var(--ivory-dk);
  color: var(--charcoal);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

h1,
h2,
h3,
h4 {
  font-family: var(--font-serif);
  font-weight: 400;
}

/* Hold serif headings at their pre-bump visual size so the root increase
   only affects sans body text, not the (serif) header text. */
h1 { font-size: 1.647rem; }  /* ~28px, was ~1.75rem @16px */
h2 { font-size: 1.235rem; }  /* ~21px, was ~1.3125rem @16px */
h3 { font-size: 1.06rem; }   /* ~18px */
h4 { font-size: .918rem; }   /* ~15.6px */

button {
  cursor: pointer;
  font-family: var(--font-sans);
}

input,
select,
textarea {
  font-family: var(--font-sans);
  font-size: .9rem;
  border: 1px solid var(--border-dk);
  border-radius: 5px;
  padding: .4rem .6rem;
  background: #fff;
  color: var(--charcoal);
  width: 100%;
  transition: border-color .15s;
}

input:focus,
select:focus,
textarea:focus {
  outline: none;
  border-color: var(--gold);
}

textarea {
  resize: vertical;
  min-height: 70px;
}

/* ─── TOP BAR ─── */

#topbar {
  background: var(--forest);
  color: var(--ivory);
  padding: .7rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0,0,0,.18);
}

#topbar .brand {
  display: flex;
  align-items: center;
  gap: .8rem;
}

#topbar h1 {
  font-size: 1.25rem;
  color: var(--gold-lt);
  letter-spacing: .5px;
}

#topbar .sub {
  font-size: .72rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(249,247,244,.6);
}

#topbar .actions {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
}

/* ─── GLOBAL SEARCH ─── */

.global-search {
  position: relative;
  flex: 1 1 240px;
  min-width: 170px;
  max-width: 380px;
  margin-left: auto;
}

.global-search .gs-icon {
  position: absolute;
  left: .6rem;
  top: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  pointer-events: none;
  color: var(--forest);
  opacity: .6;
}

.global-search .gs-icon svg {
  width: 1rem;
  height: 1rem;
}

#gs-input {
  width: 100%;
  box-sizing: border-box;
  padding: .46rem .7rem .46rem 2rem;
  border: 1px solid rgba(212,184,150,.5);
  border-radius: 999px;
  background: rgba(249,247,244,.96);
  color: var(--charcoal,#2a2a2a);
  font-size: .84rem;
  font-family: inherit;
  outline: none;
}

#gs-input::placeholder {
  color: #8a857d;
}

#gs-input:focus {
  border-color: var(--gold,#b89968);
  box-shadow: 0 0 0 3px rgba(184,153,104,.22);
}

.gs-results {
  display: none;
  position: absolute;
  top: calc(100% + .4rem);
  right: 0;
  left: 0;
  background: #fff;
  border: 1px solid rgba(212,184,150,.5);
  border-radius: 12px;
  box-shadow: 0 16px 44px rgba(45,40,30,.22);
  max-height: 62vh;
  overflow-y: auto;
  z-index: 1200;
  padding: .3rem;
}

.gs-results.open {
  display: block;
}

.gs-result {
  display: flex;
  align-items: center;
  gap: .6rem;
  padding: .5rem .6rem;
  border-radius: 8px;
  cursor: pointer;
  text-align: left;
}

.gs-result:hover,
.gs-result.gs-active {
  background: #faf5ec;
}

.gs-result .gs-type {
  flex: 0 0 auto;
  font-size: .6rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: #fff;
  background: var(--forest,#2d4a3e);
  padding: .2rem .45rem;
  border-radius: 999px;
}

.gs-result .gs-body {
  min-width: 0;
  flex: 1;
}

.gs-result .gs-title {
  font-size: .86rem;
  color: var(--charcoal,#2a2a2a);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gs-result .gs-sub {
  font-size: .72rem;
  color: #7a756d;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gs-empty {
  padding: .8rem .7rem;
  font-size: .82rem;
  color: #7a756d;
  text-align: center;
}

.gs-group-label {
  padding: .45rem .6rem .2rem;
  font-size: .62rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #a89c86;
}

@media (max-width:760px) {
  .global-search {
    order: 5;
    flex-basis: 100%;
    max-width: none;
    margin-left: 0;
  }

}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  padding: .42rem .85rem;
  border-radius: 5px;
  font-size: .82rem;
  font-weight: 500;
  border: none;
  transition: all .15s;
  white-space: nowrap;
}

.btn-gold {
  background: var(--gold);
  color: #fff;
}

.btn-gold:hover {
  background: var(--gold-lt);
}

.btn-forest {
  background: var(--forest-lt);
  color: #fff;
}

.btn-forest:hover {
  background: var(--forest-deep);
}

.btn-outline {
  background: transparent;
  color: var(--forest);
  border: 1px solid var(--gold);
}

.btn-outline:hover {
  background: var(--gold-pale);
}

#topbar .btn-outline {
  color: var(--ivory);
  border-color: rgba(249,247,244,.35);
}

#topbar .btn-outline:hover {
  background: rgba(249,247,244,.1);
}

.btn-danger {
  background: var(--red);
  color: #fff;
}

.btn-danger:hover {
  background: #a93226;
}

.btn-sm {
  padding: .3rem .65rem;
  font-size: .78rem;
}

/* ─── BACKUP BANNER ─── */

#backup-banner {
  background: var(--gold-pale);
  border-bottom: 1px solid var(--border);
  padding: .6rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font-size: .82rem;
  color: var(--charcoal);
}

#backup-banner.is-dismissed {
  display: none !important;
}

html.backup-banner-dismissed-early #backup-banner {
  display: none !important;
}

#backup-banner .backup-banner-copy {
  flex: 1;
  min-width: 0;
}

#backup-banner strong {
  color: var(--forest);
}

#backup-banner .backup-banner-dismiss {
  flex-shrink: 0;
  padding: .32rem .75rem;
  border-radius: 6px;
  font-size: .76rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.65);
  color: var(--forest);
  transition: background .15s, border-color .15s;
}

#backup-banner .backup-banner-dismiss:hover {
  background: #fff;
  border-color: color-mix(in srgb, var(--forest) 25%, var(--border));
}

#storage-warning {
  display: none;
  background: #FDF2F2;
  border-bottom: 2px solid #C53030;
  padding: .65rem 1.5rem;
  gap: 1rem;
  align-items: center;
  justify-content: center;
  font-size: .84rem;
  color: #742A2A;
  text-align: center;
  flex-wrap: wrap;
}

#storage-warning.visible {
  display: flex;
}

#storage-warning strong {
  color: #C53030;
}

#storage-warning .sw-actions {
  display: flex;
  gap: .5rem;
  flex-shrink: 0;
}

#storage-warning .sw-btn {
  padding: .32rem .8rem;
  border-radius: 6px;
  font-size: .78rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background .2s;
}

#storage-warning .sw-backup {
  background: #C53030;
  color: #fff;
}

#storage-warning .sw-backup:hover {
  background: #9B2C2C;
}

#storage-warning .sw-dismiss {
  background: rgba(197,48,48,.12);
  color: #C53030;
}

#storage-warning .sw-dismiss:hover {
  background: rgba(197,48,48,.22);
}

#last-saved {
  font-size: .75rem;
  color: var(--muted);
}

#profile-bar {
  background: var(--forest);
  color: #FFFDF9;
  padding: .45rem 1.5rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .6rem 1.2rem;
  font-size: .82rem;
}

.pbar-group {
  display: flex;
  align-items: center;
  gap: .45rem;
  flex-wrap: wrap;
}

.pbar-label {
  color: var(--gold-lt);
  letter-spacing: .04em;
}

#profile-bar select {
  padding: .28rem .5rem;
  border-radius: 6px;
  border: 1px solid rgba(212,184,150,.4);
  background: #FFFDF9;
  color: var(--charcoal);
  font-size: .82rem;
  max-width: 200px;
}

#profile-bar .btn-sm {
  padding: .25rem .6rem;
  font-size: .76rem;
  background: rgba(255,255,255,.1);
  color: #FFFDF9;
  border-color: rgba(212,184,150,.5);
}

#profile-bar .btn-sm:hover {
  background: rgba(255,255,255,.2);
}

/* ─── LAYOUT ─── */

#layout {
  display: flex;
  flex: 1;
  min-height: 0;
}

/* ─── SIDEBAR ─── */

#sidebar {
  width: var(--sidebar-w);
  background: var(--ivory);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  padding: 1rem 0;
  height: auto;
  overflow: visible;
  flex-shrink: 0;
}

.nav-section {
  margin-bottom: .25rem;
}

.nav-label {
  font-size: .65rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  padding: .5rem 1.2rem .2rem;
}

button.nav-item {
  background: none;
  border: none;
  border-radius: 0;
  font-family: inherit;
  font-size: inherit;
  text-align: left;
  width: 100%;
  appearance: none;
  -webkit-appearance: none;
  outline: none;
  margin: 0;
  box-shadow: none;
}

button.nav-item:focus-visible {
  outline: 2px solid var(--gold, #B89968);
  outline-offset: -2px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: .6rem;
  padding: .55rem 1.2rem;
  font-size: .875rem;
  cursor: pointer;
  color: var(--charcoal);
  border-left: 3px solid transparent;
  transition: all .12s;
}

.nav-item:hover {
  background: var(--ivory-dk);
}

.nav-item.active {
  color: var(--forest);
  font-weight: 600;
  border-left-color: var(--gold);
  background: var(--gold-pale);
}

.nav-icon {
  font-size: 1rem;
  width: 1.2rem;
  text-align: center;
}

.nav-badge {
  margin-left: auto;
  font-size: .68rem;
  background: var(--red);
  color: #fff;
  border-radius: 10px;
  padding: .1rem .4rem;
  min-width: 1.2rem;
  text-align: center;
}

/* ─── Section completion progress badges ─── */

.nav-prog {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: .28rem;
  font-size: .64rem;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: .02em;
}

.nav-prog::before {
  content: "";
  width: .5rem;
  height: .5rem;
  border-radius: 50%;
  background: #c9c2b6;
  flex: 0 0 auto;
}

.nav-prog[data-state="progress"]::before {
  background: #d9a441;
}

.nav-prog[data-state="done"]::before {
  background: #3d8a5f;
}

.nav-prog[data-state="done"] {
  color: #3d8a5f;
}

.nav-item.active .nav-prog {
  color: var(--forest);
}

/* ─── Planning progress card (dashboard) ─── */

#section-progress-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.1rem 1.2rem;
  margin-top: 1.1rem;
  box-shadow: 0 6px 18px rgba(54,39,20,.05);
}

#section-progress-card .spc-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: .85rem;
  flex-wrap: wrap;
}

#section-progress-card .spc-title {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest);
  font-size: 1.1rem;
  margin: 0;
}

#section-progress-card .spc-overall {
  font-size: .78rem;
  color: var(--muted);
}

#section-progress-card .spc-overall b {
  color: var(--forest);
}

.spc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(190px,1fr));
  gap: .5rem .8rem;
}

.spc-row {
  display: flex;
  align-items: center;
  gap: .55rem;
  padding: .4rem .55rem;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--ivory);
  cursor: pointer;
  transition: background .12s;
}

.spc-row:hover {
  background: var(--gold-pale);
}

.spc-dot {
  width: .6rem;
  height: .6rem;
  border-radius: 50%;
  background: #c9c2b6;
  flex: 0 0 auto;
}

.spc-row[data-state="progress"] .spc-dot {
  background: #d9a441;
}

.spc-row[data-state="done"] .spc-dot {
  background: #3d8a5f;
}

.spc-name {
  flex: 1;
  min-width: 0;
  font-size: .82rem;
  color: var(--charcoal);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.spc-meta {
  font-size: .72rem;
  color: var(--muted);
  font-weight: 600;
}

.spc-row[data-state="done"] .spc-meta {
  color: #3d8a5f;
}

/* ─── Key Dates summary card (Step 1.4) ─── */

#key-dates-card {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.1rem 1.2rem;
  margin-top: 1.1rem;
  box-shadow: 0 6px 18px rgba(54,39,20,.05);
}

#key-dates-card .kd-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: .85rem;
  flex-wrap: wrap;
}

#key-dates-card .kd-title {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest);
  font-size: 1.1rem;
  margin: 0;
}

#key-dates-card .kd-sub {
  font-size: .78rem;
  color: var(--muted);
}

.kd-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(250px,1fr));
  gap: .55rem .8rem;
}

.kd-row {
  display: flex;
  align-items: center;
  gap: .7rem;
  padding: .5rem .6rem;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--ivory);
  cursor: pointer;
  transition: background .12s,border-color .12s;
}

.kd-row:hover {
  background: var(--gold-pale);
  border-color: var(--gold-lt);
}

.kd-row.kd-overdue {
  background: #fbeceb;
  border-color: #e7b9b3;
}

.kd-row.kd-milestone {
  background: var(--gold-pale);
  border-color: var(--gold-lt);
}

.kd-date {
  flex: 0 0 auto;
  width: 2.9rem;
  text-align: center;
  line-height: 1;
}

.kd-date b {
  display: block;
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest);
  font-size: 1.15rem;
}

.kd-date span {
  display: block;
  font-size: .62rem;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: .12rem;
}

.kd-row.kd-overdue .kd-date b {
  color: var(--red,#b3402f);
}

.kd-body {
  flex: 1;
  min-width: 0;
}

.kd-name {
  font-size: .85rem;
  color: var(--charcoal);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.kd-meta {
  font-size: .72rem;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.kd-when {
  flex: 0 0 auto;
  font-size: .72rem;
  font-weight: 700;
  color: var(--forest);
  text-align: right;
}

.kd-row.kd-overdue .kd-when {
  color: var(--red,#b3402f);
}

.kd-empty {
  font-size: .82rem;
  color: var(--muted);
  padding: .5rem .2rem;
}

/* ─── Start-Here onboarding checklist (Step 2.1) ─── */

#start-here-card {
  background: var(--ivory,#F7F3ED);
  color: var(--charcoal,#3b3228);
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 16px;
  padding: 1.3rem 1.4rem;
  margin-bottom: 1.25rem;
  box-shadow: 0 6px 20px rgba(54,39,20,.06);
  position: relative;
  overflow: hidden;
  text-align: center;
}

#start-here-card .sh-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .4rem;
  margin-bottom: 1rem;
}

#start-here-card .sh-kicker {
  font-size: .7rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--gold,#C9A84C);
  font-weight: 700;
}

#start-here-card .sh-title {
  font-family: var(--font-serif,Georgia,serif);
  font-size: 1.4rem;
  color: var(--forest,#2D4A3E);
  margin: .2rem 0 .2rem;
}

#start-here-card .sh-lead {
  font-size: .82rem;
  color: var(--muted,#8a7e6b);
  max-width: 46ch;
  margin: 0 auto;
}

#start-here-card .sh-progress {
  font-size: .74rem;
  color: var(--gold,#C9A84C);
  font-weight: 700;
  white-space: nowrap;
  margin-top: .3rem;
}

#start-here-card .sh-dismiss {
  display: none;
}

#start-here-card .sh-close {
  position: absolute;
  top: .7rem;
  right: .7rem;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--muted,#8a7e6b);
  padding: .2rem;
  line-height: 1;
  font-size: 1.1rem;
}

#start-here-card .sh-close:hover {
  color: var(--forest,#2D4A3E);
}

#start-here-card .sh-bar {
  height: 5px;
  border-radius: 99px;
  background: var(--ivory-dk,#e7e0d3);
  margin: .2rem auto 1rem;
  max-width: 400px;
  overflow: hidden;
}

#start-here-card .sh-bar i {
  display: block;
  height: 100%;
  border-radius: 99px;
  background: var(--gold,#C9A84C);
  transition: width .35s ease;
}

.sh-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(220px,1fr));
  gap: .55rem .7rem;
}

.sh-item {
  display: flex;
  align-items: center;
  gap: .6rem;
  padding: .55rem .65rem;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 10px;
  background: #fff;
  cursor: pointer;
  transition: background .12s;
  text-align: left;
  color: inherit;
  font: inherit;
  width: 100%;
}

.sh-item:hover {
  background: var(--ivory-dk,#e7e0d3);
}

.sh-item .sh-check {
  flex: 0 0 auto;
  width: 1.15rem;
  height: 1.15rem;
  border-radius: 50%;
  border: 2px solid var(--border,#d4cfc6);
  display: flex;
  align-items: center;
  justify-content: center;
}

.sh-item .sh-check svg {
  width: .7rem;
  height: .7rem;
  stroke: #fff;
  stroke-width: 3.2;
  fill: none;
  opacity: 0;
}

.sh-item.done .sh-check {
  background: var(--gold,#C9A84C);
  border-color: var(--gold,#C9A84C);
}

.sh-item.done .sh-check svg {
  opacity: 1;
}

.sh-item .sh-label {
  flex: 1;
  min-width: 0;
  font-size: .83rem;
  color: var(--charcoal,#3b3228);
}

.sh-item.done .sh-label {
  color: var(--muted,#8a7e6b);
  text-decoration: line-through;
}

.sh-item .sh-go {
  font-size: .66rem;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--gold,#C9A84C);
  font-weight: 700;
  opacity: .85;
}

.sh-item.done .sh-go {
  opacity: 0;
}

#start-here-card .sh-foot {
  margin-top: 1rem;
  display: flex;
  gap: .6rem;
  flex-wrap: wrap;
  justify-content: center;
}

#start-here-card .sh-wizard-btn {
  background: var(--gold);
  color: var(--forest);
  border: none;
  border-radius: 9px;
  padding: .55rem 1.1rem;
  font-weight: 700;
  font-size: .82rem;
  cursor: pointer;
}

#start-here-card .sh-wizard-btn:hover {
  filter: brightness(1.05);
}

/* ─── 3-Minute Setup Wizard modal (Step 2.1) ─── */

.wizard-modal {
  max-width: 560px;
  padding: 1.9rem 2rem;
}

.wizard-modal .wz-kicker {
  font-size: .7rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 700;
}

.wizard-modal h3 {
  margin: .25rem 0 .15rem;
  font-size: 1.5rem;
}

.wizard-modal .wz-sub {
  font-size: .82rem;
  color: var(--muted);
  margin-bottom: 1.1rem;
}

.wizard-modal .wz-steps {
  display: flex;
  gap: .4rem;
  margin-bottom: 1.3rem;
}

.wizard-modal .wz-steps span {
  flex: 1;
  height: 4px;
  border-radius: 99px;
  background: var(--ivory-dk,#e7e0d3);
}

.wizard-modal .wz-steps span.active {
  background: var(--gold);
}

.wizard-step {
  display: none;
}

.wizard-step.active {
  display: block;
}

.wizard-step h4 {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest);
  font-size: 1.1rem;
  margin: 0 0 .15rem;
}

.wizard-step .wz-hint {
  font-size: .78rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.wz-fields {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: .7rem .9rem;
}

.wz-fields label {
  display: flex;
  flex-direction: column;
  gap: .25rem;
  font-size: .74rem;
  color: var(--charcoal);
  font-weight: 600;
}

.wz-fields label.wz-full {
  grid-column: 1 / -1;
}

.wz-fields input {
  padding: .5rem .6rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font: inherit;
  font-size: .86rem;
}

.wz-fields input:focus {
  outline: none;
  border-color: var(--gold);
}

.wizard-modal .wz-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  margin-top: 1.4rem;
}

.wizard-modal .wz-actions .wz-right {
  display: flex;
  gap: .5rem;
}

.wizard-modal .wz-skip {
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-size: .8rem;
  text-decoration: underline;
}

.wizard-modal .wz-sample {
  font-size: .74rem;
  color: var(--muted);
  text-align: center;
  margin-top: 1rem;
}

.wizard-modal .wz-sample a {
  color: var(--gold);
  font-weight: 700;
  cursor: pointer;
}

/* ─── Quick Jump / Recent Pages (Step 3.1) ─── */

#quick-jump-wrap {
  position: relative;
}

#quick-jump-btn {
  background: none;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 8px;
  padding: .35rem .55rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  color: var(--forest);
  font-size: .78rem;
  font-weight: 600;
  white-space: nowrap;
}

#quick-jump-btn svg {
  width: 1rem;
  height: 1rem;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#quick-jump-btn:hover {
  background: var(--ivory-dk,#e7e0d3);
}

#quick-jump-drop {
  display: none;
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  width: 260px;
  max-height: 370px;
  overflow-y: auto;
  background: #fff;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(54,39,20,.13);
  z-index: 800;
  padding: .5rem 0;
}

#quick-jump-drop.open {
  display: block;
}

.qj-section {
  padding: .2rem .7rem;
  font-size: .65rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted,#8a7e6b);
  font-weight: 700;
  margin-top: .3rem;
}

.qj-item {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .45rem .7rem;
  cursor: pointer;
  font-size: .82rem;
  color: var(--charcoal,#3b3228);
  transition: background .1s;
}

.qj-item:hover {
  background: var(--ivory-dk,#e7e0d3);
}

.qj-item .qj-icon {
  flex: 0 0 auto;
  width: 1.1rem;
  height: 1.1rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.qj-item .qj-icon svg {
  width: 1rem;
  height: 1rem;
  stroke: var(--forest);
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.qj-item .qj-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.qj-star {
  flex: 0 0 auto;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  color: var(--gold-lt,#d8b778);
  font-size: .9rem;
  line-height: 1;
  opacity: .5;
}

.qj-star:hover,
.qj-star.fav {
  opacity: 1;
  color: var(--gold,#C9A84C);
}

.qj-empty {
  padding: .7rem;
  text-align: left;
  font-size: .78rem;
  color: var(--muted,#8a7e6b);
  font-style: italic;
}

@media (max-width:760px) {
  #quick-jump-drop {
    right: -40px;
    width: 240px;
  }

}

/* ─── Topbar Notifications Bell ─── */

.topbar-notifications-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.topbar-notifications-icon-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.topbar-notifications-btn.has-alerts .line-icon {
  color: var(--forest, #2D4A3E);
}

.topbar-notifications-badge {
  position: absolute;
  top: -6px;
  right: -8px;
  min-width: 1.05rem;
  height: 1.05rem;
  padding: 0 .22rem;
  border-radius: 999px;
  background: var(--danger, #b54a4a);
  color: #fff;
  font-size: .58rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.05rem;
  text-align: center;
  box-shadow: 0 0 0 2px var(--ivory, #f5f0e6);
  pointer-events: none;
}

.topbar-notifications-badge[hidden],
.topbar-notifications-badge.is-empty {
  display: none !important;
}

.topbar-notifications-drop {
  display: none;
  position: absolute;
  top: calc(100% + 6px);
  left: 100%;
  right: auto;
  width: 300px;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 8px;
  box-shadow: 0 10px 30px rgba(54,39,20,.13);
  z-index: 7100;
  padding: 0;
}

.topbar-notifications-drop-scroll {
  max-height: 420px;
  overflow-y: auto;
  padding: .45rem 0;
  scrollbar-width: thin;
  scrollbar-color: rgba(54,39,20,.28) transparent;
}

.topbar-notifications-drop-scroll::-webkit-scrollbar {
  width: 8px;
}

.topbar-notifications-drop-scroll::-webkit-scrollbar-track {
  background: transparent;
  margin-block: 7px;
  margin-inline-end: 2px;
}

.topbar-notifications-drop-scroll::-webkit-scrollbar-thumb {
  background-color: rgba(54,39,20,.24);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}

.topbar-notifications-drop-scroll::-webkit-scrollbar-thumb:hover {
  background-color: rgba(54,39,20,.38);
}

.topbar-notifications-drop-scroll::-webkit-scrollbar-corner {
  background: transparent;
}

.topbar-notifications-drop.open {
  display: block;
}

.tb-notif-section + .tb-notif-section {
  margin-top: .25rem;
  padding-top: .25rem;
  border-top: 1px solid var(--border,#d4cfc6);
}

.tb-notif-section-head {
  padding: .2rem .75rem .35rem;
  font-size: .65rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted,#8a7e6b);
  font-weight: 700;
}

.tb-notif-item {
  display: flex;
  align-items: flex-start;
  gap: .55rem;
  width: 100%;
  padding: .5rem .75rem;
  border: none;
  background: none;
  cursor: pointer;
  text-align: left;
  font-size: .8rem;
  color: var(--charcoal,#3b3228);
  transition: background .1s;
}

.tb-notif-item:hover {
  background: var(--ivory-dk,#e7e0d3);
}

.tb-notif-item.urgent .tb-notif-item-icon {
  background: rgba(181,74,74,.12);
  color: var(--danger, #b54a4a);
}

.tb-notif-item-icon {
  flex: 0 0 auto;
  width: 1.35rem;
  height: 1.35rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(201,168,76,.14);
  color: var(--gold,#C9A84C);
  font-size: .72rem;
  font-weight: 800;
  line-height: 1;
}

.tb-notif-item-copy {
  flex: 1;
  min-width: 0;
}

.tb-notif-item-copy strong {
  display: block;
  font-size: .8rem;
  line-height: 1.2;
  color: var(--forest);
  margin-bottom: .12rem;
}

.tb-notif-item-copy span {
  display: block;
  font-size: .74rem;
  line-height: 1.35;
  color: var(--muted,#8a7e6b);
}

.tb-notif-later {
  flex: 0 0 auto;
  align-self: center;
  background: none;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 999px;
  padding: .18rem .55rem;
  font-size: .68rem;
  font-weight: 600;
  color: var(--muted,#8a7e6b);
  cursor: pointer;
}

.tb-notif-later:hover {
  background: var(--ivory-dk,#e7e0d3);
  color: var(--forest);
}

.tb-notif-empty {
  padding: .55rem .75rem;
  font-size: .76rem;
  color: var(--muted,#8a7e6b);
  font-style: italic;
}

@media (max-width:760px) {
  .topbar-notifications-drop {
    width: 260px;
    max-width: min(300px, calc(100vw - 1rem));
  }
}

/* ─── Smart Calendar Conflict Warnings (Step 3.2) ─── */

#smart-conflicts .cf-row {
  display: flex;
  align-items: flex-start;
  gap: .6rem;
  padding: .5rem .55rem;
  border-radius: 8px;
  background: rgba(179,64,47,.06);
  border: 1px solid rgba(179,64,47,.15);
  margin-bottom: .45rem;
  font-size: .78rem;
}

#smart-conflicts .cf-icon {
  flex: 0 0 auto;
  color: var(--red,#b3402f);
  margin-top: .1rem;
}

#smart-conflicts .cf-icon svg {
  width: 1rem;
  height: 1rem;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#smart-conflicts .cf-body {
  flex: 1;
  min-width: 0;
}

#smart-conflicts .cf-label {
  font-weight: 600;
  color: var(--charcoal,#3b3228);
}

#smart-conflicts .cf-detail {
  color: var(--muted,#8a7e6b);
  font-size: .72rem;
  margin-top: .1rem;
}

#smart-conflicts .cf-events {
  display: flex;
  flex-wrap: wrap;
  gap: .3rem;
  margin-top: .3rem;
}

#smart-conflicts .cf-chip {
  font-size: .68rem;
  padding: .15rem .45rem;
  border-radius: 6px;
  background: rgba(179,64,47,.1);
  color: var(--charcoal,#3b3228);
  cursor: pointer;
  white-space: nowrap;
}

#smart-conflicts .cf-chip:hover {
  background: rgba(179,64,47,.2);
}

#smart-conflicts .cf-none {
  text-align: center;
  padding: .5rem;
  color: var(--muted,#8a7e6b);
  font-size: .78rem;
  font-style: italic;
}

.smart-day.has-conflict .smart-day-number b {
  position: relative;
}

.smart-day.has-conflict .smart-day-number b::after {
  content: '';
  position: absolute;
  top: -2px;
  right: -5px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--red,#b3402f);
}

/* ─── Custom Theme Builder modal (Batch 9) ─── */

.tb-overlay {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(30,24,16,.5);
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.tb-overlay.open {
  display: flex;
}

.tb-modal {
  background: var(--ivory,#F7F3ED);
  border: 1px solid var(--border,#d4cfc6);
  max-width: 560px;
  width: 100%;
  max-height: 90vh;
  overflow: auto;
  padding: 1.6rem 1.7rem;
  box-shadow: 0 24px 60px rgba(40,28,12,.3);
}

.tb-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.tb-head h3 {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest,#2D4A3E);
  margin: 0;
  font-size: 1.3rem;
}

.tb-close {
  background: none;
  border: none;
  font-size: 1.1rem;
  color: var(--muted,#8a7e6b);
  cursor: pointer;
  line-height: 1;
}

.tb-sub {
  color: var(--muted,#8a7e6b);
  font-size: .82rem;
  line-height: 1.5;
  margin: .4rem 0 1.1rem;
}

.tb-field {
  display: flex;
  flex-direction: column;
  gap: .3rem;
  margin-bottom: 1.1rem;
}

.tb-field span {
  font-size: .68rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted,#8a7e6b);
  font-weight: 700;
}

.tb-field input[type="text"] {
  border: 1px solid var(--border,#d4cfc6);
  padding: .5rem .65rem;
  font: inherit;
  font-size: .9rem;
  background: #fff;
  color: var(--charcoal,#3b3228);
}

.tb-colors {
  display: grid;
  grid-template-columns: repeat(5,1fr);
  gap: .6rem;
  margin-bottom: 1.2rem;
}

.tb-color {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .4rem;
  text-align: center;
}

.tb-color input[type="color"] {
  width: 100%;
  height: 48px;
  border: 1px solid var(--border,#d4cfc6);
  padding: 0;
  background: none;
  cursor: pointer;
}

.tb-color span {
  font-size: .66rem;
  color: var(--forest,#2D4A3E);
  font-weight: 700;
  line-height: 1.3;
}

.tb-color span em {
  font-style: normal;
  font-weight: 400;
  color: var(--muted,#8a7e6b);
  font-size: .6rem;
}

.tb-preview {
  margin-bottom: 1rem;
}

.tb-prev-card {
  display: flex;
  align-items: center;
  gap: .6rem;
  flex-wrap: wrap;
  border: 1px solid;
  padding: .85rem 1rem;
}

.tb-prev-title {
  font-family: var(--font-serif,Georgia,serif);
  font-size: 1.05rem;
  font-weight: 700;
  margin-right: auto;
}

.tb-prev-chip {
  font-size: .7rem;
  font-weight: 700;
  padding: .2rem .6rem;
  border-radius: 2px;
}

.tb-saved {
  margin-bottom: 1.1rem;
}

.tb-saved-head {
  font-size: .66rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted,#8a7e6b);
  font-weight: 700;
  margin-bottom: .5rem;
}

.tb-saved-row {
  display: flex;
  align-items: center;
  gap: .6rem;
  padding: .4rem .1rem;
  border-bottom: 1px solid var(--gold-pale,#f5edd4);
}

.tb-saved-name {
  flex: 1;
  font-size: .84rem;
  color: var(--forest,#2D4A3E);
  font-weight: 600;
}

.tb-saved-apply,
.tb-saved-edit {
  background: none;
  border: 1px solid var(--forest,#2D4A3E);
  color: var(--forest,#2D4A3E);
  padding: .22rem .6rem;
  font-size: .72rem;
  font-weight: 600;
  cursor: pointer;
}
.tb-saved-edit {
  border-color: var(--gold,#B89968);
  color: var(--gold,#B89968);
}

.tb-saved-del {
  background: none;
  border: none;
  color: var(--muted,#8a7e6b);
  cursor: pointer;
  font-size: .85rem;
}

.tb-actions {
  display: flex;
  justify-content: flex-end;
  gap: .6rem;
}

@media (max-width:540px) {
  .tb-colors {
    grid-template-columns: repeat(3,1fr);
  }

}

/* ─── Email Templates (Step 4.1) ─── */

#panel-emails .et-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1.2rem;
}

#panel-emails .et-header h2 {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest,#2D4A3E);
  margin: 0;
  font-size: 1.35rem;
}

#panel-emails .et-header p {
  margin: .2rem 0 0;
  color: var(--muted,#8a7e6b);
  font-size: .82rem;
  line-height: 1.4;
}

/* Two-column workspace: category rail (left) + cards (right) */

#panel-emails .et-layout {
  display: grid;
  grid-template-columns: 230px minmax(0,1fr);
  gap: 1.5rem;
  align-items: start;
}

#panel-emails .et-sidebar {
  position: sticky;
  top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
}

#panel-emails .et-sidebar-head {
  font-size: .66rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--gold,#C9A84C);
  font-weight: 800;
}

/* In the rail the category buttons stack vertically and fill the width */

#panel-emails .et-cat-tabs {
  display: flex;
  flex-direction: column;
  gap: .35rem;
  margin: 0;
}

#panel-emails .et-sidebar .et-cat-tab {
  width: 100%;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* Available Merge Fields card */

#panel-emails .et-merge-card {
  background: var(--ivory,#F7F3ED);
  border: 1px solid var(--border,#d4cfc6);
  padding: .9rem 1rem;
}

#panel-emails .et-merge-card h3 {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest,#2D4A3E);
  font-size: .95rem;
  margin: 0 0 .25rem;
}

#panel-emails .et-merge-card p {
  margin: 0 0 .7rem;
  font-size: .72rem;
  color: var(--muted,#8a7e6b);
