  border-radius: 7px;
  padding: .38rem .5rem;
  font: inherit;
  font-size: .82rem;
  background: #fff;
}

#panel-logistics .log-form-grid textarea {
  min-height: 60px;
  resize: vertical;
}

/* Quiet utility panel — curated questions (Vendors tracker + Logistics compare) */
.log-questions {
  margin: .85rem 0 1.15rem;
  padding: 1rem 0 1.1rem;
  border: none;
  border-top: 1px solid color-mix(in srgb, var(--forest,#2D4A3E) 22%, var(--border,#d4cfc6));
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.log-questions h4 {
  margin: 0 0 .75rem;
  padding: 0 0 .55rem;
  text-align: left;
  font-family: var(--font-sans);
  font-size: .95rem;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: .01em;
  color: var(--forest,#2D4A3E);
  border-bottom: 1.5px solid color-mix(in srgb, var(--forest,#2D4A3E) 55%, transparent);
}

.log-questions ol {
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: log-q;
  display: grid;
  gap: 0;
}

.log-questions li {
  position: relative;
  counter-increment: log-q;
  margin: 0;
  padding: .55rem 0 .55rem 1.65rem;
  font-family: var(--font-sans);
  font-size: .84rem;
  line-height: 1.45;
  color: var(--charcoal,#3b3228);
  background: transparent;
  border-radius: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--border,#d4cfc6) 85%, transparent);
}

.log-questions li:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.log-questions li::before {
  content: counter(log-q) ".";
  position: absolute;
  left: 0;
  top: .55rem;
  font-family: var(--font-sans);
  font-size: .78rem;
  font-weight: 500;
  letter-spacing: 0;
  color: color-mix(in srgb, var(--forest,#2D4A3E) 70%, var(--muted,#8a7e6b));
  line-height: 1.45;
  font-variant-numeric: tabular-nums;
}

#panel-vendors .log-questions {
  margin-top: .35rem;
  margin-bottom: 1.2rem;
}

#panel-logistics .log-map-links {
  display: inline-flex;
  gap: .3rem;
}

#panel-logistics .log-map-links a {
  font-size: .68rem;
  padding: .2rem .45rem;
  border-radius: 5px;
  background: var(--gold-pale,#f5edd4);
  color: var(--forest,#2D4A3E);
  text-decoration: none;
  font-weight: 600;
}

#panel-logistics .log-map-links a:hover {
  background: var(--gold,#C9A84C);
  color: #fff;
}

@media(max-width:760px) {
  #panel-logistics .log-form-grid {
    grid-template-columns: 1fr 1fr;
  }


}

/* ─── Reflective / Relational Pages (Step 6.1) ─── */

#panel-reflect .rfl-tabs {
  display: flex;
  gap: .4rem;
  margin: 1rem 0;
  flex-wrap: wrap;
}

#panel-reflect .rfl-tab {
  background: none;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 8px;
  padding: .4rem .8rem;
  cursor: pointer;
  font-size: .78rem;
  font-weight: 600;
  color: var(--muted,#8a7e6b);
}

#panel-reflect .rfl-tab:hover {
  border-color: var(--gold,#C9A84C);
  color: var(--forest,#2D4A3E);
}

#panel-reflect .rfl-tab.active {
  background: var(--forest,#2D4A3E);
  border-color: var(--forest,#2D4A3E);
  color: #fff;
}

#panel-reflect .rfl-subtabs {
  display: flex;
  gap: .45rem;
  flex-wrap: wrap;
  margin: .85rem 0 1rem;
}

#panel-reflect .rfl-subtab {
  border: 1px solid rgba(196,165,118,.34);
  background: #fffdf9;
  color: var(--forest,#2D4A3E);
  padding: .42rem .75rem;
  cursor: pointer;
  font: inherit;
  font-size: .78rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .06em;
  border-radius: 0;
}

#panel-reflect .rfl-subtab.active {
  background: var(--forest,#2D4A3E);
  border-color: var(--forest,#2D4A3E);
  color: #fff;
}

#panel-reflect .rfl-card {
  background: var(--ivory,#F7F3ED);
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 12px;
  padding: 1.2rem 1.3rem;
  box-shadow: 0 4px 14px rgba(54,39,20,.05);
  margin-bottom: 1rem;
}

#panel-reflect .rfl-card h2 {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest,#2D4A3E);
  font-size: 1.2rem;
  margin: 0 0 .3rem;
}

#panel-reflect .rfl-card .rfl-intro {
  color: var(--muted,#8a7e6b);
  font-size: .82rem;
  line-height: 1.45;
  margin-bottom: .8rem;
}

#panel-reflect .rfl-card hr.gold {
  border: none;
  border-top: 1px solid var(--gold-pale,#f5edd4);
  margin: .7rem 0;
}

#panel-reflect .rfl-field {
  margin-bottom: .8rem;
}

#panel-reflect .rfl-field label {
  display: block;
  font-family: var(--font-serif,Georgia,serif);
  font-size: .88rem;
  color: var(--forest,#2D4A3E);
  margin-bottom: .3rem;
  font-weight: 600;
}

#panel-reflect .rfl-field input {
  width: 100%;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 8px;
  padding: .45rem .6rem;
  font: inherit;
  font-size: .85rem;
  background: #fff;
  color: var(--charcoal,#3b3228);
}

#panel-reflect .rfl-field textarea {
  width: 100%;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 8px;
  padding: .5rem .6rem;
  font: inherit;
  font-size: .82rem;
  background: #fff;
  color: var(--charcoal,#3b3228);
  min-height: 80px;
  resize: vertical;
  line-height: 1.5;
}

#panel-reflect .rfl-rhythm-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(200px,1fr));
  gap: .6rem;
  margin-bottom: .8rem;
}

#panel-reflect .rfl-rhythm-grid label {
  font-size: .78rem;
  color: var(--forest,#2D4A3E);
  font-weight: 600;
  display: block;
  margin-bottom: .2rem;
}

#panel-reflect .rfl-rhythm-grid input {
  width: 100%;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 8px;
  padding: .4rem .55rem;
  font: inherit;
  font-size: .82rem;
  background: #fff;
}


#panel-reflect .hc-stats {
  display: flex;
  gap: .8rem;
  flex-wrap: wrap;
  margin-bottom: .8rem;
}

#panel-reflect .hc-stat {
  font-size: .78rem;
  color: var(--muted,#8a7e6b);
}

#panel-reflect .hc-stat b {
  color: var(--forest,#2D4A3E);
}

@media(max-width:760px) {
  #panel-reflect .rfl-rhythm-grid {
    grid-template-columns: 1fr 1fr;
  }

}

/* ─── Backup Reminder banner (Step 2.3) ─── */

#backup-reminder {
  display: none;
  background: linear-gradient(135deg,#fdf6e3 0%,#fef9ef 100%);
  border: 1px solid var(--gold-lt,#d8b778);
  border-left: 4px solid var(--gold,#C9A84C);
  border-radius: 12px;
  padding: .9rem 1.1rem;
  margin-top: 1.1rem;
  box-shadow: 0 4px 12px rgba(54,39,20,.06);
}

#backup-reminder .br-inner {
  display: flex;
  align-items: center;
  gap: .85rem;
  flex-wrap: wrap;
}

#backup-reminder .br-icon {
  flex: 0 0 auto;
  width: 2.2rem;
  height: 2.2rem;
  border-radius: 50%;
  background: var(--gold-pale,#f5edd4);
  display: flex;
  align-items: center;
  justify-content: center;
}

#backup-reminder .br-icon svg {
  width: 1.15rem;
  height: 1.15rem;
  stroke: var(--gold,#C9A84C);
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#backup-reminder .br-body {
  flex: 1;
  min-width: 160px;
}

#backup-reminder .br-title {
  font-family: var(--font-serif,Georgia,serif);
  color: var(--forest,#2D4A3E);
  font-size: .92rem;
  font-weight: 700;
  margin: 0 0 .15rem;
}

#backup-reminder .br-msg {
  font-size: .78rem;
  color: var(--muted,#8a7e6b);
  line-height: 1.45;
}

#backup-reminder .br-msg b {
  color: var(--red,#b3402f);
  font-weight: 600;
}

#backup-reminder .br-actions {
  display: flex;
  gap: .5rem;
  align-items: center;
  flex-wrap: wrap;
}

#backup-reminder .br-backup-btn {
  background: var(--gold,#C9A84C);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: .45rem .95rem;
  font-weight: 700;
  font-size: .78rem;
  cursor: pointer;
  white-space: nowrap;
}

#backup-reminder .br-backup-btn:hover {
  filter: brightness(1.08);
}

#backup-reminder .br-later {
  background: none;
  border: none;
  color: var(--muted,#8a7e6b);
  font-size: .72rem;
  cursor: pointer;
  text-decoration: underline;
  padding: 0;
}

#backup-reminder .br-later:hover {
  color: var(--charcoal,#3b3228);
}

/* ─── Phase 5: backup education, essentials hub, focus presets, blended-family prompts ─── */
.backup-education-callout {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: .85rem 1rem;
  margin: 0 0 1.1rem;
  padding: .95rem 1.05rem;
  border: 1px solid color-mix(in srgb, var(--gold,#B89968) 45%, var(--border,#d4cfc6));
  border-radius: 14px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--gold-pale,#EFE8DD) 80%, #fff), #fff);
  color: var(--charcoal,#3b3228);
  text-align: left;
}
.backup-education-callout .bec-icon {
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--forest,#2D4A3E);
  color: #fff;
}
.backup-education-callout .bec-icon svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
}
.backup-education-callout .bec-body { flex: 1 1 220px; min-width: 0; }
.backup-education-callout .bec-title {
  font-family: var(--font-serif,Georgia,serif);
  font-size: 1.02rem;
  color: var(--forest,#2D4A3E);
  margin-bottom: .25rem;
}
.backup-education-callout p {
  margin: 0;
  font-size: .82rem;
  line-height: 1.5;
  color: var(--muted,#8a7e6b);
}
.backup-education-callout .bec-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .45rem;
  align-items: center;
}
.essentials-hub-card {
  margin: 0 0 1.15rem;
  padding: 1rem 1.1rem;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 16px;
  background: var(--ivory,#F7F3ED);
  color: var(--charcoal,#3b3228);
  text-align: left;
}
.essentials-hub-card.active {
  border-color: color-mix(in srgb, var(--forest,#2D4A3E) 35%, var(--border,#d4cfc6));
  box-shadow: 0 8px 22px rgba(45,74,62,.08);
}
.essentials-hub-card.compact { margin-bottom: 1rem; }
.ess-hub-head {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem 1rem;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: .85rem;
}
.ess-hub-kicker {
  font-size: .68rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--gold,#B89968);
  font-weight: 700;
}
.ess-hub-title {
  font-family: var(--font-serif,Georgia,serif);
  font-size: 1.2rem;
  color: var(--forest,#2D4A3E);
  margin: .15rem 0;
}
.ess-hub-lead {
  margin: 0;
  font-size: .8rem;
  line-height: 1.45;
  color: var(--muted,#8a7e6b);
  max-width: 58ch;
}
.ess-hub-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(150px,1fr));
  gap: .55rem;
}
.ess-hub-link {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: .15rem;
  padding: .65rem .75rem;
  border: 1px solid var(--border,#d4cfc6);
  border-radius: 10px;
  background: #fff;
  cursor: pointer;
  text-align: left;
  transition: border-color .12s, background .12s;
}
.ess-hub-link:hover {
  border-color: var(--gold,#B89968);
  background: color-mix(in srgb, var(--gold-pale,#EFE8DD) 55%, #fff);
}
.ess-hub-label {
  font-size: .82rem;
  font-weight: 600;
  color: var(--forest,#2D4A3E);
}
.ess-hub-note {
  font-size: .72rem;
  color: var(--muted,#8a7e6b);
  line-height: 1.35;
}
.focus-preset-select {
  min-width: 9.5rem;
  max-width: 12rem;
}
.essentials-view-btn.is-active-essentials {
  border-color: var(--forest,#2D4A3E);
  background: color-mix(in srgb, var(--forest,#2D4A3E) 10%, #fff);
  color: var(--forest,#2D4A3E);
  font-weight: 600;
}
.blended-family-prompt {
  margin: 0 0 1rem;
  padding: .85rem 1rem;
  border: 1px solid color-mix(in srgb, var(--gold,#B89968) 35%, var(--border,#d4cfc6));
  border-radius: 12px;
  background: color-mix(in srgb, var(--gold-pale,#EFE8DD) 55%, #fff);
  color: var(--charcoal,#3b3228);
}
.bfp-kicker {
  font-size: .66rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--gold,#B89968);
  font-weight: 700;
  margin-bottom: .2rem;
}
.bfp-title {
  display: block;
  font-family: var(--font-serif,Georgia,serif);
  font-size: 1rem;
  color: var(--forest,#2D4A3E);
  margin-bottom: .35rem;
}
.blended-family-prompt p {
  margin: 0 0 .65rem;
  font-size: .82rem;
  line-height: 1.5;
  color: var(--muted,#8a7e6b);
}
.bfp-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .45rem;
}
.m-btn-quiet {
  background: transparent;
  border-color: transparent;
  color: var(--muted,#8a7e6b);
  text-decoration: underline;
}
body.editorial-v4.dark-mode .backup-education-callout,
body.editorial-v4.dark-mode .essentials-hub-card,
body.editorial-v4.dark-mode .blended-family-prompt {
  background: #1a1a1a !important;
  color: #e6e6e6 !important;
  border-color: #2e2e2e !important;
}
body.editorial-v4.dark-mode .log-questions {
  background: transparent;
  border-top-color: #2e2e2e;
  box-shadow: none;
}
body.editorial-v4.dark-mode .log-questions h4 {
  color: var(--text,#e8e4dc);
  border-bottom-color: #2e2e2e;
}
body.editorial-v4.dark-mode .log-questions li {
  background: transparent;
  color: color-mix(in srgb, var(--text,#e8e4dc) 90%, transparent);
  border-bottom-color: color-mix(in srgb, var(--border,#444) 70%, transparent);
}
body.editorial-v4.dark-mode .log-questions li::before {
  color: color-mix(in srgb, var(--text,#e8e4dc) 55%, var(--muted,#8a7e6b));
}
body.editorial-v4.dark-mode .ess-hub-link {
  background: color-mix(in srgb, var(--card,#1e1e1e) 92%, #000);
  border-color: var(--border,#444);
}
body.editorial-v4.dark-mode .ess-hub-label,
body.editorial-v4.dark-mode .bfp-title,
body.editorial-v4.dark-mode .backup-education-callout .bec-title,
body.editorial-v4.dark-mode .ess-hub-title {
  color: var(--text,#e8e4dc);
}
body.editorial-v4.dark-mode .ess-hub-note,
body.editorial-v4.dark-mode .blended-family-prompt p,
body.editorial-v4.dark-mode .backup-education-callout p,
body.editorial-v4.dark-mode .ess-hub-lead {
  color: color-mix(in srgb, var(--text,#e8e4dc) 72%, transparent);
}

/* ─── MAIN ─── */

#main {
  flex: 1;
  min-width: 0;
  padding: 1.75rem var(--planner-page-gutter);
  overflow-y: visible;
}

.panel {
  display: none;
}

.panel.active {
  display: block;
}

.page-title {
  font-family: var(--font-serif);
  font-size: 1.9rem;
  color: var(--forest);
  margin-bottom: .25rem;
  line-height: 1.1;
}

.page-subtitle {
  font-size: .82rem;
  color: var(--muted);
  margin-bottom: 1.5rem;
  letter-spacing: .3px;
  font-style: italic;
}

/* ─── CARDS ─── */

.card {
  background: #fff;
  border-radius: var(--radius);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow);
  margin-bottom: 1.25rem;
  border: 1px solid var(--border);
}

.card-title {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  color: var(--forest);
  margin-bottom: .9rem;
  padding-bottom: .5rem;
  border-bottom: 1px solid var(--border);
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(160px,1fr));
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.stat-card {
  background: #fff;
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: .3rem;
}

.stat-label {
  font-size: .7rem;
  letter-spacing: 1.8px;
  text-transform: uppercase;
  color: var(--muted);
}

.stat-val {
  font-family: var(--font-serif);
  font-size: 1.7rem;
  color: var(--forest);
}

.stat-sub {
  font-size: .75rem;
  color: var(--muted);
}

.stat-card.warn .stat-val {
  color: var(--amber);
}

.stat-card.danger .stat-val {
  color: var(--red);
}

.stat-card.ok .stat-val {
  color: var(--green);
}

/* ─── PROGRESS BAR ─── */

.progress-wrap {
  margin: .3rem 0 .15rem;
}

.progress-label {
  display: flex;
  justify-content: space-between;
  font-size: .75rem;
  color: var(--muted);
  margin-bottom: .25rem;
}

.progress-bar {
  height: 7px;
  background: var(--ivory-dk);
  border-radius: 4px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  border-radius: 4px;
  transition: width .4s;
}

.fill-gold {
  background: var(--gold);
}

.fill-forest {
  background: var(--forest);
}

.fill-green {
  background: var(--green);
}

.fill-red {
  background: var(--red);
}

/* ─── CHARTS ─── */

.chart-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
  margin-bottom: 1.25rem;
}

.chart-wrap {
  background: #fff;
  border-radius: var(--radius);
  padding: 1.25rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
}

.chart-title {
  font-size: .82rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: .9rem;
}

canvas {
  display: block;
  width: 100% !important;
  max-height: 220px;
}

/* ─── TABLE ─── */

.tbl-wrap {
  overflow-x: auto;
  margin-top: .75rem;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: .85rem;
}

th {
  background: var(--ivory-dk);
  font-size: .7rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--muted);
  padding: .55rem .75rem;
  text-align: left;
  white-space: nowrap;
  border-bottom: 1px solid var(--border);
}

td {
  padding: .55rem .75rem;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}

tr:last-child td {
  border-bottom: none;
}

tr:hover td {
  background: var(--gold-pale);
}

td input,
td select {
  border: none;
  background: transparent;
  padding: .2rem .3rem;
}

td input:focus,
td select:focus {
  background: #fff;
  border: 1px solid var(--gold);
}

.del-btn {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 1rem;
  padding: .2rem .4rem;
  border-radius: 4px;
}

.del-btn:hover {
  color: var(--red);
  background: var(--red-pale);
}

.add-row-btn {
  margin-top: .75rem;
  background: transparent;
  border: 1px dashed var(--border);
  color: var(--muted);
  border-radius: 5px;
  padding: .45rem 1rem;
  font-size: .82rem;
  width: 100%;
  transition: all .15s;
}

.add-row-btn:hover {
  border-color: var(--gold);
  color: var(--forest);
  background: var(--gold-pale);
}

/* ─── STATUS BADGES ─── */

.badge {
  display: inline-block;
  padding: .15rem .55rem;
  border-radius: 20px;
  font-size: .72rem;
  font-weight: 600;
  white-space: nowrap;
}

.badge-green {
  background: var(--green-pale);
  color: var(--green);
}

.badge-amber {
  background: var(--amber-pale);
  color: var(--amber);
}

.badge-red {
  background: var(--red-pale);
  color: var(--red);
}

.badge-grey {
  background: var(--ivory-dk);
  color: var(--muted);
}

.badge-forest {
  background: color-mix(in srgb, var(--forest) 8%, #fff);
  color: var(--forest);
}

/* ─── FORM GRID ─── */

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: .85rem;
}

.form-grid.cols-3 {
  grid-template-columns: 1fr 1fr 1fr;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: .3rem;
}

.form-group.span-2 {
  grid-column: span 2;
}

.form-group.span-3 {
  grid-column: span 3;
}

label {
  font-size: .75rem;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: var(--muted);
}

.form-actions {
  display: flex;
  gap: .6rem;
  margin-top: 1rem;
}

/* ─── COUNTDOWN ─── */

.countdown-display {
  text-align: left;
  padding: 1.5rem;
  font-family: var(--font-serif);
  color: var(--forest);
}

.countdown-display .days {
  font-size: 3.5rem;
  line-height: 1;
}

.countdown-display .label {
  font-size: .85rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
}

.countdown-display .date {
  font-size: 1rem;
  margin-top: .4rem;
  font-style: italic;
  color: var(--gold);
}

/* ─── EMPTY STATE ─── */

.empty-state {
  text-align: left;
  padding: 2.5rem 1rem;
  color: var(--muted);
  font-style: italic;
}

.empty-state p {
  margin-top: .5rem;
  font-size: .85rem;
}

/* ─── Friendly table empty states (starter messages + add button) ─── */

.table-empty-row td {
  background: transparent !important;
  border: none !important;
}

.table-empty-state {
  text-align: left;
  padding: 2.2rem 1rem;
  color: #7a7268;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: .5rem;
}

.table-empty-state .tes-icon {
  width: 2.5rem;
  height: 2.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--gold-pale);
  color: var(--gold);
}

.table-empty-state .tes-icon svg {
  width: 1.35rem;
  height: 1.35rem;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.table-empty-state .tes-title {
  font-family: var(--font-serif,Georgia,serif);
  font-size: 1.08rem;
  color: var(--forest);
  font-weight: 600;
}

.table-empty-state .tes-msg {
  font-size: .86rem;
  max-width: 34rem;
  line-height: 1.5;
}

.table-empty-state .tes-actions {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
  justify-content: flex-start;
  margin-top: .35rem;
}

.table-empty-state .tes-btn {
  background: var(--forest);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: .5rem 1.1rem;
  font-size: .82rem;
  cursor: pointer;
  transition: background .12s;
}

.table-empty-state .tes-btn:hover {
  background: var(--forest-lt);
}

.table-empty-state .tes-btn-alt {
  background: transparent;
  color: var(--forest);
  border: 1px solid var(--gold);
}

.table-empty-state .tes-btn-alt:hover {
  background: var(--gold-pale);
}

/* ─── PRAYER / FAITH SECTIONS ─── */

.scripture-pull {
  background: var(--gold-pale);
  border-left: 3px solid var(--gold);
  padding: .8rem 1rem;
  border-radius: 0 5px 5px 0;
  margin: .75rem 0;
  font-family: var(--font-serif);
  font-style: italic;
  font-size: .95rem;
  color: var(--charcoal);
}

.scripture-ref {
  display: block;
  font-size: .75rem;
  font-style: normal;
  margin-top: .3rem;
  color: var(--muted);
  letter-spacing: 1px;
}

/* ─── SECTION DIVIDER ─── */

.section-divider {
  display: flex;
  align-items: center;
  gap: .8rem;
  margin: 1.5rem 0 1rem;
}

.section-divider span {
  font-size: .7rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}

.section-divider::before,
.section-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* ─── MODAL ─── */

.modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(42,42,42,.5);
  z-index: 1000;
  align-items: center;
  justify-content: center;
}

.modal-overlay.open {
  display: flex;
}

.modal {
  background: #fff;
  border-radius: var(--radius);
  padding: 2rem;
  max-width: 480px;
  width: 90%;
  box-shadow: 0 8px 40px rgba(0,0,0,.2);
}

.modal h3 {
  font-family: var(--font-serif);
  color: var(--forest);
  margin-bottom: .75rem;
}

.modal p {
  font-size: .875rem;
  color: var(--muted);
  margin-bottom: 1.25rem;
}

.modal .modal-actions {
  display: flex;
  gap: .6rem;
  justify-content: flex-end;
}

/* ─── NOTES ─── */

.notes-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.note-card {
  background: #fff;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  padding: 1rem;
}

.note-card label {
  display: block;
  margin-bottom: .4rem;
}

/* ════════════════════════════════════════════════
LUXURY EDITORIAL REDESIGN — dashboard
════════════════════════════════════════════════ */

body {
  background: radial-gradient(circle at 16% 8%, rgba(212,184,150,.30), transparent 30%), radial-gradient(circle at 90% 0%, rgba(45,74,62,.10), transparent 32%), linear-gradient(135deg, #FBF8F2 0%, #F4EEE6 48%, #EFE7DB 100%);
}

#topbar {
  background: var(--forest);
  background: linear-gradient(135deg, color-mix(in srgb, var(--forest) 72%, #000) 0%, var(--forest) 70%, color-mix(in srgb, var(--forest) 88%, #fff) 100%);
  padding: .95rem 1.65rem;
  border-bottom: 1px solid rgba(212,184,150,.30);
}

#topbar h1 {
  font-size: 1.38rem;
  letter-spacing: .7px;
}

#topbar .sub {
  color: rgba(249,247,244,.72);
}

.btn {
  border-radius: 999px;
  padding: .48rem .9rem;
  letter-spacing: .02em;
}

.btn svg,
.line-icon {
  width: 1.05em;
  height: 1.05em;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: 0 0 auto;
}

.btn-gold {
  background: linear-gradient(135deg, var(--gold), #C8A978);
}

#backup-banner {
  background: rgba(245,239,228,.78);
  backdrop-filter: blur(10px);
}

#sidebar {
  background: var(--forest-deep);
  background: linear-gradient(180deg, var(--forest-deep) 0%, var(--forest-deeper) 100%);
  border-right: 1px solid rgba(212,184,150,.25);
  box-shadow: 8px 0 30px rgba(45,74,62,.10);
}

.nav-label {
  color: rgba(212,184,150,.70);
  padding-top: .95rem;
}

.nav-item {
  color: rgba(249,247,244,.84);
  border-left-color: transparent;
}

.nav-item:hover {
  background: rgba(249,247,244,.06);
}

.nav-item.active {
  color: #FFFDF9;
  border-left-color: var(--gold-lt);
  background: linear-gradient(90deg, rgba(184,153,104,.28), rgba(249,247,244,.06));
}

.nav-icon {
  width: 1.25rem;
  height: 1.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--gold-lt);
}

.nav-icon svg {
  width: 1.05rem;
  height: 1.05rem;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#main {
  padding: 2.2rem var(--planner-page-gutter);
}

.page-title {
  font-size: clamp(2rem, 4vw, 3.45rem);
  letter-spacing: .02em;
  color: var(--forest);
}

.page-subtitle {
  font-size: .95rem;
}

.card,
.chart-wrap,
.stat-card {
  background: rgba(255,253,248,.92);
  border: 1px solid rgba(184,153,104,.28);
  box-shadow: 0 18px 48px rgba(42,42,42,.07);
}

.card-title {
  font-size: 1.35rem;
  letter-spacing: .03em;
}

.card-kicker,
.eyebrow {
  color: var(--gold);
  font-size: .72rem;
  letter-spacing: .23em;
  text-transform: uppercase;
  font-weight: 700;
}

.dash-hero {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  align-items: center;
  margin-bottom: 1.4rem;
  padding: clamp(1.35rem, 2.7vw, 2.6rem);
  border-radius: 28px;
  background: linear-gradient(135deg, rgba(255,253,248,.96), rgba(245,239,228,.88)), radial-gradient(circle at 100% 40%, rgba(45,74,62,.12), transparent 38%);
  border: 1px solid rgba(184,153,104,.32);
  box-shadow: 0 24px 70px rgba(45,74,62,.10);
}

.dash-hero .page-subtitle {
  max-width: 62ch;
  margin-bottom: 1rem;
}

.hero-photo-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .45rem;
}

.hero-photo {
  width: 150px;
  height: 150px;
  border-radius: 50%;
  border: 2px dashed var(--gold-lt);
  background-color: rgba(255,255,255,.55);
  background-size: cover;
  background-position: center;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  overflow: hidden;
  color: var(--gold);
  text-align: center;
  transition: border-color .2s, box-shadow .2s;
}

.hero-photo:hover {
  border-color: var(--gold);
  box-shadow: 0 6px 18px rgba(45,74,62,.16);
}

.hero-photo.has-photo {
  border-style: solid;
  border-color: var(--gold);
  cursor: grab;
  touch-action: none;
}

.hero-photo.has-photo:active {
  cursor: grabbing;
}

.hero-photo-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .35rem;
  padding: .6rem;
}

.hero-photo-placeholder svg {
  width: 30px;
  height: 30px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.hero-photo-placeholder span {
  font-size: .72rem;
  letter-spacing: .04em;
  line-height: 1.25;
}

.hero-photo-actions {
  display: flex;
  gap: .9rem;
}

.hero-photo-link {
  background: none;
  border: none;
  color: var(--muted);
  font-size: .72rem;
  cursor: pointer;
  text-decoration: underline;
  padding: 0;
  font-family: inherit;
}

.hero-photo-link:hover {
  color: var(--forest);
}

.hero-meta {
  display: flex;
  gap: .7rem;
  flex-wrap: wrap;
  margin-top: .9rem;
}

.meta-pill {
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  padding: .5rem .78rem;
  border-radius: 999px;
  border: 1px solid rgba(184,153,104,.28);
  background: rgba(255,255,255,.62);
  color: var(--forest);
  font-size: .82rem;
}

.dashboard-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 380px);
  gap: 1.4rem;
  align-items: start;
}

.dashboard-main,
.dashboard-aside {
  min-width: 0;
}

.dashboard-aside {
  display: grid;
  gap: 1.25rem;
  position: sticky;
  top: 110px;
}

.dash-stat-grid {
  grid-template-columns: repeat(4, minmax(150px, 1fr));
}

.stat-card {
  border-radius: 20px;
  padding: 1.05rem;
  gap: .42rem;
  position: relative;
  overflow: hidden;
}

.stat-card::after {
  content: '';
  position: absolute;
  inset: auto -20px -36px auto;
  width: 95px;
  height: 95px;
  background: radial-gradient(circle, rgba(184,153,104,.14), transparent 68%);
}

.stat-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .65rem;
}

.stat-icon {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--gold);
  background: var(--gold-pale);
  border: 1px solid rgba(184,153,104,.24);
}

.stat-icon svg,
.meta-pill svg,
.task-dot svg {
  width: 17px;
  height: 17px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.stat-val {
  font-size: 2rem;
  line-height: 1;
}

.progress-suite {
  border-radius: 24px;
}

.progress-list {
  display: grid;
  gap: .95rem;
}

.progress-row {
  display: grid;
  gap: .35rem;
}

.progress-row-top {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: baseline;
}

.progress-row-label {
  font-size: .78rem;
  letter-spacing: .13em;
  text-transform: uppercase;
  color: var(--forest);
  font-weight: 700;
}

.progress-row-sub {
  font-size: .78rem;
  color: var(--muted);
}

.progress-track {
  height: 8px;
  border-radius: 999px;
  background: rgba(45,74,62,.10);
  overflow: hidden;
  border: 1px solid rgba(184,153,104,.12);
}

.progress-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--forest), var(--gold));
}

.chart-row-luxury {
  margin-top: 1.25rem;
}

.chart-wrap {
  border-radius: 22px;
}

.chart-wrap canvas {
  cursor: pointer;
}

#chart-tooltip {
  position: fixed;
  z-index: 9999;
  pointer-events: none;
  display: none;
  background: var(--forest);
  color: #FFFDF9;
  padding: .45rem .65rem;
  border-radius: 8px;
  font-size: .78rem;
  line-height: 1.35;
  font-family: var(--font-sans);
  box-shadow: 0 4px 14px rgba(0,0,0,.2);
  white-space: nowrap;
}

#chart-tooltip strong {
  color: var(--gold-lt);
}

.chart-title {
  display: flex;
  align-items: center;
  gap: .45rem;
  color: var(--forest);
  font-weight: 700;
}

.countdown-card {
  text-align: left;
  border-radius: 28px;
  background: var(--forest);
  background: linear-gradient(160deg, color-mix(in srgb, var(--forest) 88%, #000), var(--forest) 58%, color-mix(in srgb, var(--forest) 76%, #000));
  color: #FFFDF9;
  border-color: rgba(212,184,150,.42);
}

.countdown-card .card-kicker {
  color: var(--gold-lt);
}

.countdown-display {
  color: inherit;
  padding: 1rem .5rem;
}

.countdown-display .days {
  display: block;
  font-size: clamp(3.5rem, 8vw, 5rem);
  line-height: 1.05;
  margin: .15rem 0 .35rem;
  color: var(--gold-lt) !important;
  letter-spacing: .02em;
}

.countdown-display .label {
  display: block;
  color: rgba(255,253,249,.76);
}

.countdown-display .date {
  color: var(--gold-lt);
}

.countdown-note {
  font-size: .75rem;
  color: rgba(255,253,249,.62);
  text-align: left;
  margin-top: .75rem;
  font-style: italic;
}

.next-up-card,
.scripture-card {
  border-radius: 24px;
}

.task-list {
  display: grid;
  gap: .7rem;
  margin-top: .75rem;
}

.task-item {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: .7rem;
  align-items: start;
  padding: .72rem;
  border: 1px solid rgba(184,153,104,.20);
  border-radius: 16px;
  background: rgba(249,247,244,.55);
}

.task-dot {
  width: 25px;
  height: 25px;
  border-radius: 50%;
  border: 1px solid rgba(184,153,104,.55);
  color: var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: .1rem;
}

.task-dot svg {
  width: 14px;
  height: 14px;
}

.task-title {
  font-family: var(--font-serif);
  font-size: 1.02rem;
  color: var(--forest);
}

.task-meta {
  font-size: .76rem;
  color: var(--muted);
  margin-top: .1rem;
}

.scripture-card blockquote {
  font-family: var(--font-serif);
  color: var(--forest);
  font-size: 1.28rem;
  line-height: 1.25;
  margin: .65rem 0;
}

.scripture-card cite {
  display: block;
  color: var(--gold);
  font-style: normal;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-size: .72rem;
}

.empty-dashboard-note {
  padding: 1rem;
  border: 1px dashed rgba(184,153,104,.35);
  border-radius: 16px;
  color: var(--muted);
  background: rgba(245,239,228,.45);
  font-style: italic;
}

/* Guest cost estimator */

.cost-summary {
  margin-top: 1rem;
  border-top: 1px solid var(--border);
  padding-top: .75rem;
  max-width: 420px;
}

.cost-line {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  font-size: .88rem;
  padding: .25rem 0;
  color: var(--charcoal);
}

.cost-line.cost-total {
  border-top: 1px solid var(--border);
  margin-top: .35rem;
  padding-top: .55rem;
  font-weight: 700;
  font-size: 1rem;
  color: var(--forest);
}

/* Table layout */

.tables-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.2rem;
}

/* Marriage license helper (Track 2) */
#marriage-license-card .ml-lead {
  font-size: .82rem;
  color: #6b645d;
  margin: 0 0 .8rem;
  line-height: 1.5;
}
#marriage-license-card .ml-hint {
  font-size: .82rem;
  color: #6b645d;
  background: var(--gold-pale, #f5efe4);
  border: 1px solid var(--gold-lt, #d4b896);
  border-radius: 10px;
  padding: .7rem .85rem;
  line-height: 1.5;
}
.ml-window {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: .6rem;
  margin: .3rem 0 .5rem;
}
.ml-window-item {
  border: 1px solid var(--gold-lt, #d4b896);
  border-radius: 10px;
  padding: .55rem .65rem;
  background: #fff;
}
.ml-window-item span {
  display: block;
  font-size: .64rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: #8a8177;
}
.ml-window-item b {
  display: block;
  font-size: 1rem;
  color: var(--forest, #2d4a3e);
  margin: .1rem 0;
}
.ml-window-item small { font-size: .68rem; color: #8a8177; }
.ml-window-item.ok { border-color: #8fb89d; background: #eef5ef; }
.ml-window-item.warn { border-color: #d9a441; background: #fbf3e4; }
.ml-window-item.warn b { color: #7a4f12; }
.ml-warn {
  font-size: .8rem;
  color: #7a4f12;
  background: #fbf3e4;
  border: 1px solid #d9a441;
  border-radius: 8px;
  padding: .5rem .7rem;
  margin-bottom: .5rem;
}
.ml-warn div { margin: .1rem 0; }
.ml-checks {
  display: flex;
  gap: 1.2rem;
  flex-wrap: wrap;
  margin-top: .8rem;
}
.ml-check {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  font-size: .84rem;
  color: #4a453e;
  cursor: pointer;
}

/* Seating capacity guardrails (Track 1.4) */
#seating-guardrails { display: grid; gap: .75rem; margin: 0 0 1.15rem; }
#seating-guardrails:empty { display: none; }
.seat-guard {
  border: 1px solid var(--gold-lt, #d4b896);
  border-radius: 12px;
  padding: .85rem 1rem;
  background: var(--ivory, #f9f7f4);
}
.seat-guard-head {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-weight: 600;
  font-size: .92rem;
}
.seat-guard-warn { border-color: #d9a441; background: #fbf3e4; color: #7a4f12; }
.seat-guard-info { border-color: var(--gold-lt, #d4b896); background: #fbf8f1; }
.seat-guard-ok { border-color: #8fb89d; background: #eef5ef; color: #2d4a3e; }
.seat-guard-list { margin: .5rem 0 .25rem; padding-left: 1.2rem; font-size: .85rem; }
.seat-guard-list li { margin: .15rem 0; }
.seat-guard-list em { font-style: normal; color: #b3402f; font-weight: 600; }
.seat-guard-note { margin: .35rem 0 0; font-size: .78rem; color: #6b645d; }
.seat-guard-chips { display: flex; flex-wrap: wrap; gap: .35rem; margin: .55rem 0 .3rem; }
.seat-guard-chip {
  font-size: .76rem;
  padding: .18rem .5rem;
  border-radius: 999px;
  background: #fff;
  border: 1px solid var(--gold-lt, #d4b896);
  color: #4a453e;
}
.seat-guard-chip.more { background: transparent; border-style: dashed; color: #6b645d; }
.seat-guard-btn {
  margin-top: .45rem;
  font: inherit;
  font-size: .82rem;
  cursor: pointer;
  border: 1px solid var(--forest, #2d4a3e);
  background: var(--forest, #2d4a3e);
  color: #fff;
  border-radius: 8px;
  padding: .4rem .8rem;
}
.seat-guard-btn:hover { background: var(--forest-lt, #3d6655); }

.table-card {
  display: flex;
  flex-direction: column;
  gap: .6rem;
}

.table-card-head {
  display: flex;
  align-items: center;
  gap: .5rem;
}

.table-name-input {
  flex: 1;
  font-family: var(--font-serif);
  font-size: 1.15rem;
  color: var(--forest);
  font-weight: 600;
  border: none;
  border-bottom: 1px solid transparent;
  background: transparent;
  padding: .1rem .15rem;
}

.table-name-input:hover,
.table-name-input:focus {
  border-bottom-color: var(--gold-lt);
  outline: none;
}

.table-seat-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  font-size: .82rem;
}

.table-count {
  font-weight: 700;
  color: var(--forest);
}

.table-count.over {
  color: var(--red, #A95D4E);
}

.table-cap {
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  gap: .35rem;
}

.table-cap input {
  width: 56px;
}

.table-placement {
  width: 100%;
  font-size: .85rem;
}

.table-guests {
  display: flex;
  flex-wrap: wrap;
  gap: .35rem;
  margin-top: .2rem;
}

.table-guest-chip {
  background: var(--gold-pale);
  border: 1px solid rgba(184,153,104,.3);
  color: var(--charcoal);
  border-radius: 999px;
  padding: .2rem .6rem;
  font-size: .78rem;
}

.table-guest-chip em {
  font-style: normal;
  color: var(--gold);
  font-size: .7rem;
}

.table-label-display {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  color: var(--forest);
  font-weight: 600;
}

.table-name-edit {
  display: block;
  font-size: .72rem;
  color: var(--muted);
  margin: -.2rem 0 .5rem;
}

.table-name-edit input {
  width: 100%;
  margin-top: .15rem;
}

#table-map {
  position: relative;
  width: 100%;
  min-width: 280px;
  min-height: 300px;
  max-width: 100%;
  border: 1px dashed rgba(184,153,104,.45);
  border-radius: 14px;
  background: repeating-linear-gradient(45deg, rgba(245,239,228,.35) 0 12px, transparent 12px 24px);
  overflow: hidden;
  resize: both;
}

.table-node {
  position: absolute;
  width: 96px;
  height: 96px;
  background: var(--forest);
  color: #FFFDF9;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: grab;
  box-shadow: 0 4px 12px rgba(45,74,62,.25);
  user-select: none;
  touch-action: none;
  padding: .3rem;
  text-align: center;
}

.table-node.circle {
  border-radius: 50%;
}

.table-node.rect {
  border-radius: 12px;
  width: 140px;
  height: 84px;
}

.table-node.rect.vert {
  width: 84px;
  height: 140px;
}

.table-node.over {
  background: #A95D4E;
}

.table-node.dragging {
  cursor: grabbing;
  opacity: .9;
  box-shadow: 0 8px 22px rgba(45,74,62,.4);
}

.table-node .tn-controls {
  display: flex;
  gap: 4px;
  justify-content: center;
  margin-bottom: 3px;
}

.table-node .tn-shape,
.table-node .tn-rotate {
  background: rgba(255,255,255,.2);
  border: none;
  color: #FFFDF9;
  width: 20px;
  height: 18px;
  border-radius: 5px;
  font-size: .72rem;
  line-height: 1;
  cursor: pointer;
}

.table-node .tn-shape:hover,
.table-node .tn-rotate:hover {
  background: rgba(255,255,255,.4);
}

.table-node .tn-label {
  font-family: var(--font-serif);
  font-size: .9rem;
  line-height: 1.1;
}

.table-node .tn-count {
  font-size: .72rem;
  color: var(--gold-lt);
  margin-top: .15rem;
}

.table-empty {
  color: var(--muted);
  font-style: italic;
  font-size: .82rem;
}

/* FAQ */

.faq-item {
  margin-bottom: 1rem;
}

.faq-q {
  font-family: var(--font-serif);
  font-size: 1.12rem;
  color: var(--forest);
  font-weight: 600;
  margin-bottom: .4rem;
}

.faq-a {
  font-size: .92rem;
  line-height: 1.65;
  color: var(--charcoal);
}

/* Bulk row selection */

.sel-col {
  width: 34px;
  text-align: center;
}

.bulk-bar {
  display: flex;
  flex-direction: column;
  gap: .45rem;
  margin-bottom: .7rem;
  font-size: .82rem;
  background: var(--gold-pale);
  border: 1px solid rgba(184,153,104,.28);
  border-radius: 10px;
  padding: .6rem .75rem;
}

.bulk-head {
  display: flex;
  align-items: center;
  gap: .7rem;
  flex-wrap: wrap;
}

.bulk-head strong {
  color: var(--forest);
  letter-spacing: .04em;
}

.bulk-count {
  color: var(--muted);
}

.bulk-crits {
  display: flex;
  flex-wrap: wrap;
  gap: .4rem .9rem;
}

/* Integrated bulk-edit row: belongs to the table instead of floating above it */

table thead tr.bulk-table-row th {
  padding: 0 !important;
  background: rgba(251,245,236,.72) !important;
  border-bottom: 1px solid rgba(196,165,118,.24) !important;
  text-transform: none !important;
  letter-spacing: normal !important;
}

.bulk-table-row .bulk-bar {
  width: 100%;
  margin: 0;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  background: linear-gradient(90deg,rgba(251,245,236,.92),rgba(255,253,249,.86));
  padding: .72rem .86rem;
  display: grid;
  grid-template-columns: minmax(185px,.42fr) minmax(340px,1fr) auto;
  gap: .75rem 1rem;
  align-items: center;
}

.bulk-table-row .bulk-head {
  gap: .55rem;
  min-width: 0;
}

.bulk-table-row .bulk-head strong {
  display: block;
  font-family: var(--font-serif);
  text-transform: uppercase;
  letter-spacing: .08em;
  font-size: .9rem;
  color: var(--forest);
}

.bulk-table-row .bulk-count {
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(196,165,118,.28);
  border-radius: 999px;
  padding: .22rem .56rem;
  background: #fffdfa;
  color: #6f6962;
  font-size: .76rem;
  white-space: nowrap;
}

.bulk-controls {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(165px,1fr));
  gap: .55rem;
  align-items: end;
}

.bulk-field {
  display: flex;
  flex-direction: column;
  gap: .22rem;
  min-width: 0;
}

.bulk-field span {
  font-size: .68rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #82786e;
}

.bulk-field select {
  width: 100%;
  min-height: 34px;
  border: 1px solid rgba(196,165,118,.28);
  border-radius: 9px;
  background: #fffdfa;
  color: var(--forest);
  padding: .4rem .6rem;
  font: inherit;
  font-size: .82rem;
}

.bulk-field select:focus {
  outline: none;
  border-color: rgba(22,71,56,.32);
  box-shadow: 0 0 0 3px rgba(22,71,56,.08);
}

.bulk-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: .5rem;
  flex-wrap: wrap;
}

.bulk-actions .btn {
  white-space: nowrap;
}

.bulk-delete-btn {
  border: 1px solid rgba(197,78,63,.22) !important;
  color: #b54b3f !important;
  background: #fff8f5 !important;
}

.bulk-delete-btn:hover {
  background: #fbe9e3 !important;
}

@media(max-width:980px) {
  .bulk-table-row .bulk-bar {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .bulk-actions {
    justify-content: flex-start;
  }

}

.bcrit-opt {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  white-space: nowrap;
  color: var(--charcoal);
}

.bcrit-opt input {
  width: auto;
}

.bcrit-del {
  color: #A95D4E;
}

.btn-sm {
  padding: .35rem .7rem;
  font-size: .8rem;
}

/* Wrapping, resizable table text cells */

textarea.cell-ta {
  width: 100%;
  min-width: 60px;
  resize: vertical;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font: inherit;
  line-height: 1.3;
  padding: .35rem .45rem;
  min-height: 2em;
  overflow: hidden;
}

/* Draggable column resizing for all planner tables */

table thead th {
  position: relative;
}

#main table.planner-resizable-table {
  table-layout: fixed;
}

.col-resizer {
  position: absolute;
  top: 0;
  right: -1px;
  width: 10px;
  height: 100%;
  cursor: col-resize;
  user-select: none;
  touch-action: none;
  z-index: 5;
}

.col-resizer::before {
  content: "";
  position: absolute;
  top: 22%;
  bottom: 22%;
  left: 4px;
  width: 1px;
  background: rgba(184,153,104,.38);
  border-radius: 2px;
}

.col-resizer:hover::before,
.col-resizer.active::before {
  background: var(--gold);
  width: 2px;
  left: 4px;
}

#main table th.is-resizing {
  background: rgba(251,245,236,.95);
}

/* Vision board */

.preset-palettes,
.saved-palettes {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 1rem;
}

.palette-card {
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: .8rem;
  background: rgba(255,255,255,.6);
}

.palette-name {
  font-family: var(--font-serif);
  color: var(--forest);
  font-weight: 600;
  margin-bottom: .55rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.swatch-row {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  margin-bottom: .7rem;
}

.swatch-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .25rem;
}

.swatch {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid rgba(0,0,0,.12);
  display: block;
}

.swatch-wrap code {
  font-size: .66rem;
  color: var(--muted);
}

.palette-builder {
  display: flex;
  flex-wrap: wrap;
  gap: .5rem;
  align-items: center;
  margin: .4rem 0 1rem;
}

.palette-builder input[type="color"] {
  width: 42px;
  height: 38px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: none;
  cursor: pointer;
}

.mood-section {
  margin-bottom: 1.4rem;
  padding-bottom: 1.4rem;
  border-bottom: 1px solid var(--border);
}

.mood-section:last-child {
  border-bottom: none;
}

.mood-sec-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  margin-bottom: .6rem;
}

.mood-sec-head span {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  color: var(--forest);
  font-weight: 600;
}

.gallery-grid {
  column-count: 4;
  column-gap: .5rem;
}

@media (max-width: 1100px) {
  .gallery-grid {
    column-count: 3;
  }

}

@media (max-width: 760px) {
  .gallery-grid {
    column-count: 2;
  }

}

@media (max-width: 460px) {
  .gallery-grid {
    column-count: 1;
  }

}

.gallery-item {
  break-inside: avoid;
  margin: 0 0 .5rem;
  border-radius: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  background: rgba(255,255,255,.6);
  box-shadow: 0 2px 10px rgba(45,74,62,.06);
}

.gallery-item img {
  width: 100%;
  height: auto;
  display: block;
}

.gallery-item figcaption {
  display: flex;
  align-items: center;
  gap: .35rem;
  padding: .4rem;
}

.gallery-item figcaption input {
  flex: 1;
  font-size: .78rem;
}

.mini-upload {
  display: inline-block;
  cursor: pointer;
  font-size: .8rem;
  color: var(--forest);
  border: 1px dashed var(--gold-lt);
  border-radius: 8px;
  padding: .3rem .6rem;
  background: var(--gold-pale);
}

.mini-upload:hover {
  border-color: var(--gold);
}

.doc-thumb {
  width: 48px;
  height: 48px;
  object-fit: cover;
  border-radius: 6px;
  cursor: pointer;
  border: 1px solid var(--border);
}

/* Itemized budget */

.budget-summary {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: .8rem;
}

.bsum-card {
  display: flex;
  align-items: center;
  gap: .7rem;
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: .6rem .7rem;
  background: rgba(255,255,255,.6);
}

.ring {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  flex: 0 0 58px;
  display: grid;
  place-items: center;
}

.ring span {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #fff;
  display: grid;
  place-items: center;
  font-size: .72rem;
  font-weight: 700;
  color: var(--forest);
}

.bsum-info {
  min-width: 0;
  flex: 1;
}

.bsum-name {
  font-family: var(--font-serif);
  color: var(--forest);
  font-weight: 600;
  font-size: .92rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bsum-amt {
  font-size: .82rem;
  color: var(--charcoal);
  margin: .1rem 0 .3rem;
}

.bsum-target {
  font-size: .7rem;
  color: var(--muted);
  margin-top: .25rem;
}

.budget-cat {
  margin-bottom: 1rem;
}

.budget-cat-head {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  align-items: center;
  justify-content: space-between;
  margin-bottom: .6rem;
}

.budget-cat-name {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  color: var(--forest);
  font-weight: 600;
  border: none;
  border-bottom: 1px solid transparent;
  background: transparent;
  flex: 1;
  min-width: 160px;
}

.budget-cat-name:hover,
.budget-cat-name:focus {
  border-bottom-color: var(--gold-lt);
  outline: none;
}

.budget-cat-meta {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  align-items: center;
  font-size: .8rem;
  color: var(--muted);
}

.budget-cat-meta label {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
}

.budget-cat-pct {
  font-weight: 700;
  color: var(--forest);
}

.budget-tip {
  margin-top: .6rem;
  font-size: .82rem;
  color: var(--charcoal);
  background: var(--gold-pale);
  border-left: 3px solid var(--gold);
  border-radius: 8px;
  padding: .5rem .7rem;
}

/* Global scripture banner */

#scripture-banner {
  background: #7B2D3B;
  color: #FFFDF9;
  text-align: center;
  padding: .6rem 1.5rem;
  font-family: var(--font-serif);
  font-size: 1rem;
  letter-spacing: .01em;
  border-bottom: 1px solid rgba(212,184,150,.42);
}

#scripture-banner .ref {
  color: var(--gold-lt);
  font-size: .8rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  margin-left: .5rem;
  font-family: var(--font-sans);
}

.banner-editor {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  align-items: end;
}

.banner-editor .form-group {
  margin: 0;
}

.saved-flash {
  color: var(--gold-lt) !important;
  transition: color .2s;
}

@media (max-width: 1180px) {
  .dashboard-shell {
    grid-template-columns: 1fr;
  }

  .dashboard-aside {
    position: static;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

}

@media (max-width: 900px) {
  .dash-hero {
    grid-template-columns: 1fr;
    justify-items: start;
    text-align: left;
  }

  .dash-hero .hero-meta {
    justify-content: flex-start;
  }

  .dash-hero .page-subtitle {
    margin-left: 0;
    margin-right: 0;
  }

  .hero-photo-col {
    order: -1;
    margin-bottom: .5rem;
  }

  .dashboard-aside {
    grid-template-columns: 1fr;
  }

  .dash-stat-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

}

/* ─── RESPONSIVE ─── */

@media (max-width:768px) {
  #sidebar {
    display: none;
  }

  #main {
    padding: 1rem;
  }

  .chart-row {
    grid-template-columns: 1fr;
  }

  .form-grid {
    grid-template-columns: 1fr;
  }

  .form-grid.cols-3 {
    grid-template-columns: 1fr;
  }

  .form-group.span-2,
  .form-group.span-3 {
    grid-column: span 1;
  }

  .notes-grid {
    grid-template-columns: 1fr;
  }

  .stat-grid,
  .dash-stat-grid {
    grid-template-columns: 1fr;
  }

  .dashboard-shell,
  .dashboard-aside {
    grid-template-columns: 1fr;
  }

  .dash-hero {
    grid-template-columns: 1fr;
  }

  .hero-meta {
    display: grid;
  }

  #topbar .actions .btn .btn-text {
    display: none;
  }

}

/* ════════════════════════════════════════════════
MOCKUP REDESIGN — chrome + dashboard
════════════════════════════════════════════════ */

/* Top bar → slim translucent strip with a forest action pill on the right */

#topbar {
  background: rgba(249,247,244,.88) !important;
  backdrop-filter: blur(8px);
  border-bottom: none !important;
  box-shadow: none;
  padding: .72rem 1.35rem .45rem;
  justify-content: space-between;
  align-items: center;
}

#topbar .brand {
  display: flex !important;
  align-items: center;
  gap: .85rem;
  min-width: 0;
}

#topbar .actions {
  background: var(--forest-deep);
  border-radius: 999px;
  padding: .32rem .5rem;
  gap: .15rem;
  box-shadow: 0 8px 24px rgba(45,74,62,.18);
}

#topbar .actions .btn {
  background: transparent !important;
  border: none !important;
  color: #F4EFE6 !important;
  border-radius: 999px;
  padding: .42rem .82rem;
}

#topbar .actions .btn:hover {
  background: rgba(255,255,255,.13) !important;
}

#topbar .actions .btn .btn-text {
  font-size: .82rem;
  letter-spacing: .02em;
}

#topbar .brand-mark {
  color: var(--gold);
  font-size: 1.2rem;
  line-height: 1;
  flex: 0 0 auto;
}

#topbar .brand-copy {
  min-width: 0;
}

#topbar .brand-main {
  font-family: var(--font-serif);
  color: var(--forest-deep);
  font-size: 1.45rem;
  line-height: 1.02;
  letter-spacing: .02em;
  font-weight: 500;
}

#topbar .brand-sub {
  font-size: .68rem;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--forest-deep) 58%, #ffffff 22%);
  margin-top: .2rem;
}

/* Sidebar photo cutout */

.side-brand {
  padding: .7rem 1.05rem 1rem;
  border-bottom: 1px solid rgba(212,184,150,.22);
  margin-bottom: .55rem;
}

.side-photo-wrap {
  display: flex;
  justify-content: center;
}

.side-photo-cutout {
  position: relative;
  width: 124px;
  height: 124px;
  border-radius: 50%;
  overflow: hidden;
  cursor: pointer;
  background: #f7efe4;
  border: 2px solid rgba(212,184,150,.58);
  box-shadow: 0 10px 22px rgba(0,0,0,.16), inset 0 0 0 8px rgba(255,255,255,.05);
  background-size: cover;
  background-position: center;
}

.side-photo-cutout.has-photo {
  border-color: rgba(212,184,150,.9);
}

.side-photo-placeholder {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .35rem;
  color: rgba(255,249,240,.8);
  text-align: center;
  padding: 1rem;
}

.side-photo-placeholder svg {
  width: 28px;
  height: 28px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.side-photo-placeholder span {
  font-size: .72rem;
  line-height: 1.25;
}

.side-photo-edit {
  position: absolute;
  right: 7px;
  bottom: 7px;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(244,239,230,.98);
  color: var(--forest-deep);
  border: 1px solid rgba(212,184,150,.65);
  box-shadow: 0 5px 14px rgba(0,0,0,.12);
  pointer-events: none;
}

.side-photo-edit svg {
  width: 15px;
  height: 15px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.side-photo-help {
  margin-top: .65rem;
  text-align: center;
  font-size: .68rem;
  line-height: 1.35;
  color: rgba(249,247,244,.78);
}

.nav-item.active {
  background: #fff !important;
  color: var(--forest) !important;
  border-radius: 8px;
  font-weight: 600;
}

.nav-item.active .nav-icon svg {
  color: var(--forest);
  stroke: var(--forest);
}

/* Profile + backup bars — slim & subtle */

#profile-bar {
  background: rgba(45,74,62,.05);
  color: var(--muted);
  border-bottom: 1px solid var(--border);
  padding: .4rem 1.6rem;
}

#profile-bar .pbar-label {
  color: var(--muted);
}

#profile-bar select {
  background: #fff;
  color: var(--charcoal);
}

#profile-bar .btn-sm {
  background: #fff;
  color: var(--forest);
  border-color: var(--border);
}

#backup-banner {
  background: rgba(245,239,228,.6);
}

/* ── Dashboard (editorial match) ── */

.dashboard-redesign {
  width: 100%;
  max-width: 1260px;
  margin: 0 auto;
  padding: clamp(.5rem,1.1vw,.95rem) clamp(.3rem,1vw,.7rem) 0;
}

/* Leaf ornament */

.leaf-orn {
  width: 80px;
  height: auto;
  display: inline-block;
  vertical-align: middle;
}

.dash-orn {
  color: var(--gold);
  line-height: 0;
  text-align: left;
}

.dash-orn .leaf-orn {
  width: 90px;
}

.dash-orn-sm .leaf-orn {
  width: 62px;
}

.leaf-light {
  color: #d8b778;
}

/* Title */

.dashboard-redesign .dash-title {
  text-align: left;
  margin: .3rem 0 1.5rem;
}

.dashboard-redesign .dash-title .dash-orn {
  margin-bottom: .3rem;
}

.dashboard-redesign .dash-title .page-title {
  text-transform: uppercase;
  letter-spacing: .055em;
  font-weight: 500;
  font-size: 2.9rem;
  margin: .2rem 0 .5rem;
  color: var(--forest-deep);
}

.dashboard-redesign .dash-title .page-subtitle {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.18rem;
  color: #66615a;
  max-width: none;
}

/* Info + stat cards (icon-left) */

.dash-info-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 1.1rem;
  margin-bottom: 1.2rem;
}

.info-card {
  display: grid;
  grid-template-columns: 56px 1fr;
  align-items: center;
  gap: 14px;
  background: rgba(255,253,249,.85);
  border: 1px solid rgba(196,165,118,.26);
  border-radius: 13px;
  padding: 1.1rem 1.2rem;
  box-shadow: 0 9px 22px rgba(54,39,20,.06);
}

.info-icon {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: #fbf5ec;
  border: 1px solid rgba(196,165,118,.24);
  color: var(--gold);
  display: grid;
  place-items: center;
}

.info-icon svg {
  width: 26px;
  height: 26px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.info-label {
  font-size: .66rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: #77706a;
  font-weight: 700;
  margin-bottom: 5px;
}

.info-value {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  line-height: 1.05;
  color: var(--forest);
  font-weight: 500;
}

.info-sub {
  font-size: .78rem;
  color: #706b65;
  margin-top: 3px;
}

.info-photo {
  width: 54px !important;
  height: 54px !important;
  border-radius: 50% !important;
  border: 1px solid rgba(196,165,118,.3) !important;
  background-color: #fbf5ec;
}

.info-photo .hero-photo-placeholder span {
  display: none;
}

.info-photo .hero-photo-placeholder svg {
  width: 24px;
  height: 24px;
}

.palette-swatches {
  display: flex;
  gap: 8px;
  align-items: center;
  height: 26px;
  margin: 2px 0 7px;
}

.palette-swatches i {
  width: 23px;
  height: 23px;
  border-radius: 50%;
  display: block;
  border: 1px solid rgba(0,0,0,.08);
}

.palette-names .pname {
  color: var(--forest);
  font-weight: 600;
  font-size: .8rem;
}

.palette-names .pfont {
  display: block;
  font-size: .7rem;
  color: var(--gold);
  margin-top: 1px;
}

/* Stat tiles */

.dash-stat-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 1.1rem;
  margin-bottom: 1.3rem;
}

.stat-tile {
  display: flex;
  flex-direction: column;
}

.stat-tile-top {
  display: grid;
  grid-template-columns: 56px 1fr;
  align-items: center;
  gap: 14px;
}

.stat-tile-val {
  font-family: var(--font-serif);
  font-size: 1.95rem;
  line-height: 1.02;
  color: var(--forest);
  margin: 2px 0;
}

.stat-tile.danger .stat-tile-val {
  color: var(--red);
}

.stat-tile-link {
  margin-top: auto;
  padding-top: .85rem;
  border-top: 1px solid rgba(196,165,118,.28);
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--forest);
  font-size: .82rem;
  cursor: pointer;
}

.stat-tile-link span {
  color: var(--gold);
  font-size: 1.1rem;
}

.stat-tile-link:hover {
  color: var(--gold);
}

/* Trio */

.dash-trio {
  display: grid;
  grid-template-columns: 1fr 1.28fr 1.26fr;
  gap: 1.3rem;
  align-items: stretch;
  margin-bottom: 1.3rem;
}

.dash-trio > .card {
  height: 100%;
  display: flex;
  flex-direction: column;
}

/* Countdown */

.dashboard-redesign .countdown-card {
  border-radius: 13px;
  padding: 1.5rem 1.4rem 1.3rem;
  text-align: left;
  color: #fff9ef;
  background: radial-gradient(circle at 70% 0%,rgba(255,255,255,.06),transparent 35%),linear-gradient(155deg,#174b3b,#073b2f 70%);
  border: 1px solid rgba(199,161,98,.38);
  box-shadow: 0 16px 30px rgba(20,60,48,.18);
}

.dashboard-redesign .countdown-card .card-kicker {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #fffaf0;
  font-weight: 500;
}

.cd-date {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  color: #f5e5c8;
  margin: .4rem 0 .1rem;
}

.cd-num {
  font-family: var(--font-serif);
  font-size: clamp(3.8rem,7vw,5rem);
  line-height: .95;
  color: #f7dfbd;
  text-shadow: 0 2px 0 rgba(0,0,0,.12);
}

.cd-label {
  font-family: var(--font-serif);
  font-size: 1rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #fffaf0;
  margin-top: .15rem;
}

.cd-parts {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  margin: 1.1rem 0 .9rem;
  border-top: 1px solid rgba(216,183,120,.25);
  border-bottom: 1px solid rgba(216,183,120,.25);
}

.cd-parts span {
  padding: .6rem 0;
  border-right: 1px solid rgba(216,183,120,.22);
}

.cd-parts span:last-child {
  border-right: 0;
}

.cd-parts b {
  display: block;
  font-family: var(--font-serif);
  font-size: 1.3rem;
  color: #f7dfbd;
  font-weight: 400;
}

.cd-parts em {
  font-style: normal;
  text-transform: uppercase;
  font-size: .6rem;
  letter-spacing: .08em;
  color: #fffaf0;
}

.cd-verse {
  font-family: var(--font-serif);
  font-style: italic;
  color: #f1e5d2;
  font-size: .95rem;
  line-height: 1.35;
  margin-top: auto;
}

.cd-verse cite {
  display: block;
  font-family: var(--font-sans);
  font-style: normal;
  text-transform: uppercase;
  letter-spacing: .12em;
  font-size: .62rem;
  color: #fffaf0;
  margin-top: .5rem;
}

.dashboard-redesign .countdown-card .leaf-slot {
  margin: .7rem 0;
}

/* Progress + Next Up */

.dashboard-redesign .progress-suite,
.dashboard-redesign .next-up-card {
  border-radius: 13px;
  padding: 1.5rem 1.5rem;
  display: flex;
  flex-direction: column;
  background: rgba(255,253,249,.85);
  border: 1px solid rgba(196,165,118,.26);
  box-shadow: 0 9px 22px rgba(54,39,20,.06);
}

.dashboard-redesign .progress-suite .card-title,
.dashboard-redesign .next-up-card .card-title {
  text-align: left;
  font-family: var(--font-serif);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--forest);
  margin: 0;
}

.dashboard-redesign .progress-suite .dash-orn,
.dashboard-redesign .next-up-card .dash-orn {
  margin: .25rem 0 1rem;
}

.progress-list {
  display: flex;
  flex-direction: column;
  gap: .45rem;
}

.dprog-row {
  display: grid;
  grid-template-columns: 30px minmax(0,1fr) 50px;
  column-gap: .7rem;
  align-items: center;
  padding: .25rem 0;
}

.dprog-icon {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #fbf5ec;
  border: 1px solid rgba(196,165,118,.28);
  color: var(--gold);
  display: grid;
  place-items: center;
}

.dprog-icon svg {
  width: 14px;
  height: 14px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.dprog-mid {
  min-width: 0;
}

.dprog-label {
  font-size: .8rem;
  color: var(--forest);
  font-weight: 500;
  margin-bottom: 5px;
}

.dprog-mid .progress-track {
  height: 6px;
  background: #e8dfd3;
  border: 0;
  border-radius: 99px;
  overflow: hidden;
}

.dprog-mid .progress-track span {
  display: block;
  height: 100%;
  background: var(--forest-deep);
  border-radius: 99px;
}

.dprog-right {
  text-align: right;
}

.dprog-pct {
  font-size: .85rem;
  color: var(--forest);
  font-weight: 600;
}

.dprog-frac {
  font-size: .66rem;
  color: #9d8e7e;
}

.dash-card-foot {
  margin-top: auto;
}

.dash-card-foot a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--forest);
  font-size: .85rem;
  cursor: pointer;
  border-top: 1px solid rgba(196,165,118,.28);
  padding-top: .9rem;
  margin-top: 1rem;
}

.dash-card-foot a span {
  color: var(--gold);
}

.dash-card-foot a:hover {
  color: var(--gold);
}

/* Next-up items */

.dnext-list {
  display: flex;
  flex-direction: column;
}

.dnext-item {
  display: grid;
  grid-template-columns: 24px 1fr auto;
  gap: .7rem;
  align-items: center;
  padding: .55rem 0;
  border-bottom: 1px solid rgba(196,165,118,.16);
}

.dnext-check {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1.5px solid #cbb98f;
}

.dnext-body {
  min-width: 0;
}

.dnext-title {
  font-family: var(--font-serif);
  font-size: 1.05rem;
  color: var(--forest);
}

.dnext-cat {
  font-size: .62rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #9d8e7e;
  margin-top: 1px;
}

.dnext-date {
  text-align: right;
}

.dnext-date > div:first-child {
  font-size: .82rem;
  color: var(--forest);
}

.dnext-dow {
  font-size: .6rem;
  letter-spacing: .08em;
  color: #a99f8d;
}

/* Scripture footer band */

.dash-scripture-footer {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 1.2rem;
  text-align: left;
  padding: 1.2rem 1.5rem;
  margin: .4rem 0 1.5rem;
  border-top: 1px solid rgba(196,165,118,.24);
}

.dscript-text {
  font-family: var(--font-serif);
  font-style: italic;
  color: var(--gold);
  font-size: 1.15rem;
  max-width: 60ch;
}

.dscript-text cite {
  display: block;
  font-family: var(--font-sans);
  font-style: normal;
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .66rem;
  color: var(--gold);
  margin-top: .4rem;
}

.dash-scripture-footer .dash-orn {
  flex: 0 0 auto;
}

/* Charts kept */

.dashboard-redesign .chart-wrap {
  background: rgba(255,253,249,.85);
  border: 1px solid rgba(196,165,118,.26);
  border-radius: 13px;
  padding: 1.2rem 1.3rem;
  box-shadow: 0 9px 22px rgba(54,39,20,.06);
}

.dashboard-redesign .chart-title {
  font-family: var(--font-serif);
  color: var(--forest);
  font-size: 1.05rem;
}

@media(max-width:1100px) {
  .dash-trio {
    grid-template-columns: 1fr;
  }

  .dash-stat-grid,
  .dash-info-grid {
    grid-template-columns: repeat(2,1fr);
  }

}

@media(max-width:640px) {
  .dash-stat-grid,
  .dash-info-grid {
    grid-template-columns: 1fr;
  }

  #topbar {
    padding: .65rem .9rem .4rem;
  }

  #topbar .brand-main {
    font-size: 1.12rem;
  }

  #topbar .brand-sub {
    font-size: .58rem;
    letter-spacing: .14em;
  }

}

/* ════════════════════════════════════════════════
INSTRUCTIONS PAGE — Listing-Instructions mockup match
════════════════════════════════════════════════ */

#panel-instructions.instructions-mockup {
  width: 100%;
  max-width: 1260px;
  margin: 0 auto;
  padding: clamp(.55rem,1.2vw,1rem) clamp(.32rem,1vw,.72rem) 0;
}

.instructions-mockup .inst-title-wrap {
  text-align: left;
  margin: .15rem 0 1.15rem;
}

.instructions-mockup .inst-title-wrap .leaf-orn {
  width: 70px;
  color: var(--gold);
}

.instructions-mockup .inst-title {
  font-family: var(--font-serif);
  color: var(--forest-deep);
  font-size: clamp(2.35rem,4.1vw,3.45rem);
  line-height: .98;
  letter-spacing: .07em;
  text-transform: uppercase;
  font-weight: 500;
  margin: .28rem 0 .25rem;
}

.instructions-mockup .inst-kicker {
  font-size: .82rem;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 600;
}

.inst-card {
  background: rgba(255,253,249,.86);
  border: 1px solid rgba(196,165,118,.26);
  border-radius: 13px;
  box-shadow: 0 10px 24px rgba(54,39,20,.055);
  padding: clamp(1rem,1.8vw,1.45rem);
}

.inst-welcome {
