  place-items: center;
  color: var(--gold);
  background: linear-gradient(135deg,rgba(255,253,249,.92),rgba(245,239,228,.58));
}

.inst-emblem svg {
  width: 74px;
  height: 74px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.25;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.inst-card-title {
  font-family: var(--font-serif);
  color: var(--forest-deep);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: .02em;
  margin-bottom: .35rem;
}

.inst-copy {
  color: var(--forest);
  font-size: .86rem;
  line-height: 1.62;
}

.inst-muted {
  color: #69625a;
}

.inst-grid-3 {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1rem;
}

.inst-section-title {
  text-align: left;
  font-family: var(--font-serif);
  color: var(--forest-deep);
  font-size: 1.08rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 600;
  margin-bottom: .15rem;
}

.inst-section-sub {
  text-align: left;
  font-family: var(--font-serif);
  font-style: italic;
  color: #6f6962;
  font-size: .9rem;
  margin-bottom: 1.05rem;
}

.inst-step-list {
  display: grid;
  gap: .72rem;
}

.inst-step {
  display: grid;
  grid-template-columns: 33px 42px 1fr;
  align-items: start;
  gap: .72rem;
}

.inst-num {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  border: 1px solid rgba(196,165,118,.36);
  color: var(--gold);
  font-family: var(--font-serif);
  font-size: 1.12rem;
  background: #fbf5ec;
}

.inst-round-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  border: 1px solid rgba(196,165,118,.25);
  background: #fbf5ec;
  color: var(--gold);
  flex: 0 0 auto;
}

.inst-round-icon svg {
  width: 21px;
  height: 21px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.inst-step h4,
.inst-tip h4 {
  font-family: var(--font-serif);
  font-size: 1rem;
  line-height: 1.05;
  color: var(--forest-deep);
  font-weight: 600;
  margin-bottom: .16rem;
}

.inst-step p,
.inst-tip p {
  font-size: .76rem;
  line-height: 1.38;
  color: var(--forest);
}

.inst-tip {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: .85rem;
  align-items: start;
  padding: .55rem 0 .75rem;
  border-bottom: 1px dashed rgba(196,165,118,.31);
}

.inst-tip:last-child {
  border-bottom: 0;
}

.inst-note-box {
  margin-top: .9rem;
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: .8rem;
  align-items: center;
  padding: .75rem .95rem;
  background: rgba(245,239,228,.72);
  border: 1px solid rgba(196,165,118,.18);
  border-radius: 6px;
}

.inst-note-box .leaf-orn {
  width: 38px;
  color: var(--gold);
}

.inst-note-box p {
  font-size: .78rem;
  line-height: 1.35;
  color: #3c3c36;
}

.inst-wide-row {
  display: grid;
  grid-template-columns: 1.35fr .75fr;
  gap: 1rem;
  margin-bottom: 1rem;
}

.inst-backup-grid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.inst-backup-item {
  display: grid;
  grid-template-columns: 48px 1fr;
  gap: .8rem;
  align-items: center;
}

.inst-backup-item h4 {
  font-family: var(--font-serif);
  color: var(--forest-deep);
  font-size: .98rem;
  margin-bottom: .12rem;
}

.inst-backup-item p {
  font-size: .72rem;
  line-height: 1.35;
  color: #3c3c36;
}

.inst-alert {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: .75rem;
  align-items: start;
  background: rgba(235,241,237,.58);
  border: 1px solid rgba(45,74,62,.10);
  padding: .75rem .9rem;
  border-radius: 6px;
  font-family: var(--font-serif);
  font-style: italic;
  color: var(--forest);
  font-size: .84rem;
}

.inst-alert svg {
  width: 24px;
  height: 24px;
  color: var(--forest-lt);
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
}

.inst-alone {
  text-align: left;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: flex-start;
