  border-top: 1px solid rgba(196,165,118,.22);
  padding-top: .95rem;
  display: none;
}

.venue-extra-editor.active {
  display: block;
}

.venue-extra-editor h4 {
  font-family: var(--font-serif);
  color: var(--forest);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin: 0 0 .75rem;
}

.venue-extra-grid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: .72rem;
}

.venue-extra-grid input {
  border: 1px solid rgba(196,165,118,.34);
  background: rgba(255,253,249,.98);
  border-radius: 9px;
  padding: .66rem .75rem;
  font-size: .82rem;
  color: var(--forest);
}

.venue-extra-grid .span-2 {
  grid-column: span 2;
}

.venue-extra-list {
  display: grid;
  gap: .65rem;
  margin-top: .8rem;
}

.venue-extra-row {
