  justify-content: space-between;
  align-items: center;
  gap: .6rem;
  margin-bottom: .55rem;
}

.venue-extra-row-head strong {
  font-family: var(--font-serif);
  color: var(--forest);
  font-size: 1rem;
}

.venue-card-delete {
  border: 0;
  background: #f7efe4;
  color: #8b5e3c;
  border-radius: 999px;
  padding: .25rem .5rem;
  font-size: .72rem;
}

.venue-card-link {
  margin-top: auto;
  color: var(--forest);
  font-size: .8rem;
