  display: inline-flex;
  align-items: center;
  gap: .28rem;
}

.venue-card-link:hover {
  text-decoration: underline;
}

.venue-compare-table {
  margin-top: .95rem;
  border-top: 1px solid rgba(196,165,118,.22);
  padding-top: .9rem;
  display: none;
}

.venue-compare-table.active {
  display: block;
}

.venue-compare-row {
  display: grid;
  grid-template-columns: 150px repeat(auto-fit,minmax(130px,1fr));
  gap: .7rem;
  padding: .43rem 0;
  border-bottom: 1px solid rgba(196,165,118,.12);
  font-size: .8rem;
  color: var(--forest);
}

.venue-compare-row:last-child {
  border-bottom: none;
}

.venue-compare-row strong {
  color: #7a6e5e;
  text-transform: uppercase;
  letter-spacing: .08em;
  font-size: .72rem;
}

.venue-switch-wrap {
  display: flex;
  align-items: center;
  gap: .62rem;
  color: var(--forest);
  font-size: .82rem;
  white-space: nowrap;
}

.venue-switch {
  position: relative;
  display: inline-block;
  width: 42px;
  height: 24px;
}

.venue-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.venue-switch .slider {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: #e7e2d8;
  transition: .2s ease;
  box-shadow: inset 0 0 0 1px rgba(196,165,118,.25);
}

.venue-switch .slider::before {
  content: "";
  position: absolute;
  height: 18px;
  width: 18px;
  left: 3px;
  top: 3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  transition: .2s ease;
}

.venue-switch input:checked + .slider {
  background: var(--forest);
}

.venue-switch input:checked + .slider::before {
  transform: translateX(18px);
}

.venue-note-stack {
  display: grid;
  gap: .85rem;
}

.venue-note-item {
  border: 1px solid rgba(196,165,118,.18);
  border-radius: 10px;
  background: #fffdfa;
  padding: .85rem .9rem;
}

.venue-note-label {
  display: flex;
  align-items: center;
  gap: .46rem;
  font-size: .78rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #7a6e5e;
  margin-bottom: .38rem;
}

.venue-note-label svg {
  width: 15px;
  height: 15px;
  color: var(--gold);
}

.venue-note-item p {
  margin: 0;
  color: var(--forest);
  font-size: .84rem;
  line-height: 1.55;
  white-space: pre-wrap;
}

.venue-note-item.empty p {
  color: #9a9082;
  font-style: italic;
}

.venue-note-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.venue-note-title-wrap {
  min-width: 0;
}

.venue-edit-note-btn {
  border: 0;
  background: transparent;
  color: var(--forest);
  padding: .15rem 0 .2rem;
  font-size: .82rem;
  white-space: nowrap;
  cursor: pointer;
  border-bottom: 1px solid transparent;
}

.venue-edit-note-btn:hover {
  color: var(--forest);
  border-bottom-color: rgba(52,112,93,.45);
}

.venue-note-display {
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0;
}

.venue-note-display p {
  margin: 0;
  color: var(--forest);
  font-size: .9rem;
  line-height: 1.68;
  white-space: pre-wrap;
}

.venue-note-display.empty p {
  color: #9a9082;
  font-style: italic;
}

.venue-note-updated {
  display: block;
  margin-top: .65rem;
  color: #8c8173;
  font-size: .74rem;
}

.venue-note-editor {
  display: grid;
  gap: .75rem;
}

.venue-note-editor textarea {
  width: 100%;
  min-height: 168px;
  border: 1px solid rgba(196,165,118,.34);
  background: rgba(255,253,249,.98);
  border-radius: 10px;
  padding: .85rem .95rem;
  color: var(--forest);
  line-height: 1.55;
  resize: vertical;
}

.venue-note-editor textarea:focus {
  border-color: rgba(22,71,56,.35);
  box-shadow: 0 0 0 3px rgba(22,71,56,.08);
  outline: none;
}

.venue-note-actions {
  display: flex;
  align-items: center;
  gap: .55rem;
  flex-wrap: wrap;
}

.venue-note-actions .btn {
  border-radius: 999px;
}

.venue-reminder-list {
  display: grid;
  gap: .16rem;
  margin-top: .25rem;
}

.venue-reminder-item {
  display: grid;
  grid-template-columns: 22px 1fr auto;
  gap: .7rem;
  align-items: center;
  padding: .5rem 0;
  border-bottom: 1px solid rgba(196,165,118,.12);
}

.venue-reminder-item:last-child {
  border-bottom: none;
}

.venue-reminder-mark {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  border: 1.6px solid #c9a970;
  color: transparent;
}

.venue-reminder-item.done .venue-reminder-mark {
  background: var(--forest);
  border-color: var(--forest);
  color: #fff;
}

.venue-reminder-mark svg {
  width: 11px;
  height: 11px;
  stroke-width: 2.4;
}

.venue-reminder-label {
  font-size: .84rem;
  color: var(--forest);
}

.venue-reminder-state {
  font-size: .77rem;
  color: var(--gold);
}

.venue-reminder-item.done .venue-reminder-state {
  color: var(--forest);
}

.venue-reminder-summary {
  margin-top: .9rem;
  padding: .9rem;
  border-radius: 11px;
  background: #f8f4ed;
  color: var(--forest);
  font-size: .83rem;
  line-height: 1.55;
}

.venue-scripture-footer {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1.1rem;
  padding: 1.15rem 1rem 0;
  margin: 1rem 0 0;
  border-top: 1px solid rgba(196,165,118,.24);
  color: var(--gold);
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.08rem;
  text-align: center;
}

.venue-scripture-footer .leaf-orn {
  width: 56px;
  flex: 0 0 auto;
}

.venue-scripture-footer cite {
  display: block;
  font-family: var(--font-sans);
  font-style: normal;
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .66rem;
  margin-top: .36rem;
  color: var(--gold);
}

@media(max-width:1120px) {
  .venue-stat-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .venue-layout,
  .venue-bottom-grid {
    grid-template-columns: 1fr;
  }

}

@media(max-width:780px) {
  .venue-stat-grid,
  .venue-detail-grid,
  .venue-shortlist-grid,
  .venue-bottom-grid,
  .venue-full-grid {
    grid-template-columns: 1fr;
  }

  .venue-detail-row.span-2,
  .venue-full-item.span-2 {
    grid-column: span 1;
  }

  .venue-compare-row {
    grid-template-columns: 1fr;
    gap: .22rem;
  }

  .venue-scripture-footer {
    flex-direction: column;
    gap: .35rem;
  }

}

/* ════════════════════════════════════════════════
PLANNING TIMELINE PAGE — editorial redesign
