#panel-plan.timeline-mockup {
  width: 100%;
  max-width: 1260px;
  margin: 0 auto;
  padding: clamp(.55rem,1.2vw,1rem) clamp(.28rem,.95vw,.65rem) 0;
}

.timeline-title-wrap {
  text-align: center;
  margin: .12rem 0 1.25rem;
}

.timeline-title-wrap .leaf-orn {
  width: 76px;
  color: var(--gold);
}

.timeline-title {
  font-family: var(--font-serif);
  color: var(--forest-deep);
  font-size: clamp(2.55rem,4.8vw,3.95rem);
  line-height: .95;
  letter-spacing: .06em;
  text-transform: uppercase;
  font-weight: 500;
  margin: .18rem 0 .38rem;
}

.timeline-subtitle {
  font-family: var(--font-serif);
