}

.timeline-action-row {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: .75rem;
  margin-bottom: 1.1rem;
  flex-wrap: wrap;
}

.timeline-action-row .btn {
  border-radius: 10px;
  padding: .68rem 1.18rem;
