  place-items: center;
  color: var(--gold);
  background: #fbf5ec;
  border: 1px solid rgba(196,165,118,.22);
}

.timeline-stat-card.soft .timeline-stat-icon {
  color: var(--forest);
  background: color-mix(in srgb, var(--forest) 8%, #fff);
  border-color: rgba(22,71,56,.12);
