  stroke-linejoin: round;
}

.timeline-stat-kicker {
  font-size: .73rem;
  letter-spacing: .11em;
  text-transform: uppercase;
  color: #706b65;
  margin-bottom: .16rem;
}

.timeline-stat-value {
  font-family: var(--font-serif);
  font-size: 1.55rem;
  line-height: 1.03;
  color: var(--forest);
}

.timeline-stat-sub {
  font-size: .78rem;
  color: #6f6962;
  margin-top: .24rem;
}

.timeline-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: .85rem;
}

.timeline-filter-group {
  display: flex;
  align-items: center;
  gap: .7rem;
  flex-wrap: wrap;
}

.timeline-filter-wrap {
  position: relative;
}

.timeline-filter-wrap svg {
  position: absolute;
  left: .78rem;
  top: 50%;
  transform: translateY(-50%);
  color: #9e8657;
  width: 16px;
  height: 16px;
}

.timeline-filter-select {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  padding: .7rem 2.25rem .7rem 2.1rem;
  border: 1px solid rgba(196,165,118,.3);
  border-radius: 10px;
  background: rgba(255,253,249,.96);
  color: var(--forest);
  font-size: .84rem;
  box-shadow: 0 5px 16px rgba(54,39,20,.04);
}

.timeline-filter-select:focus {
  outline: none;
  border-color: rgba(22,71,56,.28);
