.timeline-meta-actions {
  display: flex;
  gap: .55rem;
  flex-wrap: wrap;
}

.timeline-meta-actions .btn {
  border-radius: 9px;
}

.timeline-table-card {
  border: 1px solid rgba(196,165,118,.27);
