.timeline-pill.phase-12 {
  background: color-mix(in srgb, var(--forest) 8%, #fff);
  color: var(--forest);
}

.timeline-pill.phase-9 {
  background: #f8f0e8;
  color: #9b7040;
}

.timeline-pill.phase-6 {
  background: #f7eee8;
  color: #ad7655;
}

.timeline-pill.phase-3 {
  background: #f4edf5;
  color: #7f678b;
}

.timeline-pill.phase-month {
  background: #f7f1e5;
  color: #8b7242;
}

.timeline-pill.phase-week {
  background: #eef0f8;
  color: #61729a;
}

.timeline-pill.phase-after {
  background: color-mix(in srgb, var(--forest) 5%, #fff);
  color: var(--forest);
