.timeline-pill.priority-medium {
  background: #f7f2e7;
  color: #a9802b;
}

.timeline-pill.priority-low {
  background: color-mix(in srgb, var(--forest) 6%, #fff);
  color: var(--forest);
}

.timeline-pill.status-complete {
  background: color-mix(in srgb, var(--forest) 8%, #fff);
  color: var(--forest);
}

.timeline-pill.status-progress {
  background: #f7f2e7;
  color: #a9802b;
}

.timeline-pill.status-upcoming {
  background: #edf1f5;
  color: #61748f;
