.timeline-owner-meta,
.timeline-date-meta {
  display: flex;
  align-items: center;
  gap: .45rem;
  min-width: 0;
}

.timeline-owner-meta svg,
.timeline-date-meta svg {
  width: 15px;
  height: 15px;
  color: var(--gold);
  flex: 0 0 auto;
}

.timeline-done-wrap {
  display: flex;
  justify-content: center;
}

.timeline-done-check {
