/* Reconciliation panel */
.budget-recon-head { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: .75rem; margin-bottom: .8rem; }
.budget-gift-toggle { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem; }
