.budget-gift-seg { display: inline-flex; border: 1px solid var(--border, #e2ddd2); border-radius: 999px; overflow: hidden; }
.budget-gift-seg-btn { border: 0; background: transparent; padding: .3rem .85rem; font-size: .8rem; cursor: pointer; color: var(--muted, #6a655d); }
.budget-gift-seg-btn.active { background: var(--forest, #2d4a3e); color: #fff; }
.budget-gift-toggle-hint { font-size: .72rem; color: var(--muted, #6a655d); }
