.budget-recon-waterfall { margin-bottom: 1rem; }
.budget-recon-waterfall-table, .budget-recon-table, .budget-recon-contrib-table { width: 100%; border-collapse: collapse; font-size: .84rem; }
.budget-recon-waterfall-table th, .budget-recon-table th, .budget-recon-contrib-table th { text-align: right; font-size: .68rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted, #6a655d); font-weight: 500; padding: .3rem .55rem; border-bottom: 1px solid var(--border, #e2ddd2); }
.budget-recon-waterfall-table th:first-child, .budget-recon-table th:first-child, .budget-recon-contrib-table th:first-child { text-align: left; }
.budget-recon-waterfall-table td { padding: .32rem .55rem; }
.budget-recon-waterfall-table .wf-label { color: var(--ink, #2b2b2b); }
.budget-recon-waterfall-table .wf-num { text-align: right; font-variant-numeric: tabular-nums; color: var(--muted, #6a655d); }
.budget-recon-waterfall-table .wf-active { color: var(--forest, #2d4a3e); font-weight: 600; }
.budget-recon-waterfall-table .wf-sub td, .budget-recon-waterfall-table .wf-rem td { border-top: 1px solid var(--border, #e2ddd2); font-weight: 600; }
.budget-recon-waterfall-table .wf-gift .wf-num { color: #2f7050; }
body.dark-mode .budget-recon-waterfall-table .wf-gift .wf-num { color: #9fc7ac; }

.budget-recon-grid { display: grid; grid-template-columns: 1fr; gap: 1.5rem; }
.budget-recon-col-title { font-size: .8rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted, #6a655d); margin: 0 0 .4rem; font-weight: 500; }
.budget-recon-table td, .budget-recon-contrib-table td { padding: .32rem .55rem; border-bottom: 1px solid var(--border, #eee); }
.budget-recon-table .brc-num, .budget-recon-contrib-table .brc-num { text-align: right; font-variant-numeric: tabular-nums; }
.budget-recon-table .brc-name, .budget-recon-contrib-table .brc-name { font-weight: 500; color: var(--forest, #2d4a3e); }
.budget-recon-table .brc-gift { color: #2f7050; }
.budget-recon-table .brc-share { font-weight: 600; }
.budget-recon-table .brc-over { color: #C53030; }
.budget-recon-table .brc-total td { border-top: 2px solid var(--border, #ddd); border-bottom: 0; font-weight: 700; }
.budget-recon-table .brc-tag, .budget-recon-contrib-table .brc-tag { font-size: .62rem; color: var(--muted, #6a655d); font-weight: 400; }
.brc-contrib-items { display: block; font-size: .68rem; font-weight: 400; color: var(--muted, #6a655d); }
