.budget-inline-catnote { font-size: .72rem; color: var(--muted, #6a655d); }
.budget-inline-items { margin-top: 1rem; }
.budget-inline-items-title { font-size: .78rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted, #6a655d); font-weight: 500; margin-bottom: .45rem; }
.budget-inline-items-empty { font-size: .82rem; color: var(--muted, #6a655d); padding: .55rem .2rem; }
.budget-inline-items-table { width: 100%; border-collapse: collapse; font-size: .85rem; }
.budget-inline-items-table th { text-align: right; font-size: .66rem; text-transform: uppercase; letter-spacing: .04em; color: var(--muted, #6a655d); font-weight: 500; padding: .35rem .55rem; border-bottom: 1px solid var(--border, #e2ddd2); }
.budget-inline-items-table th:first-child, .budget-inline-items-table td:first-child { text-align: left; }
