/* Payment linked to a gifted budget item */
.payment-gift-note { font-size: .8rem; line-height: 1.5; background: rgba(126, 168, 146, .12); border: 1px solid rgba(126, 168, 146, .32); border-radius: 8px; padding: .5rem .65rem; color: #2f7050; }
.payment-gift-note.partial { background: rgba(196, 165, 118, .14); border-color: rgba(196, 165, 118, .34); color: #8a6d2f; }
body.dark-mode .payment-gift-note { color: #9fc7ac; background: rgba(126, 168, 146, .12); border-color: rgba(126, 168, 146, .3); }
body.dark-mode .payment-gift-note.partial { color: #d8c08a; background: rgba(196, 165, 118, .12); border-color: rgba(196, 165, 118, .28); }

/* ── Guided setup coach (spotlight + ambient) ─────────────────────────── */
.coach-dim { position: fixed; z-index: 11990; background: rgba(18,16,12,.60); display: none; }
.coach-hole { position: fixed; z-index: 11992; border-radius: 10px; border: 2px solid var(--forest, #2d4a3e); box-shadow: 0 0 24px 5px rgba(45,74,62,.40); pointer-events: none; display: none; transition: left .2s ease, top .2s ease, width .2s ease, height .2s ease; }
.coach-bubble { position: fixed; z-index: 12001; width: 340px; max-width: calc(100vw - 32px); background: #ffffff; border: 1px solid var(--border, #e2ddd2); border-radius: 14px; box-shadow: 0 18px 50px rgba(0,0,0,.4); padding: 16px 18px; box-sizing: border-box; }
.coach-bubble h4 { margin: 0 0 4px; font-size: 1.05rem; color: var(--ink, #222); }
.coach-chip { display: inline-block; font-size: .68rem; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--forest, #2d4a3e); background: rgba(45,74,62,.1); padding: 3px 9px; border-radius: 20px; margin-bottom: 8px; }
.coach-body { color: var(--muted, #6a655d); font-size: .85rem; line-height: 1.5; margin: 0 0 12px; }
.coach-field { margin-bottom: 9px; }
.coach-field label { display: block; font-size: .72rem; color: var(--muted, #6a655d); margin-bottom: 3px; }
.coach-field input { width: 100%; height: 38px; border: 1px solid var(--border-strong, #cfc9be); border-radius: 8px; padding: 0 11px; background: var(--section-bg, #fff); color: var(--ink, #222); font-size: .9rem; box-sizing: border-box; }
.coach-lights { display: flex; gap: 6px; align-items: center; font-size: .75rem; color: #2f7050; background: rgba(126,168,146,.14); border-radius: 8px; padding: 7px 10px; margin: 2px 0 12px; }
.coach-actions { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.coach-actions .right { display: flex; gap: 8px; }
/* Self-contained buttons — .ued-btn depends on --ued-* vars only present inside .ued-scope. */
.coach-bubble .ued-btn, .coach-framing-card .ued-btn { background: #ffffff; border: 1px solid var(--border-strong, #cfc9be); color: var(--ink, #222); border-radius: 8px; padding: .5rem .95rem; font-size: .74rem; }
.coach-bubble .ued-btn.primary, .coach-framing-card .ued-btn.primary { background: #2d4a3e; border-color: #2d4a3e; color: #ffffff; }
body.dark-mode .coach-bubble .ued-btn, body.dark-mode .coach-framing-card .ued-btn { background: var(--dm-input, #191919); border-color: var(--dm-border, #333); color: var(--dm-text, #d2d2d2); }
body.dark-mode .coach-bubble .ued-btn.primary, body.dark-mode .coach-framing-card .ued-btn.primary { background: #3f5d50; border-color: #3f5d50; color: #ffffff; }
.coach-bubble .ued-btn:hover, .coach-framing-card .ued-btn:hover { background: #f2efe9; color: var(--ink, #222); }
.coach-bubble .ued-btn.primary:hover, .coach-framing-card .ued-btn.primary:hover { background: #24463a; border-color: #24463a; color: #ffffff; }
body.dark-mode .coach-bubble .ued-btn:hover, body.dark-mode .coach-framing-card .ued-btn:hover { background: var(--dm-surface-2, #262626); color: var(--dm-text, #d2d2d2); }
body.dark-mode .coach-bubble .ued-btn.primary:hover, body.dark-mode .coach-framing-card .ued-btn.primary:hover { background: #4a6b5b; border-color: #4a6b5b; color: #ffffff; }

/* ============================================================
   PAGE-HEADER DECLUTTER (visual audit pass)
   Tightens the tall repetitive preamble stack on every page:
   smaller title, no giant section number, slim scripture / prayer /
   progress bands, tighter vertical rhythm.
   ============================================================ */
#main .m-title { font-size: clamp(30px, 3.2vw, 38px) !important; line-height: 1.12 !important; margin: 0 0 .1rem !important; }
#main .ued-title { font-size: clamp(26px, 3vw, 34px) !important; line-height: 1.15 !important; }
/* Remove the giant decorative section number */
#main .m-mast-right, #main .m-mast-num { display: none !important; }
/* Scripture becomes a slim caption, not its own band */
#main .page-scripture-footer { margin: .35rem 0 .6rem !important; padding: .3rem 0 !important; border-top: 0 !important; }
#main .page-scripture-footer .psf-text { font-size: .88rem !important; }
/* Slim the Pause & Pray banner */
#main .page-prayer-prompt { padding: .55rem .95rem !important; margin: 0 0 .6rem !important; }
#main .page-prayer-prompt [class*="title"], #main .page-prayer-prompt h3, #main .page-prayer-prompt h4 { font-size: .74rem !important; }
/* Slim the full-width progress bar and hug it to the stat band */
#main .ux-goal-bar { padding: .5rem .95rem !important; margin-top: .4rem !important; margin-bottom: .7rem !important; }
/* Tighten masthead vertical rhythm */
#main .m-mast, #main .m-mast-wrap { margin-bottom: .5rem !important; padding-bottom: .25rem !important; }

/* ── "What's next" path on Get Started ────────────────────────────────── */
.nsp { margin: 0 0 1.5rem; }
.nsp-head { margin-bottom: 1rem; }
.nsp-kicker { font-size: .68rem; text-transform: uppercase; letter-spacing: .08em; color: var(--muted, #6a655d); }
.nsp-h { font-size: 1.3rem; margin: .15rem 0 .3rem; color: var(--ink, #222); }
.nsp-lead { color: var(--muted, #6a655d); font-size: .9rem; line-height: 1.55; margin: 0 0 .5rem; max-width: 640px; }
.nsp-progress { font-size: .78rem; font-weight: 600; color: #2d4a3e; }
.nsp-flow { position: relative; }
.nsp-flow::before { content: ''; position: absolute; left: 19px; top: 12px; bottom: 56px; width: 2px; background: var(--border, #e2ddd2); }
.nsp-step { position: relative; display: flex; gap: 14px; margin-bottom: 12px; cursor: pointer; z-index: 1; }
.nsp-badge { flex: none; width: 40px; height: 40px; border-radius: 50%; background: var(--section-bg, #fff); border: 2px solid var(--border-strong, #cfc9be); color: var(--ink, #222); display: flex; align-items: center; justify-content: center; font-weight: 600; }
.nsp-badge svg { width: 20px; height: 20px; }
.nsp-badge.cur { background: #2d4a3e; border-color: #2d4a3e; color: #fff; }
.nsp-badge.done { background: rgba(126,168,146,.18); border-color: rgba(126,168,146,.5); color: #2f7050; }
.nsp-badge.finish { background: rgba(126,168,146,.16); border-color: rgba(126,168,146,.45); color: #2f7050; }
.nsp-card { flex: 1; background: var(--section-bg, #fff); border: 1px solid var(--border, #e2ddd2); border-radius: 12px; padding: 12px 15px; transition: border-color .15s ease, box-shadow .15s ease; }
.nsp-step:hover .nsp-card { border-color: #2d4a3e; box-shadow: 0 4px 14px rgba(0,0,0,.06); }
.nsp-step.is-current .nsp-card { border: 2px solid #2d4a3e; }
.nsp-step.is-done .nsp-card { opacity: .82; }
.nsp-card-head { display: flex; align-items: center; gap: 8px; }
.nsp-ic { display: inline-flex; color: #2d4a3e; }
.nsp-ic svg { width: 18px; height: 18px; }
.nsp-title { font-weight: 500; color: var(--ink, #222); }
.nsp-chip { margin-left: auto; font-size: .64rem; font-weight: 600; text-transform: uppercase; letter-spacing: .03em; color: #2d4a3e; background: rgba(45,74,62,.1); padding: 3px 9px; border-radius: 20px; }
.nsp-chip.done { color: #2f7050; background: rgba(126,168,146,.16); }
.nsp-body { color: var(--muted, #6a655d); font-size: .85rem; line-height: 1.5; margin: 6px 0 8px; }
.nsp-cta { font-size: .8rem; font-weight: 500; color: #2d4a3e; }
.nsp-finish { margin-bottom: 0; cursor: pointer; }
.nsp-finish-card { background: rgba(126,168,146,.12); border: 0; color: #2f7050; display: flex; align-items: center; font-size: .85rem; line-height: 1.5; }
body.dark-mode .nsp-h, body.dark-mode .nsp-title { color: var(--dm-head, #ededed); }
body.dark-mode .nsp-badge { background: var(--dm-surface-2, #262626); border-color: var(--dm-border, #333); color: var(--dm-text, #d2d2d2); }
body.dark-mode .nsp-badge.cur { background: #3f5d50; border-color: #3f5d50; color: #fff; }
body.dark-mode .nsp-card { background: var(--dm-surface, #1e1e1e); border-color: var(--dm-border, #333); }
body.dark-mode .nsp-step:hover .nsp-card, body.dark-mode .nsp-step.is-current .nsp-card { border-color: #6f9a86; }
body.dark-mode .nsp-ic, body.dark-mode .nsp-cta, body.dark-mode .nsp-chip, body.dark-mode .nsp-progress { color: #8fb3a0; }
body.dark-mode .nsp-chip { background: rgba(143,179,160,.14); }

/* ============================================================
   AUDIT FIXES — de-duplicated titles, venue spacing,
   theme-consistent accents (replace hardcoded greens).
   The earlier hardcoded rules remain as graceful fallback for
   browsers without :has() / color-mix.
   ============================================================ */
/* Drop the duplicate hero heading when the page masthead already shows it */
#main [id^="panel-"]:has(.m-title) .ued-mast .ued-title { display: none !important; }
/* Venue: stop long ceremony/reception names from colliding */
body.editorial-v4 #main #panel-venue .m-stats { gap: 24px !important; }
body.editorial-v4 #main #panel-venue .m-stat { padding-inline: 12px !important; min-width: 0; box-sizing: border-box; }
/* Long venue names rendered at 25px and collided; a 1,4,0 rule was winning, so
   this uses two IDs to outrank it — shrink + allow wrap. */
body.editorial-v4 #main #panel-venue .m-stat-val { font-size: 1rem !important; line-height: 1.3 !important; white-space: normal !important; overflow-wrap: anywhere; }

/* ============================================================
   DASHBOARD BENTO — theme-driven, squared corners, responsive.
   Scoped to #panel-dashboard so it never affects other pages.
   ============================================================ */
/* Card-ify: consistent squared corners + subtle depth (light) */
#panel-dashboard .ued-panel,
#panel-dashboard .dash-breakdown-card,
#panel-dashboard .ued-band,
#panel-dashboard .dash-needs { border-radius: 8px !important; }
#panel-dashboard .ued-panel { box-shadow: 0 1px 3px rgba(0,0,0,.05); }
body.dark-mode #panel-dashboard .ued-panel { box-shadow: none; }

/* Countdown blends into the page — no filled card, no border, no shadow */
#panel-dashboard .ued-countdown-c {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

/* Outer gutter is applied uniformly for every page by `#main`'s horizontal
   padding (= var(--planner-page-gutter)). Masthead, cards, scripture, and the
   banner editor all sit inside #main, so they share that one gutter and line
   up automatically — no per-element gutter overrides needed. The scripture
   footer keeps zero side padding so its hairline ends at the same edge. */
body.editorial-v4 #main .page-scripture-footer { padding-left: 0 !important; padding-right: 0 !important; margin-left: 0 !important; margin-right: 0 !important; }

/* KPI strip (stats band) — squared, mobile-friendly */
@media (max-width: 640px){ #panel-dashboard .ued-band { --ued-band-cols: 2 !important; } }

/* Bento primary row: progress dominant + Needs-you side by side (v2 sketch) */
#panel-dashboard .dash-primary-row { display: grid !important; grid-template-columns: 1.9fr 1fr !important; gap: 12px; margin: 12px 0; align-items: stretch; }
#panel-dashboard .dash-primary-row > * { grid-column: auto !important; min-width: 0; }
#panel-dashboard .dash-progress-dominant { border: 1px solid var(--border-strong, #cfc9be) !important; }
#panel-dashboard .dash-progress-dominant .ued-progress { margin-top: .5rem; }
@media (max-width: 860px){ #panel-dashboard .dash-primary-row { grid-template-columns: 1fr !important; } }

/* Secondary + insight rows: lower cards in tidy three-column grids */
#panel-dashboard .dash-secondary-row,
#panel-dashboard .dash-insight-row { display: grid !important; grid-template-columns: repeat(3, 1fr) !important; gap: 12px; margin: 12px 0; align-items: start; }
#panel-dashboard .dash-secondary-row > *,
#panel-dashboard .dash-insight-row > * { grid-column: auto !important; min-width: 0; }
@media (max-width: 860px){ #panel-dashboard .dash-secondary-row, #panel-dashboard .dash-insight-row { grid-template-columns: repeat(2, 1fr) !important; } }
@media (max-width: 640px){ #panel-dashboard .dash-secondary-row, #panel-dashboard .dash-insight-row { grid-template-columns: 1fr !important; } }
/* Guided Planning Path inside a 1/3 cell — keep its inner path readable */
#panel-dashboard .dash-insight-row [data-dash-card="guidance-blocks"] .ued-guidance-grid,
#panel-dashboard .dash-insight-row [data-dash-card="guidance-blocks"] .ued-panel { grid-column: 1 / -1 !important; }
#panel-dashboard .dash-insight-row [data-dash-card="guidance-blocks"] .guide-path { flex-wrap: wrap; }

/* Needs-you card — states, dots, thumb-friendly CTA (Fitts) */
#panel-dashboard .dash-needs { display: flex; flex-direction: column; padding: 15px 16px; }
#panel-dashboard .dash-needs-head { display: flex; align-items: center; gap: 7px; font-weight: 500; margin-bottom: 8px; }
#panel-dashboard .dash-needs svg { width: 16px !important; height: 16px !important; flex: none; }
#panel-dashboard .dash-needs-head svg { color: var(--forest, #2d4a3e); }
#panel-dashboard .dash-needs-list { display: flex; flex-direction: column; }
#panel-dashboard .dash-needs-row { display: flex; align-items: center; gap: 10px; width: 100%; background: transparent; border: 0; border-bottom: 1px solid var(--border, #eee); padding: 9px 2px; cursor: pointer; text-align: left; min-height: 44px; font: inherit; transition: background .12s ease; }
#panel-dashboard .dash-needs-row:last-child { border-bottom: 0; }
#panel-dashboard .dash-needs-row:hover { background: rgba(0,0,0,.03); }
#panel-dashboard .dash-needs-row:active { background: rgba(0,0,0,.06); }
#panel-dashboard .dash-needs-dot { width: 9px; height: 9px; border-radius: 50%; flex: none; }
#panel-dashboard .dash-needs-text { flex: 1; font-size: .85rem; line-height: 1.3; }
#panel-dashboard .dash-needs-text b { font-weight: 500; display: block; color: var(--ink, #222); }
#panel-dashboard .dash-needs-text em { font-style: normal; font-size: .72rem; color: var(--muted, #6a655d); }
#panel-dashboard .dash-needs-chev { color: var(--muted, #6a655d); font-size: 1.15rem; line-height: 1; }
#panel-dashboard .dash-needs-cta { margin-top: auto; display: block; width: 100%; background: var(--theme-primary, var(--forest, #2d4a3e)); color: #fff; border: 0; border-radius: 6px; padding: 11px; font-size: .85rem; font-weight: 500; cursor: pointer; min-height: 44px; transition: filter .12s ease; }
#panel-dashboard .dash-needs-cta:hover { filter: brightness(.93); }
#panel-dashboard .dash-needs-cta:active { filter: brightness(.86); }
#panel-dashboard .dash-needs-empty { display: flex; align-items: center; gap: 6px; color: #2f7050; font-size: .85rem; padding: 10px 0; }
body.dark-mode #panel-dashboard .dash-needs-row:hover { background: rgba(255,255,255,.05); }
body.dark-mode #panel-dashboard .dash-needs-text b { color: var(--dm-head, #ededed); }
body.dark-mode #panel-dashboard .dash-needs-empty { color: #8fb3a0; }

/* Squared inner elements */
#panel-dashboard .ued-progress-track, #panel-dashboard .ued-bar-track, #panel-dashboard .ued-vbar-track { border-radius: 6px !important; }

/* Responsive: stack the secondary grid on mobile, keep tablet comfy */
@media (max-width: 640px){ #panel-dashboard .ued-grid > * { grid-column: 1 / -1 !important; } }

/* Accent text → theme colour (burgundy in light, light-grey in dark) */
.nsp-progress, .nsp-ic, .nsp-cta, .nsp-chip, .coach-chip { color: var(--forest, #2d4a3e) !important; }
.nsp-chip, .coach-chip { background: color-mix(in srgb, var(--forest, #2d4a3e) 12%, transparent); }
.nsp-badge.done, .nsp-badge.finish { background: color-mix(in srgb, var(--forest, #2d4a3e) 16%, transparent); border-color: color-mix(in srgb, var(--forest, #2d4a3e) 40%, transparent); color: var(--forest, #2d4a3e) !important; }
.nsp-chip.done { color: var(--forest, #2d4a3e) !important; background: color-mix(in srgb, var(--forest, #2d4a3e) 14%, transparent); }
.nsp-finish-card, .coach-lights { color: var(--forest, #2d4a3e) !important; background: color-mix(in srgb, var(--forest, #2d4a3e) 10%, transparent); }
.nsp-step:hover .nsp-card, .nsp-step.is-current .nsp-card { border-color: var(--forest, #2d4a3e) !important; }
.budget-gift-badge { color: var(--forest, #2d4a3e) !important; background: color-mix(in srgb, var(--forest, #2d4a3e) 12%, transparent); border-color: color-mix(in srgb, var(--forest, #2d4a3e) 30%, transparent); }
.budget-recon-table .brc-gift, .budget-recon-waterfall-table .wf-gift .wf-num { color: var(--forest, #2d4a3e) !important; }
.payment-gift-note { color: var(--forest, #2d4a3e) !important; background: color-mix(in srgb, var(--forest, #2d4a3e) 10%, transparent); border-color: color-mix(in srgb, var(--forest, #2d4a3e) 26%, transparent); }
/* Primary fills → theme primary (burgundy in light, charcoal in dark) */
.nsp-badge.cur, .coach-bubble .ued-btn.primary, .coach-framing-card .ued-btn.primary, .coach-seg button.on { background: var(--theme-primary, var(--forest, #2d4a3e)) !important; border-color: var(--theme-primary, var(--forest, #2d4a3e)) !important; color: #fff !important; }
.coach-bubble .ued-btn.primary:hover, .coach-framing-card .ued-btn.primary:hover { background: color-mix(in srgb, var(--theme-primary, var(--forest, #2d4a3e)) 85%, #000) !important; border-color: color-mix(in srgb, var(--theme-primary, var(--forest, #2d4a3e)) 85%, #000) !important; }
.coach-hole { border-color: var(--theme-primary, var(--forest, #2d4a3e)); }
/* Neutralise the dark-mode green overrides added earlier */
body.dark-mode .nsp-ic, body.dark-mode .nsp-cta, body.dark-mode .nsp-chip, body.dark-mode .nsp-progress, body.dark-mode .coach-chip { color: var(--forest, #cfcfcf) !important; }
body.dark-mode .nsp-badge.cur, body.dark-mode .coach-bubble .ued-btn.primary, body.dark-mode .coach-framing-card .ued-btn.primary { background: var(--theme-primary, #3f5d50) !important; border-color: var(--theme-primary, #3f5d50) !important; }
.coach-dots { display: flex; gap: 6px; justify-content: center; margin-top: 12px; }
.coach-dots span { width: 7px; height: 7px; border-radius: 50%; background: var(--border-strong, #cfc9be); transition: all .2s ease; }
.coach-dots span.on { background: var(--forest, #2d4a3e); }
.coach-dots span.cur { width: 18px; border-radius: 20px; background: var(--forest, #2d4a3e); }
.coach-framing { position: fixed; z-index: 12001; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(18,16,12,.6); padding: 16px; }
.coach-framing-card { width: 440px; max-width: 100%; background: #ffffff; border-radius: 16px; box-shadow: 0 24px 70px rgba(0,0,0,.45); padding: 24px; box-sizing: border-box; }
.coach-choice { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 12px 0; }
.coach-choice button { padding: 12px; border: 1.5px solid var(--border, #e2ddd2); border-radius: 10px; background: var(--section-bg, #fff); cursor: pointer; text-align: left; font-size: .85rem; color: var(--ink, #222); line-height: 1.35; }
.coach-choice button.sel { border-color: var(--forest, #2d4a3e); box-shadow: 0 0 0 2px rgba(45,74,62,.15); }
.coach-toggles { display: flex; flex-direction: column; gap: 8px; margin: 10px 0 16px; }
.coach-toggle { display: flex; align-items: center; justify-content: space-between; font-size: .85rem; color: var(--ink, #222); }
.coach-seg { display: inline-flex; border: 1px solid var(--border, #e2ddd2); border-radius: 999px; overflow: hidden; }
.coach-seg button { border: 0; background: transparent; padding: 5px 14px; font-size: .8rem; cursor: pointer; color: var(--muted, #6a655d); }
.coach-seg button.on { background: var(--forest, #2d4a3e); color: #fff; }
.coach-ambient { position: fixed; right: 18px; bottom: 18px; z-index: 11000; display: flex; align-items: center; gap: 9px; background: #ffffff; border: 1px solid var(--border, #e2ddd2); border-radius: 24px; box-shadow: 0 8px 24px rgba(0,0,0,.28); padding: 8px 13px; cursor: pointer; font-size: .82rem; color: var(--ink, #222); }
.coach-ambient .ic { width: 24px; height: 24px; border-radius: 50%; background: rgba(45,74,62,.12); color: var(--forest, #2d4a3e); display: flex; align-items: center; justify-content: center; }
.coach-ambient .cx { color: var(--muted, #6a655d); margin-left: 2px; font-size: .9rem; }
body.dark-mode .coach-seg button.on, body.dark-mode .coach-choice button.sel { color: var(--dm-head, #ededed); }
body.dark-mode .coach-bubble, body.dark-mode .coach-framing-card, body.dark-mode .coach-ambient { background: var(--dm-surface, #1e1e1e); border-color: var(--dm-border, #333); }
body.dark-mode .coach-bubble h4 { color: var(--dm-head, #ededed); }
body.dark-mode .coach-toggle, body.dark-mode .coach-ambient { color: var(--dm-text, #d2d2d2); }
body.dark-mode .coach-field input, body.dark-mode .coach-choice button, body.dark-mode .coach-seg { background: var(--dm-input, #191919); border-color: var(--dm-border, #333); color: var(--dm-text, #d2d2d2); }
.coach-pulse { animation: coachPulse 1.6s ease 2; border-radius: 10px; }
@keyframes coachPulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(45,74,62,0); } 30% { box-shadow: 0 0 0 6px rgba(45,74,62,.35); } }

.budget-table {
  width: 100%;
  min-width: 980px;
  border-collapse: separate;
  border-spacing: 0;
}

.budget-table th {
  text-align: left;
  padding: .85rem .8rem;
  font-size: .74rem;
  letter-spacing: .11em;
  text-transform: uppercase;
  color: #756b5f;
  background: rgba(255,252,246,.95);
  border-bottom: 1px solid rgba(196,165,118,.22);
}

.budget-table td {
  padding: .55rem .8rem;
  border-bottom: 1px solid rgba(196,165,118,.14);
  vertical-align: middle;
}

.budget-table tr:last-child td {
  border-bottom: none;
}

.budget-table input,
.budget-table select {
  width: 100%;
  border: 1px solid transparent;
  background: transparent;
  border-radius: 7px;
  padding: .34rem .45rem;
  color: var(--forest);
}

.budget-table input:hover,
.budget-table select:hover {
  background: rgba(251,245,236,.72);
}

.budget-table input:focus,
.budget-table select:focus {
  outline: none;
  border-color: rgba(22,71,56,.24);
  background: #fff;
  box-shadow: 0 0 0 3px rgba(22,71,56,.08);
}

.budget-status-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  padding: .16rem .45rem;
  font-size: .78rem;
  min-width: 92px;
  border: 1px solid transparent;
}

.budget-status-pill.pending {
  background: #fbf5ec;
  color: #9b7040;
  border-color: rgba(184,153,104,.24);
}

.budget-status-pill.paid {
  background: color-mix(in srgb, var(--forest) 8%, #fff);
  color: var(--forest);
  border-color: rgba(47,106,83,.18);
}

.budget-status-pill.partial {
  background: #edf4fb;
  color: #3d74a5;
  border-color: rgba(61,116,165,.18);
}

.budget-status-pill select {
  width: auto;
  min-width: 84px;
  padding: .25rem 1.15rem .25rem .25rem;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: currentColor;
  font-weight: 700;
  font-size: .78rem;
  text-align: center;
  text-align-last: center;
  cursor: pointer;
}

.budget-status-pill select:focus {
  outline: none;
  box-shadow: none !important;
}

.budget-paid-check {
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
}

.budget-paid-check input {
  appearance: none;
  -webkit-appearance: none;
  width: 21px;
  height: 21px;
  border-radius: 50%;
  border: 1.6px solid rgba(184,153,104,.72);
  background: #fff;
  position: relative;
  cursor: pointer;
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.88);
}

.budget-paid-check.pending input {
  background: #fff;
  border-color: rgba(184,153,104,.72);
}

.budget-paid-check.partial input {
  background: linear-gradient(90deg, #4f8cc9 0 50%, #fff 50% 100%);
  border-color: #4f8cc9;
}

.budget-paid-check.paid input,
.budget-paid-check input:checked {
  background: var(--forest);
  border-color: var(--forest);
}

.budget-paid-check.paid input::after,
.budget-paid-check input:checked::after {
  content: "";
  position: absolute;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: 0;
  border-left: 0;
  left: 50%;
  top: 50%;
  transform: translate(-50%,-58%) rotate(45deg);
  transform-origin: center;
}

.budget-paid-check.partial input::after {
  content: "";
  position: absolute;
  width: 1px;
  height: 13px;
  background: rgba(79,140,201,.45);
  left: 9px;
  top: 2px;
  border: 0;
  transform: none;
}

.budget-icon-btn {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(196,165,118,.25);
  background: #fffdfa;
  color: var(--gold);
  display: grid;
  place-items: center;
  cursor: pointer;
}

.budget-icon-btn:hover {
  background: #fbf5ec;
}

.budget-total-row {
  background: rgba(237,244,238,.65);
}

.budget-total-row td {
  font-family: var(--font-serif);
  color: var(--forest);
  font-size: 1.02rem;
}

.budget-owned-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  flex-wrap: wrap;
  margin: .2rem 0 .7rem;
  padding: .5rem .7rem;
  border: 1px solid rgba(196,165,118,.32);
  border-radius: 10px;
  background: linear-gradient(90deg,rgba(251,245,236,.9),rgba(255,253,249,.7));
}

.budget-owned-badge {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  font-size: .78rem;
  font-weight: 600;
  color: var(--forest);
}

.budget-owned-badge svg {
  width: 15px;
  height: 15px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.budget-owned-table th.budget-owned-amt,
.budget-owned-table td.budget-owned-amt {
  text-align: right;
  white-space: nowrap;
}

.budget-owned-table td {
  color: #4a443d;
}

.budget-total-row .budget-total-sub {
  display: block;
  font-family: var(--font-sans);
  font-size: .72rem;
  color: #6f6962;
  margin-top: .1rem;
}

.budget-table-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  padding: .9rem 1rem 1rem;
  border-top: 1px solid rgba(196,165,118,.16);
}

.budget-tip {
  font-size: .82rem;
  color: #7a6e5e;
  font-style: italic;
}

.budget-empty-note {
  padding: 1.1rem;
  color: #7a7268;
  text-align: center;
}

.budget-scripture-footer {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1.1rem;
  padding: 1.1rem 1rem 0;
  margin: 1rem 0 0;
  border-top: 1px solid rgba(196,165,118,.24);
  color: var(--gold);
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.08rem;
  text-align: center;
}

.budget-scripture-footer .leaf-orn {
  width: 56px;
  flex: 0 0 auto;
}

.budget-scripture-footer cite {
  display: block;
  font-family: var(--font-sans);
  font-style: normal;
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .66rem;
  margin-top: .36rem;
  color: var(--gold);
}

@media(max-width:1280px) {
  .budget-summary {
    grid-template-columns: repeat(4,minmax(0,1fr));
  }

}

@media(max-width:1120px) {
  .budget-stat-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .budget-summary {
    grid-template-columns: repeat(4,minmax(0,1fr));
  }

  .budget-selected-editor {
    grid-template-columns: 1fr 1fr;
  }

}

@media(max-width:760px) {
  .budget-stat-grid,
  .budget-summary,
  .budget-selected-editor {
    grid-template-columns: 1fr;
  }

  .budget-section-head {
    flex-direction: column;
  }

  .budget-scripture-footer {
    flex-direction: column;
    gap: .35rem;
  }

}

