/* Wedding Day Timeline v35 refinements */

#panel-timeline .wday-card-icon {
  display: grid!important;
  place-items: center!important;
}

#panel-timeline .wday-card-icon svg {
  display: block;
  width: 20px!important;
  height: 20px!important;
  stroke: currentColor!important;
  fill: none!important;
  stroke-width: 1.7!important;
  stroke-linecap: round!important;
  stroke-linejoin: round!important;
}

#panel-timeline .wday-soft-link:focus-visible {
  outline: 2px solid rgba(22,71,56,.35);
  outline-offset: 2px;
}

@media(max-width:1180px) {
  .wday-stat-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .wday-lower-grid {
    grid-template-columns: 1fr;
  }

  .wday-contact-row {
    grid-template-columns: 34px 1fr 1fr auto;
  }

  .wday-path {
    grid-auto-columns: minmax(180px,1fr);
    min-width: 980px;
  }

}

@media(max-width:720px) {
  .wday-stat-grid {
    grid-template-columns: 1fr;
  }

  .wday-title {
    font-size: 2.25rem;
  }

  .wday-table-head {
    align-items: flex-start;
  }

  .wday-table-head .btn {
    width: 100%;
    justify-content: center;
  }

  .wday-scripture-footer {
    flex-direction: column;
    gap: .35rem;
  }

  .wday-contact-row {
    grid-template-columns: 34px 1fr;
  }

  .wday-contact-phone {
    grid-column: 2
  }

  .wday-contact-name {
    grid-column: 2
  }

}

/* Responsive horizontal timeline connector fix */

#panel-timeline .wday-path {
  --wday-count: 1;
  min-width: max(100%, calc(var(--wday-count) * 170px))!important;
}

#panel-timeline .wday-path::before {
  left: calc((100% / var(--wday-count)) / 2)!important;
  right: calc((100% / var(--wday-count)) / 2)!important;
}

#panel-timeline .wday-path[data-count="0"]::before,
#panel-timeline .wday-path[data-count="1"]::before {
  opacity: 0;
}

