/* Print utilities (Track 0.4) — screen defaults */
.print-only { display: none; }

@media print {

  /* Print utilities (Track 0.4) — shown/broken only when printing */
  .print-only { display: block !important; }
  .print-page-break { break-before: page; page-break-before: always; }

  /* ── Global: hide all UI chrome ── */

  #topbar,
  #sidebar,
  #backup-banner,
  #storage-warning,
  #profile-bar,
  #quick-jump-wrap,
  .add-row-btn,
  .del-btn,
  .form-actions,
  .bulk-bar,
  .bulk-table-row,
  .sel-col,
  .payment-icon-btn,
  .table-trash-btn,
  .page-help-banner,
  .page-scripture-footer,
  .page-prayer-prompt,
  .no-print,
  [class*="filter-group"],
  [class*="search-wrap"],
  [class*="search-actions"],
  .tasks-toolbar-row,
  .guest-toolbar,
  .guest-filter-row,
  .guest-filter-group,
  #backup-reminder,
  #start-here-card,
  .dash-chart-card,
  #section-progress-card,
  #smart-create-pane,
  .smart-create-actions,
  .smart-view-tabs,
  .smart-filter,
  #wizard-modal,
  .modal-overlay,
  .hm-table-actions,
  .hc-actions,
  .log-actions,
  .et-actions,
  .pkt-actions,
  .et-cat-tabs,
  .et-stats,
  .rfl-tabs,
  .log-tabs,
  .pkt-section-tabs,
  .pkt-sub-tabs {
    display: none !important;
  }

  /* ── Hide all buttons except print-specific ones ── */

  .btn,
  button:not(.print-keep) {
    display: none !important;
  }

  /* ── Layout: full width, no sidebar ── */

  #layout {
    display: block !important;
  }

  #main {
    padding: 0 !important;
    margin: 0 !important;
    width: 100% !important;
    max-width: none !important;
  }

  .panel {
    padding: .5rem 0 !important;
    width: 100% !important;
    max-width: none !important;
  }

  .panel:not(.active) {
    display: none !important;
  }

  /* ── Cards: clean borders, no shadows ── */

  .card,
  .prayer-card,
  .counsel-card,
  .essentials-action-card,
  .essentials-filter-card,
  .essentials-table-card,
  .info-card,
  .stat-tile,
  .et-card,
  .pkt-card,
  .rfl-card,
  .log-card,
  .budget-card,
  .gift-card,
  .gift-table-card,
  .gift-note-card,
  .hm-card,
  .hm-stat-card,
  .counsel-stat-card,
  .smart-side-card {
    box-shadow: none !important;
    border: 1px solid #ccc !important;
    break-inside: avoid;
    margin-bottom: .5rem !important;
  }

  /* ── Scripture banner ── */

  #scripture-banner {
    color: #2D4A3E !important;
    background: none !important;
    border-bottom: 1px solid #ddd;
  }

  /* ── Tables: clean borders, avoid page breaks inside rows ── */

  table {
    page-break-inside: auto !important;
    border-collapse: collapse !important;
  }

  tr {
    page-break-inside: avoid !important;
  }

  th {
    background: #f0ede8 !important;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  /* ── Form inputs: show values, hide borders ── */

  select,
  input[type="text"],
  input[type="number"],
  input[type="date"],
  input[type="email"],
  input[type="search"],
  textarea {
    border: none !important;
    box-shadow: none !important;
    padding: 2px !important;
    background: transparent !important;
  }

  input[type="checkbox"] {
    -webkit-print-color-adjust: exact;
