  height: 126px;
  border: 1px solid rgba(196,165,118,.18);
  border-radius: 10px;
  margin: .2rem 0 .85rem;
  overflow: hidden;
  position: relative;
  background: linear-gradient(180deg,rgba(245,239,228,.2),rgba(45,74,62,.12)),linear-gradient(135deg,#f4ecdd,#e6e0d1 45%,#cfd6c5);
}

.hm-travel-overview-art::before {
  content: "";
  position: absolute;
  inset: auto -10% 0 -10%;
  height: 78%;
  background: radial-gradient(ellipse at 25% 100%,rgba(45,74,62,.25),transparent 42%),radial-gradient(ellipse at 64% 95%,rgba(45,74,62,.22),transparent 48%),linear-gradient(165deg,transparent 35%,rgba(255,253,249,.5) 36% 41%,transparent 42%);
