.hm-travel-overview-art::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 45%;
  background: repeating-linear-gradient(165deg,rgba(22,71,56,.18) 0 2px,transparent 2px 12px);
  opacity: .5;
}

.hm-travel-overview-art span {
  position: absolute;
  right: 28px;
  bottom: 35px;
