  table-layout: fixed!important;
}

.cat-table th,
.cat-table td {
  box-sizing: border-box!important;
  padding: .46rem .52rem!important;
  border-right: 1px solid rgba(196,165,118,.18)!important;
  border-bottom: 1px solid rgba(196,165,118,.16)!important;
  line-height: 1.25!important;
  vertical-align: middle!important;
}

.cat-table th:last-child,
.cat-table td:last-child {
  border-right: 0!important;
}

.cat-table thead th {
  height: 38px!important;
  background: #fff8ef!important;
  color: #6e655c!important;
  font-size: .68rem!important;
  letter-spacing: .08em!important;
  text-transform: uppercase!important;
  text-align: left!important;
  white-space: nowrap!important;
  overflow: hidden!important;
  text-overflow: ellipsis!important;
}

.cat-table tbody td {
  height: 40px!important;
  background: #fffdf9;
}

.cat-table tbody tr:nth-child(even) td {
  background: rgba(251,245,236,.28);
}

.cat-table input,
.cat-table select,
.cat-table textarea {
  min-height: 28px!important;
  padding: .24rem .34rem!important;
  border-radius: 6px!important;
  font-size: .8rem!important;
  line-height: 1.2!important;
  border: 1px solid transparent;
  background: transparent;
  color: var(--forest);
}

.cat-table select {
  appearance: auto;
  background: transparent;
}

.cat-table input:hover,
.cat-table select:hover,
.cat-table textarea:hover {
  background: rgba(251,245,236,.74);
}

.cat-table input:focus,
.cat-table select:focus,
.cat-table textarea:focus {
  outline: none;
  border-color: rgba(22,71,56,.24);
  background: #fff;
  box-shadow: 0 0 0 3px rgba(22,71,56,.08);
}

#panel-catering .cat-table .cell-ta {
  min-height: 30px!important;
  max-height: 72px;
  resize: vertical;
  overflow: auto;
}

#panel-catering .sel-col,
#panel-catering th.sel-col,
#panel-catering td.sel-col {
  width: 42px!important;
  min-width: 42px!important;
  max-width: 42px!important;
  text-align: center!important;
  padding-left: .35rem!important;
  padding-right: .35rem!important;
}

#panel-catering .sel-col input[type="checkbox"],
#panel-catering .cat-check {
  appearance: none;
  -webkit-appearance: none;
  width: 16px!important;
  height: 16px!important;
  min-width: 16px!important;
  min-height: 16px!important;
  margin: 0;
  display: inline-grid;
  place-content: center;
  border: 1.5px solid rgba(22,71,56,.32);
  border-radius: 4px;
  background: #fffdf9;
  box-shadow: none;
  cursor: pointer;
  vertical-align: middle;
  padding: 0!important;
  position: relative;
}

#panel-catering .sel-col input[type="checkbox"]:checked,
#panel-catering .cat-check:checked {
  background: var(--forest);
  border-color: var(--forest);
}

#panel-catering .sel-col input[type="checkbox"]::after,
#panel-catering .cat-check::after {
  content: "";
  width: 4px;
  height: 8px;
  border: solid #fff;
  border-width: 0 1.7px 1.7px 0;
  transform: rotate(45deg) scale(0);
  transform-origin: center;
}

#panel-catering .sel-col input[type="checkbox"]:checked::after,
#panel-catering .cat-check:checked::after {
  transform: rotate(45deg) scale(1);
}

#panel-catering .catering-bulk-card {
  display: grid;
  grid-template-columns: minmax(170px,.55fr) minmax(520px,1.45fr) auto;
  gap: .85rem;
  align-items: end;
  border: 1px solid rgba(196,165,118,.26);
  border-radius: 12px;
  background: linear-gradient(90deg,rgba(251,245,236,.92),rgba(255,253,249,.88));
  box-shadow: 0 7px 18px rgba(54,39,20,.035);
  padding: .78rem .95rem;
  margin: .86rem 1.1rem .9rem;
}

#panel-catering .catering-bulk-card .bulk-head {
  align-items: flex-start;
  flex-direction: column;
  gap: .16rem;
}

#panel-catering .catering-bulk-card .bulk-head strong {
  font-family: var(--font-serif);
  font-size: 1.04rem;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--forest);
}

#panel-catering .catering-bulk-card .bulk-controls {
  display: flex;
  align-items: end;
  justify-content: flex-start;
  gap: .55rem;
  flex-wrap: wrap;
}

#panel-catering .catering-bulk-card .bulk-field {
  min-width: 155px;
  flex: 1 1 155px;
}

#panel-catering .catering-bulk-card .bulk-actions {
  justify-content: flex-end;
}

.cat-pill-row {
  display: flex;
  align-items: center;
  gap: .35rem;
  flex-wrap: wrap;
}

.cat-pill {
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  border-radius: 999px;
  padding: .16rem .48rem;
  font-size: .7rem;
  font-weight: 700;
  line-height: 1;
  background: #f4efe6;
  color: #7a6e5e;
  border: 1px solid rgba(196,165,118,.15);
  white-space: nowrap;
}

.cat-pill.green {
  background: color-mix(in srgb, var(--forest) 8%, #fff);
  color: var(--forest);
}

.cat-pill.gold {
  background: #fbf5ec;
  color: #9b7040;
}

.cat-pill.blue {
  background: #edf4fb;
  color: #3d74a5;
}

.cat-pill.red {
  background: #fbe9e3;
  color: #bd473d;
}

.cat-kids-card {
  display: grid;
  grid-template-columns: 1.25fr .75fr;
  gap: 0;
}

.cat-kids-list {
  padding: 1.1rem;
