}

.cat-setting-title {
  font-weight: 800;
  color: var(--forest);
  font-size: .88rem;
  margin-bottom: .28rem;
}

.cat-color-chip {
  display: inline-flex;
  align-items: center;
  gap: .34rem;
  color: #7a6e5e;
  font-size: .78rem;
}

.cat-color-chip i {
  width: 16px;
  height: 16px;
  border-radius: 3px;
  border: 1px solid rgba(0,0,0,.12);
  display: inline-block;
  background: var(--chip,#d4b896);
}

.cat-setting-sub {
  font-size: .78rem;
  color: #6f6962;
  margin-top: .18rem;
}

.cat-setting-total {
  text-align: right;
  margin-top: .8rem;
  color: var(--forest);
  font-size: .86rem;
}

.cat-setting-total strong {
  color: var(--forest);
}

.cat-bottom-grid {
  display: grid;
  grid-template-columns: 1fr .75fr;
  gap: 1.05rem;
