/* Planner history, undo, and redo */

.history-top-actions {
  gap: .35rem;
}

.btn-history-action[disabled] {
  opacity: .45;
  cursor: not-allowed;
}

.history-title-wrap {
  text-align: center;
  margin: 0 auto 1.15rem;
  max-width: 860px;
}

.history-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem,4vw,3.2rem);
  font-weight: 500;
  color: var(--forest);
  margin: 0;
}

.history-subtitle {
  color: #6f6962;
  font-size: .98rem;
  margin: .35rem auto 0;
  line-height: 1.55;
}

.history-stat-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: .85rem;
  margin-bottom: 1rem;
}

.history-stat-card {
  border: 1px solid rgba(196,165,118,.34);
  border-radius: 10px;
  background: #fffdf9;
  padding: 1rem;
  display: flex;
  align-items: center;
  gap: .75rem;
}

.history-stat-icon {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--gold-pale);
  border: 1px solid rgba(184,153,104,.32);
  display: grid;
  place-items: center;
  color: var(--gold);
}

.history-stat-icon svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.history-stat-kicker {
  text-transform: uppercase;
  letter-spacing: .09em;
  font-size: .68rem;
  color: #7d7469;
  font-weight: 800;
}

.history-stat-value {
  font-family: var(--font-serif);
  font-size: 1.65rem;
  color: var(--forest);
  line-height: 1.05;
}

.history-toolbar {
  border: 1px solid rgba(196,165,118,.34);
  border-radius: 10px;
  background: #fffdf9;
  padding: 1rem;
  margin-bottom: 1rem;
  display: grid;
  grid-template-columns: minmax(180px,260px) 1fr auto;
  gap: .9rem;
  align-items: end;
}

.history-toolbar label {
  display: flex;
  flex-direction: column;
  gap: .28rem;
  font-size: .78rem;
  font-weight: 800;
  color: var(--forest);
}

.history-toolbar input,
.history-toolbar select {
  border: 1px solid rgba(184,153,104,.4);
  border-radius: 7px;
  padding: .55rem .65rem;
  background: #fff;
  color: var(--charcoal);
}

.history-help-text {
  font-size: .84rem;
