  line-height: 1.45;
}

.history-table-card {
  border: 1px solid rgba(196,165,118,.34);
  border-radius: 10px;
  background: #fffdf9;
  overflow: hidden;
}

.history-table-title {
  font-family: var(--font-serif);
  font-size: 1.08rem;
  color: var(--forest);
  padding: .75rem 1rem;
  border-bottom: 1px solid rgba(196,165,118,.28);
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
}

.history-table-wrap {
  overflow: auto;
}

.history-table {
  width: 100%;
  border-collapse: collapse;
  font-size: .86rem;
}

.history-table th {
  background: linear-gradient(180deg,var(--forest),var(--forest-deep));
  color: #fff;
  text-align: left;
  padding: .65rem .7rem;
  font-size: .73rem;
  text-transform: uppercase;
  letter-spacing: .04em;
}

.history-table td {
  border-bottom: 1px solid rgba(196,165,118,.22);
  padding: .66rem .7rem;
  vertical-align: top;
}

.history-table tbody tr:nth-child(even) {
  background: rgba(249,247,244,.55);
}

.history-badge {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: .18rem .52rem;
  background: var(--gold-pale);
  color: var(--forest);
  font-weight: 800;
  font-size: .72rem;
  border: 1px solid rgba(184,153,104,.28);
}

.history-empty {
  padding: 1.5rem;
  text-align: center;
  color: #746b60;
  font-style: italic;
}

.history-drawer {
  position: fixed;
  top: 0;
  right: 0;
  width: min(420px,92vw);
  height: 100vh;
  background: #fffdf9;
  border-left: 1px solid rgba(196,165,118,.38);
  box-shadow: -18px 0 45px rgba(31,21,14,.2);
  z-index: 1500;
  transform: translateX(105%);
  transition: transform .22s ease;
  display: flex;
  flex-direction: column;
}

.history-drawer.open {
  transform: translateX(0);
}

.history-drawer-head {
  padding: 1rem;
  border-bottom: 1px solid rgba(196,165,118,.28);
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
}

.history-drawer-head h3 {
  font-family: var(--font-serif);
  color: var(--forest);
  font-size: 1.35rem;
  margin: 0;
}

.history-drawer-close {
  border: 0;
  background: transparent;
  color: var(--forest);
  font-size: 1.7rem;
  line-height: 1;
  cursor: pointer;
}

.history-drawer-body {
  padding: 1rem;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: .7rem;
}

.history-drawer-item {
  border: 1px solid rgba(196,165,118,.26);
  border-radius: 9px;
  padding: .7rem;
  background: #fff;
}

.history-drawer-time {
  font-size: .72rem;
  color: #7d7469;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .06em;
}

.history-drawer-action {
  font-weight: 800;
  color: var(--forest);
  margin: .15rem 0;
}

.history-drawer-detail {
  font-size: .82rem;
  color: #655d55;
  line-height: 1.4;
}

.history-drawer-actions {
  padding: 1rem;
  border-top: 1px solid rgba(196,165,118,.28);
  display: flex;
  gap: .55rem;
  flex-wrap: wrap;
}

@media(max-width:900px) {
  .history-stat-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .history-toolbar {
    grid-template-columns: 1fr;
  }

}

@media(max-width:560px) {
  .history-stat-grid {
    grid-template-columns: 1fr;
  }

  .history-table {
    min-width: 720px;
  }

}

/* ════════════════════════════════════════════════
V4 EDITORIAL — reusable component library
Port of "Dashboard Mockup — Editorial v4" design language.
Pure presentation. Offline-safe (inline SVG icons, no CDN).
Used to convert every page to the flat luxury-editorial look:
shapeless tan/transparent sections, uppercase underlined heads
with gold line-icons, hairline tables, borderless serif-numeral
stat strips, serif numerals.
════════════════════════════════════════════════ */

:root {

  /* v4 colors DERIVE from the active theme vars (set by applyTheme) so the
  whole editorial UI re-themes when the user changes the theme. Fallbacks
  keep it working before a theme is applied. */

  --v4-forest: var(--forest, #2D4A3E);
  --v4-gold: var(--gold, #B89968);
  --v4-gold-lt: var(--gold-lt, #C9B896);
  --v4-soft: var(--gold-pale, #F4EEE3);
  --v4-page: var(--ivory-dk, #EFE9DD);
  --v4-content: var(--ivory, #FBF9F6);
  --v4-ink: #3b3228;
  --v4-muted: #8a7e6b;
  --v4-muted2: #a89a85;
  --v4-muted3: #6f6456;
  --v4-hair: #EFE9DD;
  --v4-hair2: #E8E1D4;
  --v4-hair3: #F1EBDF;
  --v4-serif: Georgia,'Times New Roman',serif;
}

/* ── Section head: uppercase, gold line-icon, forest underline rule ── */

.v4-head {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 10px;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--v4-forest);
  font-weight: 600;
  padding-bottom: .5rem;
  margin-bottom: .95rem;
  border-bottom: 1px solid var(--v4-forest);
}

.v4-head .v4-ico,
.v4-head svg {
  width: 14px;
  height: 14px;
  color: var(--v4-gold);
  stroke: var(--v4-gold);
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: 0 0 auto;
}

.v4-head .v4-head-tag {
  margin-left: auto;
  font-size: 9px;
  letter-spacing: .1em;
  color: var(--v4-gold);
  font-weight: 500;
}

/* Thin gold rule + section eyebrow (for sub-dividers) */

.v4-thinrule {
  height: 1px;
  background: var(--v4-gold);
  opacity: .35;
  margin: 1.25rem 0;
}

.v4-eyebrow {
  font-size: 9px;
  letter-spacing: .32em;
  text-transform: uppercase;
  color: var(--v4-gold);
  font-weight: 500;
}

/* ── Soft shapeless tan block (no border / radius / shadow) ── */

.v4-soft {
  background: var(--v4-soft);
  padding: 1.25rem 1.1rem;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

.v4-soft-center {
  text-align: center;
}

.v4-num {
  font-family: var(--v4-serif);
  color: var(--v4-forest);
  line-height: 1;
}

.v4-soft-num {
  font-family: var(--v4-serif);
  font-size: 54px;
  color: var(--v4-forest);
  line-height: 1;
}

.v4-soft-sub {
  font-size: 10px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--v4-gold);
  margin-top: 6px;
}

.v4-soft-date {
  font-size: 12px;
  color: var(--v4-muted);
  margin-top: 8px;
}

.v4-verse {
  font-family: var(--v4-serif);
  font-style: italic;
  font-size: 12px;
  color: var(--v4-muted);
  line-height: 1.55;
}

.v4-verse cite {
  display: block;
  font-style: normal;
  font-family: var(--font-sans);
  font-size: 9px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--v4-gold);
  margin-top: 4px;
}

/* ── Borderless stat strip with vertical hairline dividers ── */

.v4-stats {
  display: flex;
  margin-bottom: 1.75rem;
}

.v4-stat {
  flex: 1;
  padding: 0 1rem;
  border-right: 1px solid var(--v4-hair2);
}

.v4-stat:first-child {
  padding-left: 0;
}

.v4-stat:last-child {
  border-right: none;
  padding-right: 0;
}

.v4-stat-top {
  display: flex;
  align-items: center;
  gap: 6px;
}

.v4-stat-top .v4-ico,
.v4-stat-top svg {
  width: 15px;
  height: 15px;
  color: var(--v4-gold);
  stroke: var(--v4-gold);
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.v4-stat-label {
  font-size: 9px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--v4-muted);
}

.v4-stat-val {
  font-family: var(--v4-serif);
  font-size: 25px;
  color: var(--v4-forest);
  margin-top: 4px;
  line-height: 1;
}

.v4-stat-sub {
  font-size: 10px;
  color: var(--v4-muted2);
  margin-top: 4px;
}

/* ── Hairline editorial table ── */

.v4-table {
  width: 100%;
  border-collapse: collapse;
}

.v4-table td {
  padding: .42rem 0;
  border-bottom: 1px solid var(--v4-hair);
  font-size: 11px;
  vertical-align: middle;
}

.v4-table tr:last-child td {
  border-bottom: none;
}

.v4-td-date {
  color: var(--v4-gold);
  font-weight: 500;
  white-space: nowrap;
  width: 54px;
}

.v4-td-name {
  color: var(--v4-forest);
}

.v4-td-diff {
  color: var(--v4-muted2);
  text-align: right;
  white-space: nowrap;
  font-size: 10px;
}

.v4-row-hl .v4-td-name {
  font-weight: 600;
}

.v4-row-hl .v4-td-diff {
  color: var(--v4-gold);
  font-weight: 600;
}

/* ── Info row (4-cell soft strip) ── */

.v4-info {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: 0;
  background: var(--v4-soft);
  margin-bottom: 1.75rem;
}

.v4-info-cell {
  padding: .7rem .9rem;
  border-right: 1px solid var(--v4-hair2);
}

.v4-info-cell:last-child {
  border-right: none;
}

.v4-info-k {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 9px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--v4-gold);
  font-weight: 600;
}

.v4-info-k .v4-ico,
.v4-info-k svg {
  width: 12px;
  height: 12px;
  color: var(--v4-gold);
  stroke: var(--v4-gold);
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.v4-info-v {
  font-size: 12.5px;
  color: var(--v4-forest);
  font-weight: 500;
  margin-top: 3px;
  line-height: 1.3;
}

/* ── Gold left-border banner ── */

.v4-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: .6rem .9rem;
  background: var(--v4-soft);
  border-left: 2px solid var(--v4-gold);
}

.v4-banner .v4-ico,
.v4-banner > svg {
  width: 17px;
  height: 17px;
  color: var(--v4-gold);
  stroke: var(--v4-gold);
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: 0 0 auto;
}

.v4-banner-text {
  font-size: 11px;
  color: var(--v4-muted);
  flex: 1;
}

.v4-banner-text b {
  color: var(--v4-forest);
  font-weight: 600;
}

.v4-banner-btn {
  font-size: 10px;
  padding: .35rem .75rem;
  border: 1px solid var(--v4-gold);
  background: transparent;
  color: #946f33;
  cursor: pointer;
  font-weight: 600;
  letter-spacing: .04em;
  border-radius: 0;
}

/* ── Progress list (thin gold bars) ── */

.v4-prog-item {
  margin-bottom: .65rem;
}

.v4-prog-row {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  margin-bottom: 4px;
}

.v4-prog-name {
  color: var(--v4-muted3);
}

.v4-prog-pct {
  font-family: var(--v4-serif);
  color: var(--v4-forest);
}

.v4-prog-track {
  height: 2px;
  background: var(--v4-hair2);
}

.v4-prog-fill {
  height: 100%;
  background: var(--v4-gold);
}

/* ── "Next up" list ── */

.v4-next {
  list-style: none;
  margin: 0;
  padding: 0;
}

.v4-next-item {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: .5rem 0;
  border-bottom: 1px solid var(--v4-hair);
}

.v4-next-item:last-of-type {
  border-bottom: none;
}

.v4-next-idx {
  font-family: var(--v4-serif);
  font-size: 11px;
  color: var(--v4-gold-lt);
  min-width: 16px;
}

.v4-next-text {
  font-size: 12px;
  color: var(--v4-forest);
  flex: 1;
  line-height: 1.35;
}

.v4-next-when {
  font-size: 10px;
  color: var(--v4-muted2);
  white-space: nowrap;
}

/* ── Section-progress dot grid ── */

.v4-sp-grid {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: 0 1.75rem;
}

.v4-sp-item {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: .32rem 0;
  border-bottom: 1px solid var(--v4-hair3);
  font-size: 11px;
}

.v4-sp-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.v4-sp-dot.done {
  background: var(--v4-forest);
}

.v4-sp-dot.prog {
  background: var(--v4-gold);
}

.v4-sp-dot.none {
  background: #DDD5C6;
}

.v4-sp-name {
  color: var(--v4-forest);
}

.v4-sp-meta {
  color: var(--v4-muted2);
  margin-left: auto;
  font-size: 10px;
}

/* ── Horizontal budget bars ── */

.v4-bars {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.v4-bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.v4-bar-cat {
  font-size: 10px;
  color: var(--v4-muted3);
  min-width: 62px;
  text-align: right;
}

.v4-bar-track {
  flex: 1;
  height: 8px;
  background: var(--v4-page);
}

.v4-bar-fill {
  height: 100%;
}

.v4-bar-amt {
  font-size: 10px;
  color: var(--v4-forest);
  min-width: 42px;
  font-family: var(--v4-serif);
  text-align: right;
}

/* ── "View more" foot link ── */

.v4-foot {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  color: var(--v4-gold);
  margin-top: .9rem;
  cursor: pointer;
}

.v4-foot svg {
  width: 13px;
  height: 13px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ── Verse footer band ── */

.v4-footer {
  text-align: center;
  padding-top: 1rem;
  border-top: 1px solid var(--v4-forest);
  margin-top: 1.5rem;
}

.v4-footer-text {
  font-family: var(--v4-serif);
  font-style: italic;
  font-size: 12px;
  color: var(--v4-muted);
}

.v4-footer-orn {
  color: var(--v4-gold);
  font-size: 14px;
  margin: 0 8px;
}

/* ════════════════════════════════════════════════
V4 EDITORIAL — global flatten (applies the v4 look to EVERY page)
Flips the shared primitives from the old rounded-card look to the
flat luxury-editorial v4 language. Pure presentation; no JS touched.
════════════════════════════════════════════════ */

/* Flat editorial canvas (v4: warm ivory, no gradients) */

body.editorial-v4 {
  background: var(--v4-content) !important;
}

/* — Remove the card shape across all content panels — */

.panel .card,
.panel .chart-wrap,
.panel .note-card,
.panel .banner-scripture-card {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 0 .25rem !important;
  margin-bottom: 1.85rem !important;
}

/* — Section heads → uppercase, forest underline rule, gold line-icon — */

.panel .card-title,
.panel .chart-title {
  font-family: var(--font-sans) !important;
  font-size: .72rem !important;
  font-weight: 600 !important;
  letter-spacing: .2em !important;
  text-transform: uppercase !important;
  color: var(--v4-forest) !important;
  text-align: left !important;
  display: flex !important;
  align-items: center;
  gap: 7px;
  padding: 0 0 .5rem !important;
  margin: 0 0 1.05rem !important;
  border-bottom: 1px solid var(--v4-forest) !important;
}

.panel .card-title .line-icon,
.panel .card-title svg,
.panel .chart-title .line-icon,
.panel .chart-title svg {
  width: 14px !important;
  height: 14px !important;
  color: var(--v4-gold) !important;
  stroke: var(--v4-gold) !important;
}

/* — Page masthead title → elegant serif — */

.panel .page-title {
  font-family: var(--v4-serif) !important;
  text-transform: none !important;
  letter-spacing: .01em !important;
  font-weight: 400 !important;
  color: var(--v4-forest) !important;
}

.panel .page-subtitle {
  font-style: italic !important;
  color: var(--v4-muted) !important;
}

/* — Tables → hairline editorial — */

.panel th {
  background: transparent !important;
  color: var(--v4-forest) !important;
  border-bottom: 1px solid var(--v4-forest) !important;
  font-size: .64rem !important;
  letter-spacing: .12em !important;
}

.panel td {
  border-bottom: 1px solid var(--v4-hair) !important;
}

.panel tr:last-child td {
  border-bottom: none !important;
}

.panel tr:hover td {
  background: var(--v4-soft) !important;
}

/* — Stat tiles → borderless serif-numeral strip with hairline dividers — */

.panel .stat-grid {
  gap: 0 !important;
}

.panel .stat-card {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border-right: 1px solid var(--v4-hair2) !important;
  padding: .1rem 1.1rem !important;
}

.panel .stat-card:last-child {
  border-right: none !important;
}

.panel .stat-val {
  font-family: var(--v4-serif) !important;
  color: var(--v4-forest) !important;
}

.panel .stat-label {
  color: var(--v4-muted) !important;
  letter-spacing: .12em !important;
}

/* — Scripture pull → flat tan with gold rule — */

.panel .scripture-pull {
  background: var(--v4-soft) !important;
  border-left: 2px solid var(--v4-gold) !important;
  border-radius: 0 !important;
}

/* — Add-row / dashed buttons → square editorial — */

.panel .add-row-btn {
  border-radius: 0 !important;
}

/* — Modals → square editorial — */

.modal {
  border-radius: 0 !important;
}

/* ── Dashboard-specific flatten (override the rounded-card redesign) ── */

.dashboard-redesign .dash-title .page-title {
  text-transform: none !important;
  font-size: 2.2rem !important;
  font-weight: 400 !important;
}

/* Info row → flat tan 4-cell strip */

.dashboard-redesign .dash-info-grid {
  gap: 0 !important;
  background: var(--v4-soft);
  margin-bottom: 1.75rem !important;
}

.dashboard-redesign .info-card {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border-right: 1px solid var(--v4-hair2) !important;
  grid-template-columns: 1fr !important;
  gap: 4px !important;
  padding: .85rem 1rem !important;
}

.dashboard-redesign .dash-info-grid > .info-card:last-child {
  border-right: none !important;
}

.dashboard-redesign .info-icon {
  width: auto !important;
  height: auto !important;
  background: none !important;
  border: none !important;
}

.dashboard-redesign .info-icon svg {
  width: 14px !important;
  height: 14px !important;
  color: var(--v4-gold) !important;
  stroke: var(--v4-gold) !important;
}

.dashboard-redesign .info-label {
  color: var(--v4-gold) !important;
  letter-spacing: .12em !important;
}

.dashboard-redesign .info-value {
  font-size: 1.05rem !important;
}

.dashboard-redesign .info-photo {
  width: 42px !important;
  height: 42px !important;
}

/* Stat tiles → borderless strip */

.dashboard-redesign .dash-stat-grid {
  gap: 0 !important;
}

.dashboard-redesign .stat-tile {
  border-right: 1px solid var(--v4-hair2);
  padding: .1rem 1.05rem;
}

.dashboard-redesign .dash-stat-grid > .stat-tile:last-child {
  border-right: none;
}

.dashboard-redesign .stat-tile-top {
  grid-template-columns: 1fr !important;
  gap: 4px !important;
}

.dashboard-redesign .stat-tile .info-icon svg,
.dashboard-redesign .stat-tile svg {
  width: 15px !important;
  height: 15px !important;
  color: var(--v4-gold) !important;
  stroke: var(--v4-gold) !important;
}

.dashboard-redesign .stat-tile-val {
  font-size: 1.7rem !important;
}

.dashboard-redesign .stat-tile-link {
  border-top: 1px solid var(--v4-hair2) !important;
}

/* Countdown card → flat tan soft block (was dark gradient) */

.dashboard-redesign .countdown-card {
  background: var(--v4-soft) !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: var(--v4-forest) !important;
}

.dashboard-redesign .countdown-card .card-kicker {
  color: var(--v4-gold) !important;
  font-size: 10px !important;
  letter-spacing: .2em !important;
}

.dashboard-redesign .cd-date {
  color: var(--v4-muted) !important;
  font-size: .95rem !important;
}

.dashboard-redesign .cd-num {
  color: var(--v4-forest) !important;
  text-shadow: none !important;
}

.dashboard-redesign .cd-label {
  color: var(--v4-gold) !important;
}

.dashboard-redesign .cd-parts {
  border-color: var(--v4-hair2) !important;
}

.dashboard-redesign .cd-parts span {
  border-color: var(--v4-hair2) !important;
}

.dashboard-redesign .cd-parts b {
  color: var(--v4-forest) !important;
}

.dashboard-redesign .cd-parts em {
  color: var(--v4-muted) !important;
}

.dashboard-redesign .cd-verse {
  color: var(--v4-muted) !important;
}

.dashboard-redesign .cd-verse cite {
  color: var(--v4-gold) !important;
}

/* Progress suite + next-up → flat */

.dashboard-redesign .progress-suite,
.dashboard-redesign .next-up-card {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 0 .25rem !important;
}

.dashboard-redesign .progress-suite .card-title,
.dashboard-redesign .next-up-card .card-title {
  text-align: left !important;
  font-family: var(--font-sans) !important;
  font-size: .72rem !important;
  letter-spacing: .2em !important;
  border-bottom: 1px solid var(--v4-forest) !important;
  padding-bottom: .5rem !important;
}

.dashboard-redesign .dprog-icon {
  background: none !important;
  border: none !important;
  width: auto !important;
}

.dashboard-redesign .dprog-icon svg {
  color: var(--v4-gold) !important;
  stroke: var(--v4-gold) !important;
}

.dashboard-redesign .dprog-mid .progress-track {
  height: 2px !important;
  background: var(--v4-hair2) !important;
  border-radius: 0 !important;
}

.dashboard-redesign .dprog-mid .progress-track span {
  background: var(--v4-gold) !important;
  border-radius: 0 !important;
}

.dashboard-redesign .dnext-item {
  border-bottom: 1px solid var(--v4-hair) !important;
}

.dashboard-redesign .dnext-check {
  display: none !important;
}

.dashboard-redesign .dnext-title {
  font-family: var(--font-sans) !important;
  font-size: .85rem !important;
  color: var(--v4-forest) !important;
}

.dashboard-redesign .dash-card-foot a {
  border-top: 1px solid var(--v4-hair2) !important;
  color: var(--v4-gold) !important;
}

/* Scripture footer band → v4 verse band */

.dashboard-redesign .dash-scripture-footer {
  border-top: 1px solid var(--v4-forest) !important;
}

.dashboard-redesign .dscript-text {
  color: var(--v4-muted) !important;
  font-size: 1rem !important;
}

.dashboard-redesign .dscript-text cite {
  color: var(--v4-gold) !important;
}

/* Charts → flat */

.dashboard-redesign .chart-wrap {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 0 .25rem !important;
}

.dashboard-redesign .chart-title {
  font-family: var(--font-sans) !important;
  font-size: .72rem !important;
  letter-spacing: .2em !important;
  text-transform: uppercase !important;
  border-bottom: 1px solid var(--v4-forest) !important;
  padding-bottom: .5rem !important;
}

/* Hide leaf ornaments for the cleaner editorial look */

.dashboard-redesign .dash-orn {
  display: none !important;
}

/* ── Universal flatten: de-"card" every bespoke *-card / *-box container ──
The page redesigns share a suffix convention (venue-stat-card, budget-card,
payment-table-card, wday-side-card, prayer-card, etc.). One substring rule
removes the rounded-card shell everywhere → the v4 shapeless editorial look. */

body.editorial-v4 .panel [class*="-card"],
body.editorial-v4 .panel [class*="-box"] {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}

/* Inner table wrappers that scrolled inside a card — keep them clean */

body.editorial-v4 .panel [class*="-table-card"],
body.editorial-v4 .panel [class*="-table-wrap"] {
  padding-left: 0 !important;
  padding-right: 0 !important;
}

/* ── Re-assert the few tan callouts that should KEEP a soft fill (v4 uses tan
sparingly for emphasis: countdown, info strip, scripture/verse blocks). ── */

body.editorial-v4 .dashboard-redesign .countdown-card {
  background: var(--v4-soft) !important;
}

body.editorial-v4 .dashboard-redesign .dash-info-grid {
  background: var(--v4-soft) !important;
}

body.editorial-v4 .panel [class*="-verse-card"],
body.editorial-v4 .panel .prayer-prompt-card,
body.editorial-v4 .panel .page-prayer-prompt {
  background: var(--v4-soft) !important;
  border-left: 2px solid var(--v4-gold) !important;
}

/* ── Bespoke stat tiles → borderless serif-numeral strip (match v4 stats) ── */

body.editorial-v4 .panel [class*="-stat-card"] {
  padding: .1rem 1rem !important;
  border-right: 1px solid var(--v4-hair2) !important;
}

body.editorial-v4 .panel [class*="-stat-grid"] > [class*="-stat-card"]:last-child {
  border-right: none !important;
}

body.editorial-v4 .panel [class*="-stat-card"] [class*="-stat-val"],
body.editorial-v4 .panel [class*="-stat-card"] .stat-val {
  font-family: var(--v4-serif) !important;
  color: var(--v4-forest) !important;
}

/* ── Bespoke tables → hairline editorial (beat per-page !important header fills) ── */

body.editorial-v4 .panel table th,
body.editorial-v4 .panel [class*="-table"] th {
  background: transparent !important;
  color: var(--v4-forest) !important;
  border-bottom: 1px solid var(--v4-forest) !important;
  text-transform: uppercase !important;
  letter-spacing: .12em !important;
}

body.editorial-v4 .panel table td,
body.editorial-v4 .panel [class*="-table"] td {
  border-bottom: 1px solid var(--v4-hair) !important;
}

/* Reinforce against per-page `thead th` header fills (some use !important) */

body.editorial-v4 .panel thead,
body.editorial-v4 .panel table thead th,
body.editorial-v4 .panel [class*="-table"] thead th {
  background: transparent !important;
  color: var(--v4-forest) !important;
  border-bottom: 1px solid var(--v4-forest) !important;
}

/* Beat ID-anchored Excel-style headers (#panel-x .x-table thead tr:not(.bulk) th) */

#main .panel [class*="-table"] thead tr:not(.bulk-table-row) th,
#main .panel [class*="-table"] thead th,
#main .panel [class*="-table"] th {
  background: transparent !important;
  color: var(--v4-forest) !important;
  border-bottom: 1px solid var(--v4-forest) !important;
}

/* ── Bespoke section heads → underlined uppercase editorial heads ──
Covers the common heading classes used across the page redesigns. */

body.editorial-v4 .panel [class$="-card"] > h2:first-child,
body.editorial-v4 .panel [class$="-card"] > h3:first-child,
body.editorial-v4 .panel [class*="-section-head"],
body.editorial-v4 .panel .card-kicker {
  font-family: var(--font-sans) !important;
  font-size: .72rem !important;
  font-weight: 600 !important;
  letter-spacing: .2em !important;
  text-transform: uppercase !important;
  color: var(--v4-forest) !important;
  padding-bottom: .5rem !important;
  margin-bottom: 1rem !important;
  border-bottom: 1px solid var(--v4-forest) !important;
  display: flex !important;
  align-items: center;
  gap: 7px;
}

body.editorial-v4 .panel [class$="-card"] > h2:first-child svg,
body.editorial-v4 .panel [class$="-card"] > h3:first-child svg,
body.editorial-v4 .panel [class*="-section-head"] svg {
  width: 14px !important;
  height: 14px !important;
  color: var(--v4-gold) !important;
  stroke: var(--v4-gold) !important;
}

/* ── Chrome: verse banner, profile/backup bars, modals → v4 editorial ── */

/* Scripture verse ribbon: maroon → soft tan editorial verse band */

body.editorial-v4 #scripture-banner {
  background: var(--v4-soft) !important;
  color: var(--v4-forest) !important;
  font-family: var(--v4-serif) !important;
  font-style: italic !important;
  font-size: .98rem !important;
  border-bottom: 1px solid var(--v4-hair2) !important;
}

body.editorial-v4 #scripture-banner .ref {
  color: var(--v4-gold) !important;
}

/* Slim profile + backup bars — keep light & subtle */

body.editorial-v4 #profile-bar {
  background: var(--v4-soft) !important;
  border-bottom: 1px solid var(--v4-hair2) !important;
}

body.editorial-v4 #backup-banner {
  background: var(--v4-soft) !important;
  backdrop-filter: none !important;
}

/* Modals → flat editorial */

.modal {
  border-radius: 0 !important;
  box-shadow: 0 18px 50px rgba(45,40,30,.22) !important;
}

.modal h3 {
  font-family: var(--v4-serif) !important;
  color: var(--v4-forest) !important;
}

.modal-overlay .modal .btn {
  border-radius: 0 !important;
}

/* Global search dropdown → square editorial */

.gs-results {
  border-radius: 0 !important;
}

#gs-input {
  border-radius: 0 !important;
}

/* ════════════════════════════════════════════════
V4 EDITORIAL — buttons (NO pills) + typography lock
════════════════════════════════════════════════ */

/* Every button → square, flat, editorial. Kills all pill/gradient styling. */

body.editorial-v4 .btn,
body.editorial-v4 button.btn,
body.editorial-v4 .btn-sm,
body.editorial-v4 .tes-btn,
body.editorial-v4 .tes-btn-alt,
body.editorial-v4 .add-row-btn,
body.editorial-v4 #topbar .actions .btn,
body.editorial-v4 .modal .btn {
  border-radius: 0 !important;
  background-image: none !important;
  box-shadow: none !important;
  font-weight: 600 !important;
  letter-spacing: .04em !important;
  text-transform: none !important;
}

/* Primary (gold) → solid flat gold */

body.editorial-v4 .btn-gold {
  background: var(--v4-gold) !important;
  color: #fff !important;
  border: 1px solid var(--v4-gold) !important;
}

body.editorial-v4 .btn-gold:hover {
  background: #a98a52 !important;
  border-color: #a98a52 !important;
}

/* Forest → solid flat forest */

body.editorial-v4 .btn-forest {
  background: var(--v4-forest) !important;
  color: #fff !important;
  border: 1px solid var(--v4-forest) !important;
}

/* Outline / secondary → transparent w/ gold border (v4 backup-btn style) */

body.editorial-v4 .btn-outline {
  background: transparent !important;
  color: #946f33 !important;
  border: 1px solid var(--v4-gold) !important;
}

body.editorial-v4 .btn-outline:hover {
  background: var(--v4-soft) !important;
}

/* Topbar action pill bar → flat strip of square buttons */

body.editorial-v4 #topbar .actions {
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  gap: .4rem !important;
}

body.editorial-v4 #topbar .actions .btn {
  border: none !important;
  border-right: none !important;
  color: #F4EFE6 !important;
  background: transparent !important;
}

body.editorial-v4 #topbar .actions .btn:hover {
  background: rgba(255,255,255,.12) !important;
}

/* Add-row dashed buttons → square */

body.editorial-v4 .add-row-btn {
  border-style: dashed !important;
}

/* Badges keep small radius is fine, but square pills look more editorial */

body.editorial-v4 .badge {
  border-radius: 0 !important;
}

/* Filter chips / tabs that used pills → square */

body.editorial-v4 [class*="filter"] button,
body.editorial-v4 [class*="-tab"],
body.editorial-v4 [class*="-chip"] {
  border-radius: 0 !important;
}

/* ════════════════════════════════════════════════
V4 EDITORIAL — POP-OUT / HIDE SIDEBAR DRAWER + FULL-WIDTH STAGE
Sidebar becomes an overlay drawer; #main is always full width.
════════════════════════════════════════════════ */

/* Menu toggle button in the appbar */

body.editorial-v4 #nav-toggle {
  flex: 0 0 auto;
  min-width: 62px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .35rem;
  background: color-mix(in srgb, var(--gold) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--gold) 35%, transparent);
  border-radius: 0;
  color: var(--gold-lt);
  cursor: pointer;
  margin-right: .2rem;
  padding: 0 .7rem;
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
}

body.editorial-v4 #nav-toggle:hover {
  background: color-mix(in srgb, var(--gold) 22%, transparent);
  color: #fff;
}

body.editorial-v4 #nav-toggle svg {
  width: 20px;
  height: 20px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
}

/* Layout → block; main → full width */

body.editorial-v4 #layout {
  display: block !important;
}

body.editorial-v4 #main {
  width: 100% !important;
  max-width: none !important;
  margin: 0 !important;
  flex: none !important;
}

/* Scrim */

#nav-scrim {
  position: fixed;
  inset: 0;
  background: rgba(34,40,32,.45);
  z-index: 1190;
  opacity: 0;
  visibility: hidden;
  transition: opacity .2s;
}

body.editorial-v4:not(.nav-hidden) #nav-scrim {
  opacity: 1;
  visibility: visible;
}

/* Drawer */

body.editorial-v4 #sidebar {
  position: fixed !important;
  top: 0;
  left: 0;
  width: 274px !important;
  height: 100vh !important;
  z-index: 1200;
  /* Sidebar surface = the selected theme's MAIN color (with a subtle darker foot for depth). */
  background: linear-gradient(180deg, var(--forest), color-mix(in srgb, var(--forest) 82%, #000)) !important;
  color: var(--gold-pale) !important;
  border-right: none !important;
  overflow-y: auto !important;
  padding: 0 0 2rem !important;
  display: flex !important;
  flex-direction: column !important;
  transform: translateX(-100%);
  transition: transform .24s ease;
  box-shadow: 6px 0 30px rgba(20,40,30,.32);
}

body.editorial-v4:not(.nav-hidden) #sidebar {
  transform: translateX(0);
}

/* Drawer close button */

body.editorial-v4 #nav-close {
  position: absolute;
  top: .7rem;
  right: .7rem;
  z-index: 2;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  background: transparent;
  border: 1px solid rgba(212,184,150,.35);
  color: #cfc7b8;
  cursor: pointer;
  border-radius: 0;
}

body.editorial-v4 #nav-close:hover {
  background: rgba(255,255,255,.08);
  color: #fff;
}

body.editorial-v4 #nav-close svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
}

/* Dark drawer internals */

body.editorial-v4 #sidebar .side-brand {
  padding-top: .4rem;
}

body.editorial-v4 #sidebar .side-photo-help {
  color: rgba(237,230,216,.6) !important;
}

body.editorial-v4 #sidebar .nav-label {
  color: var(--gold-lt) !important;
  opacity: .72;
  letter-spacing: .18em !important;
  padding: 1rem 1.3rem .35rem !important;
  font-size: .6rem !important;
}

body.editorial-v4 #sidebar .nav-item {
  /* Nav text = a lighter supporting color from the selected theme. */
  color: var(--gold-pale) !important;
  border-left: 2px solid transparent !important;
  padding: .46rem 1.3rem !important;
  font-size: .82rem !important;
}
/* Category name + subtitle in the nav drawer — readable & adaptive to the
   selected theme's main colour (light text on dark themes, dark on light). */
body.editorial-v4 #sidebar .nav-drawer-cat-label,
body.editorial-v4 #sidebar .nav-cat-page-label {
  color: var(--theme-on-primary, #f5efe4) !important;
}
body.editorial-v4 #sidebar .nav-drawer-cat-sub,
body.editorial-v4 #sidebar .nav-drawer-cat-chevron,
body.editorial-v4 #sidebar .nav-cat-page-sub {
  color: var(--theme-on-primary-dim, #d4b896) !important;
}

body.editorial-v4 #sidebar .nav-item:hover {
  background: rgba(255,255,255,.05) !important;
}

body.editorial-v4 #sidebar .nav-item.active {
  background: rgba(255,255,255,.08) !important;
  color: #fff !important;
  border-left-color: var(--gold) !important;
  font-weight: 500 !important;
}

body.editorial-v4 #sidebar .nav-item .nav-icon svg,
body.editorial-v4 #sidebar .nav-item .line-icon {
  color: var(--gold-lt) !important;
  stroke: var(--gold-lt) !important;
}

body.editorial-v4 #sidebar .nav-prog {
  color: rgba(217,209,194,.7) !important;
}

body.editorial-v4 #sidebar .nav-item.active .nav-prog {
  color: #fff !important;
}

/* ════════════════════════════════════════════════
V4 EDITORIAL MASTHEAD (injected per page) + hidden native hero
════════════════════════════════════════════════ */

body.editorial-v4 .v4-hero-hidden {
  display: none !important;
}

/* text-only fallback: keep hero (for its controls) but drop duplicate title/subtitle */

body.editorial-v4 .v4-hero-textonly > h1,
body.editorial-v4 .v4-hero-textonly > h2,
body.editorial-v4 .v4-hero-textonly > p,
body.editorial-v4 .v4-hero-textonly > div > h1,
body.editorial-v4 .v4-hero-textonly > div > h2,
body.editorial-v4 .v4-hero-textonly > div > p {
  display: none !important;
}

/* action group lifted into the masthead */

body.editorial-v4 .m-mast .m-mast-actions {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
  align-items: flex-end;
  align-self: flex-end;
  margin-left: auto;
}

body.editorial-v4 .m-mast-wrap {
  margin-bottom: 1.7rem;
}

body.editorial-v4 .m-mast {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--v4-forest);
