  margin-top: 1.1rem;
}

@media(max-width:680px) {
  body.editorial-v4 .m-title {
    font-size: 23px;
  }

  body.editorial-v4 .m-mast-num {
    font-size: 32px;
  }

  body.editorial-v4 .m-meta {
    gap: 12px;
  }

}

