/* ── Nav hint tooltip ── */

.nav-hint-tooltip {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  background: var(--v4-forest,#2D4A3E);
  color: #fff;
  font-size: .75rem;
  padding: .35rem .7rem;
  border-radius: 4px;
  margin-top: 4px;
  pointer-events: none;
  animation: navHintPulse 1.5s ease-in-out infinite;
  z-index: 10000;
}

.nav-hint-tooltip::before {
  content: '';
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 5px solid transparent;
  border-bottom-color: var(--v4-forest,#2D4A3E);
}

@keyframes navHintPulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: .6;
  }

}

/* ── Skip link ── */

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  z-index: 100001;
  background: var(--forest,#2D4A3E);
  color: #fff;
  padding: .5rem 1rem;
  font-size: .875rem;
  text-decoration: none;
  border-radius: 0 0 4px 0;
  transition: top .2s;
}

.skip-link:focus {
  top: 0;
}

/* ── Toast notifications ── */

.planner-toast {
  position: fixed;
  top: 1rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100000;
  max-width: 480px;
  width: 90%;
  padding: .75rem 1.25rem;
  border-radius: 6px;
  font-size: .875rem;
  line-height: 1.4;
  color: #fff;
  background: var(--forest,#2D4A3E);
  box-shadow: 0 4px 16px rgba(0,0,0,.2);
  opacity: 0;
  transition: opacity .3s,transform .3s;
  pointer-events: none;
}

.planner-toast.visible {
  opacity: 1;
  pointer-events: auto;
}

.planner-toast.warn {
  background: #b08600;
  color: #fff;
}

.planner-toast.error {
  background: #a03030;
  color: #fff;
}

/* ── Over-budget indicator ── */

.budget-over-badge {
  display: inline-block;
  background: #c0392b;
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 3px;
  margin-left: .5rem;
  vertical-align: middle;
}

