  --ued-paper: #fff;
  --ued-panel: #fff;
  --ued-ink: #23211c;
  --ued-forest: var(--chart-1, var(--theme-primary,var(--v4-forest,#2c4a3e)));
  --ued-forest-deep: #1d342b;
  --ued-gold: var(--chart-2, var(--theme-accent,var(--v4-gold,#9c7c4a)));
  --ued-soft-gold: #b89968;
  --ued-muted: #8c8475;
  --ued-muted2: #aaa08d;
  --ued-line: rgba(35,33,28,.13);
  --ued-line2: rgba(35,33,28,.22);
  --ued-sage: #eef0ea;
  --ued-danger: #9c4a4a;
  --ued-ok: #4c7a4c;
  width: 100%;
  max-width: none;
  padding: var(--planner-panel-padding, 1.5rem);
