@media(max-width:1200px) {
  .ued-filter-grid {
    grid-template-columns: repeat(4,minmax(120px,1fr))
  }

  .ued-form-grid {
    grid-template-columns: repeat(3,minmax(120px,1fr))
  }

  .ued-category-strip {
    grid-template-columns: repeat(4,minmax(150px,1fr))
  }

