  #panel-guests.ued-scope,
  #panel-budget.ued-scope,
  #panel-payments.ued-scope {
    padding: .8rem
  }

  .ued-title {
    font-size: 2.15rem
  }

  .ued-band,
  .ued-info,
  .ued-filter-grid,
  .ued-form-grid,
  .ued-progress-card,
  .ued-section-progress-list {
    grid-template-columns: 1fr
  }

  .ued-stat,
  .ued-info-cell,
  .ued-mini {
    border-right: 0!important
  }

  .ued-filter.search {
    grid-column: span 1
  }

  .ued-bar {
    grid-template-columns: 1fr
  }

  .ued-bar-val {
    text-align: left
  }

  .ued-mast {
    gap: .7rem
  }

  .ued-meta span {
    border-right: 0;
    padding: .12rem .7rem .12rem 0
  }

  .ued-table-head,

  .ued-actions {
    width: 100%;
    justify-content: flex-start
  }

  .ued-category-strip {
    grid-template-columns: 1fr 1fr
  }

  .ued-progress-row {
    grid-template-columns: 1fr
  }

  .ued-progress-row em {
    text-align: left
  }

}

