/* =========================================================
EDITORIAL ROLLOUT - ALL REMAINING PAGES
This layer brings every existing page into the same premium
editorial visual system without removing legacy content or
breaking existing render/data functions.
========================================================= */

:root {
  --er-paper: #fff;
  --er-ink: #25221c;
  --er-muted: #81786a;
  --er-line: rgba(37,34,28,.14);
  --er-line-strong: rgba(37,34,28,.28);
  --er-soft: #f8f5ee;
  --er-forest: var(--theme-primary,var(--forest,#2c4a3e));
  --er-gold: var(--theme-accent,var(--gold,#b89968));
  --er-danger: #9c4a4a;
}

body,
#app,
#main,
.main,
.content,
.workspace {
  background: #fff!important;
  background-image: none!important;
}

#main .panel {
  width: 100%!important;
  max-width: none!important;
  margin: 0!important;
  padding: clamp(1rem,2vw,1.65rem)!important;
  background: #fff!important;
  background-image: none!important;
  color: var(--er-ink)!important;
  font-family: var(--font-sans,Inter,system-ui,sans-serif)!important;
}

#main .panel.active {
  display: block!important;
}

#main .panel:not(.active) {
  display: none!important;
}

#main .panel *,
#main .panel *::before,
#main .panel *::after {
  box-sizing: border-box;
}

#main .panel h1,
#main .panel .page-title,
#main .panel .section-title,
#main .panel .m-title,
#main .panel .hero-title {
  font-family: var(--font-serif,Georgia,serif)!important;
  color: var(--er-forest)!important;
  letter-spacing: 0!important;
}

#main .panel h2,
#main .panel h3,
#main .panel .card-title,
#main .panel .m-card-title,
#main .panel .ued-table-title {
  font-family: var(--font-serif,Georgia,serif)!important;
  color: var(--er-forest)!important;
  letter-spacing: .02em!important;
}

#main .panel p,
#main .panel .page-subtitle,
#main .panel .subtitle,
#main .panel .help-text,
#main .panel .muted,
#main .panel small {
  color: var(--er-muted)!important;
}

/* Editorial page headers */

#main .panel > .page-header,
#main .panel > .hero,
