/* =========================================================
LIVE DASHBOARD MOTION
Adds the interactive feel from the editorial mockups:
count-up stats, drawing bars, and drawing donut charts.
========================================================= */

#panel-dashboard.ued-scope .ued-count-grid {
  grid-template-columns: repeat(5,minmax(0,1fr))!important;
}

#panel-dashboard.ued-scope .ued-count-unit {
  min-width: 0!important;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-stat,
#panel-dashboard.ued-scope .ued-motion-ready .ued-panel,
#panel-dashboard.ued-scope .ued-motion-ready .ued-info-cell {
  animation: ued-panel-rise .52s cubic-bezier(.2,.7,.2,1) both;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-panel:nth-child(2) {
  animation-delay: .04s;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-panel:nth-child(3) {
  animation-delay: .08s;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-panel:nth-child(4) {
  animation-delay: .12s;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-fill,
#panel-dashboard.ued-scope .ued-motion-ready .ued-bar-fill {
  transform-origin: left center;
  animation: ued-bar-draw .9s cubic-bezier(.2,.7,.2,1) both;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-donut circle:nth-of-type(2) {
  stroke-dashoffset: 0;
  animation: ued-donut-draw 1s cubic-bezier(.2,.7,.2,1) both;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-count-unit b {
  animation: ued-count-tick .42s ease both;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-count-unit:nth-child(2) b {
  animation-delay: .04s;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-count-unit:nth-child(3) b {
  animation-delay: .08s;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-count-unit:nth-child(4) b {
  animation-delay: .12s;
}

#panel-dashboard.ued-scope .ued-motion-ready .ued-count-unit:nth-child(5) b {
  animation-delay: .16s;
}

@keyframes ued-panel-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }

}

@keyframes ued-bar-draw {
  from {
    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }

}

@keyframes ued-donut-draw {
  from {
    stroke-dashoffset: 251.2;
  }

  to {
    stroke-dashoffset: 0;
  }

}

@keyframes ued-count-tick {
  from {
    opacity: .35;
    transform: translateY(5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }

}

@media(max-width:900px) {
  #panel-dashboard.ued-scope .ued-count-grid {
    grid-template-columns: repeat(2,minmax(0,1fr))!important;
  }

  #panel-dashboard.ued-scope .ued-count-unit {
    border-bottom: 1px solid var(--countdown-line,rgba(255,255,255,.3))!important;
  }

