    color-mix(in srgb, var(--forest,#2D4A3E) 78%, #000) 0,
    color-mix(in srgb, var(--forest,#2D4A3E) 78%, #000) 56px,
    var(--forest,#2D4A3E) 56px, var(--forest,#2D4A3E) 100%) !important;
}
body.editorial-v4.nav-sidebar.nav-pinned #main{ margin-left:56px !important; width:calc(100% - 56px) !important; }

/* themed scrollbar */
body.editorial-v4.nav-sidebar #sidebar::-webkit-scrollbar{ width:8px !important; }
body.editorial-v4.nav-sidebar #sidebar::-webkit-scrollbar-track{ background:color-mix(in srgb, var(--forest,#2D4A3E) 62%, #000) !important; }
body.editorial-v4.nav-sidebar #sidebar::-webkit-scrollbar-thumb{ background:var(--gold,#B89968) !important; border-radius:4px !important; }

/* expand toggle centered in the icon column */
