/* items: icon column + name; theme colors */
body.editorial-v4.nav-sidebar #sidebar .nav-item{
  gap:12px !important; padding:0 14px 0 0 !important;
  color:color-mix(in srgb, var(--gold-pale,#F5EFE4) 60%, transparent) !important;
}
body.editorial-v4.nav-sidebar #sidebar .nav-item .nav-icon{ width:56px !important; }
body.editorial-v4.nav-sidebar #sidebar .nav-item:hover{ background:color-mix(in srgb, var(--forest,#2D4A3E) 82%, #fff) !important; color:var(--gold-pale,#F5EFE4) !important; }
body.editorial-v4.nav-sidebar #sidebar .nav-item:hover .material-symbols-sharp{ color:var(--gold-lt,#D4B896) !important; }
body.editorial-v4.nav-sidebar #sidebar .nav-item.active,
body.editorial-v4.nav-sidebar #sidebar .nav-item[aria-current="page"]{ background:color-mix(in srgb, var(--forest,#2D4A3E) 78%, #fff) !important; color:var(--gold-pale,#F5EFE4) !important; box-shadow:inset 3px 0 0 var(--gold-lt,#D4B896) !important; }
body.editorial-v4.nav-sidebar #sidebar .nav-item.active .material-symbols-sharp,
body.editorial-v4.nav-sidebar #sidebar .nav-item[aria-current="page"] .material-symbols-sharp{ color:var(--gold-lt,#D4B896) !important; }

/* category labels + page names both start in the second (expandable) panel */
body.editorial-v4.nav-sidebar.nav-rail-expanded #sidebar .nav-label{
  display:block !important; padding:14px 16px 4px 68px !important;
  color:color-mix(in srgb, var(--gold-pale,#F5EFE4) 45%, transparent) !important;
}
body.editorial-v4.nav-sidebar.nav-rail-expanded #sidebar #nav-layout-toggle{
  color:color-mix(in srgb, var(--gold-pale,#F5EFE4) 70%, transparent) !important;
  border-color:color-mix(in srgb, var(--gold,#B89968) 34%, transparent) !important;
  background:transparent !important;
}

/* ===== LEFT SIDEBAR — SAME HEIGHT THIN + EXPANDED, LEFT SCROLLBAR ===== */

/* Thin collapsed sidebar */
body.editorial-v4.nav-sidebar #sidebar {
  position: fixed !important;
  left: 0 !important;
  top: 50% !important;
  transform: translateY(-50%) !important;

  width: 56px !important;
  min-width: 56px !important;
  max-width: 56px !important;

  height: 76vh !important;
  max-height: 720px !important;
  min-height: 480px !important;

  border-radius: 0 9px 9px 0 !important;
  border-right: 1px solid color-mix(in srgb, var(--gold,#B89968) 28%, transparent) !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  direction: rtl !important; /* moves scrollbar to LEFT */

  background: var(--forest,#2D4A3E) !important;
  box-shadow: 8px 0 22px rgba(28, 39, 32, .18) !important;
  z-index: 999 !important;

  padding: 12px 0 !important;
}

/* Expanded sidebar — same height as thin sidebar */
body.editorial-v4.nav-sidebar.nav-rail-expanded #sidebar {
  width: 250px !important;
  min-width: 250px !important;
  max-width: 250px !important;

  height: 76vh !important;
  max-height: 720px !important;
  min-height: 480px !important;

  top: 50% !important;
  transform: translateY(-50%) !important;

  border-radius: 0 9px 9px 0 !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  direction: rtl !important; /* keeps scrollbar on LEFT when expanded */
}

/* Put icons/text back to normal direction */
body.editorial-v4.nav-sidebar #sidebar > *,
body.editorial-v4.nav-sidebar #sidebar .nav-section,
body.editorial-v4.nav-sidebar #sidebar .nav-item,
body.editorial-v4.nav-sidebar #sidebar .nav-icon,
body.editorial-v4.nav-sidebar #sidebar .nav-label {
  direction: ltr !important;
}

/* Main content spacing for thin sidebar */
body.editorial-v4.nav-sidebar.nav-pinned #main {
  margin-left: 56px !important;
  width: calc(100% - 56px) !important;
}

/* Main content spacing for expanded sidebar */
body.editorial-v4.nav-sidebar.nav-rail-expanded.nav-pinned #main {
  margin-left: 250px !important;
  width: calc(100% - 250px) !important;
}

/* Keep icons centered in the thin bar */
body.editorial-v4.nav-sidebar #sidebar .nav-item .nav-icon {
  width: 56px !important;
  justify-content: center !important;
}

/* Thin scrollbar */
body.editorial-v4.nav-sidebar #sidebar::-webkit-scrollbar {
  width: 6px !important;
}

/* ---- TOP MENU (icons only, same dark theme bar) ---- */
body.editorial-v4:not(.nav-sidebar) #sidebar{
  background:var(--forest,#2D4A3E) !important;
  display:flex !important; flex-direction:row !important; flex-wrap:nowrap !important;
  align-items:center !important; gap:0 !important; padding:0 8px !important;
  overflow-x:auto !important; overflow-y:hidden !important; border:0 !important;
  scrollbar-width:thin; scrollbar-color: var(--gold,#B89968) color-mix(in srgb, var(--forest,#2D4A3E) 62%, #000);
}
body.editorial-v4:not(.nav-sidebar) #sidebar::-webkit-scrollbar{ height:6px !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar::-webkit-scrollbar-thumb{ background:var(--gold,#B89968) !important; border-radius:3px !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar::-webkit-scrollbar-track{ background:color-mix(in srgb, var(--forest,#2D4A3E) 62%, #000) !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-section{ display:flex !important; flex-direction:row !important; padding:0 !important; margin:0 !important; border:0 !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-label{ display:none !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar #nav-close,
body.editorial-v4:not(.nav-sidebar) #sidebar #nav-expand,
body.editorial-v4:not(.nav-sidebar) #sidebar #nav-layout-toggle{ display:none !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item{
  flex:none !important; width:48px !important; height:48px !important; min-height:48px !important; padding:0 !important; margin:0 !important;
  border-radius:0 !important; overflow:hidden !important;
  color:color-mix(in srgb, var(--gold-pale,#F5EFE4) 60%, transparent) !important;
}
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item .nav-icon{ width:48px !important; height:48px !important; margin:0 !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item:hover{ background:color-mix(in srgb, var(--forest,#2D4A3E) 82%, #fff) !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item:hover .material-symbols-sharp,
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item.active .material-symbols-sharp,
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item[aria-current="page"] .material-symbols-sharp{ color:var(--gold-lt,#D4B896) !important; }
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item.active,
body.editorial-v4:not(.nav-sidebar) #sidebar .nav-item[aria-current="page"]{ background:color-mix(in srgb, var(--forest,#2D4A3E) 78%, #fff) !important; box-shadow:inset 0 -3px 0 var(--gold-lt,#D4B896) !important; }

/* Top-menu layout removed — hide layout switchers */
#menu-layout-pref-btn, #nav-layout-toggle{ display:none !important; }

/* ============================================================
   Fixed left rail + no page-level horizontal scroll.
   Wide tables scroll inside their own wrapper instead of
   stretching the whole page behind the menu bar.
   ============================================================ */
html, body{ overflow-x:hidden !important; max-width:100% !important; }
body.editorial-v4.nav-sidebar #main{ box-sizing:border-box !important; overflow-x:hidden !important; max-width:calc(100vw - 56px) !important; }
body.editorial-v4.nav-sidebar #main .panel{ max-width:100% !important; box-sizing:border-box !important; }
#main [class*="table-wrap"], #main .ued-table-wrap, #main .cwp-table-wrap{ max-width:100% !important; overflow-x:auto !important; }

/* ============================================================
   PT reusable table UI — generic toolbar, buttons, search,
   and header filter button (works on any converted table).
   ============================================================ */
.pt-toolbar{ display:flex; align-items:center; justify-content:flex-start; flex-wrap:wrap; gap:.5rem; margin:0 0 .8rem; }
.pt-tbtn{ border:1px solid rgba(196,165,118,.45); background:#fff; color:var(--forest,#2f5136); border-radius:8px; padding:.5rem .9rem; font:inherit; font-size:.8rem; font-weight:600; cursor:pointer; line-height:1; white-space:nowrap; }
.pt-tbtn:hover:not(:disabled){ background:#faf6ec; }
.pt-tbtn:disabled{ opacity:.4; cursor:not-allowed; }
.pt-tbtn-danger{ color:#b54b3f; border-color:rgba(181,75,63,.35); }
.pt-tbtn-danger:hover:not(:disabled){ background:#fbe9e3; }
.pt-search{ display:flex; align-items:center; gap:.45rem; border:1px solid rgba(196,165,118,.45); border-radius:8px; padding:.45rem .7rem; width:210px; background:#fff; }
.pt-search svg{ width:14px; height:14px; stroke:var(--muted,#9a9184); fill:none; stroke-width:1.8; flex:none; }
.pt-search input{ border:0 !important; background:transparent !important; outline:none; font:inherit; font-size:.8rem; color:var(--forest,#2f5136); width:100%; box-shadow:none !important; padding:0 !important; }
/* generic header filter button (unscoped so any table gets it) */
.th-flx{ display:inline-flex; align-items:center; justify-content:space-between; gap:.3rem; width:100%; }
th .col-filter{ border:0; background:transparent; cursor:pointer; color:#a79c88; font-size:.7rem; line-height:1; padding:0 .15rem; flex:none; }
th .col-filter:hover{ color:var(--gold,#b28a4c); }
th .col-filter.active{ color:var(--gold,#b28a4c); font-weight:700; }

/* ============================================================
   Menu button show/hide the rail + smaller labels + centered
   profile photo above the labels (expanded only).
   ============================================================ */
/* smooth slide */
body.editorial-v4.nav-sidebar #sidebar{ transition:width .25s cubic-bezier(.4,0,.2,1), transform .25s cubic-bezier(.4,0,.2,1) !important; }
/* hidden state (Menu button toggles) */
body.editorial-v4.nav-sidebar.nav-hidden #sidebar{ transform:translateX(-100%) !important; }
body.editorial-v4.nav-sidebar.nav-hidden.nav-pinned #main{ margin-left:0 !important; width:100% !important; max-width:100vw !important; }

/* smaller page-label font so names fit in the expanded panel */
body.editorial-v4.nav-sidebar #sidebar .nav-item{ font-size:12px !important; }

/* profile photo — centered, above the labels, expanded only */
body.editorial-v4.nav-sidebar:not(.nav-rail-expanded) #sidebar .side-brand{ display:none !important; }
body.editorial-v4.nav-sidebar.nav-rail-expanded #sidebar .side-brand{ display:block !important; padding:.8rem .6rem .5rem !important; text-align:center !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-wrap{ display:flex !important; justify-content:center !important; align-items:center !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-cutout{ margin:0 auto !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-help{ display:none !important; }

/* Nav labels: a bit smaller + bold so names fit */
