/* Profile photo — centered, no underline */
body.editorial-v4.nav-sidebar #sidebar .side-brand{ border:0 !important; border-bottom:0 !important; margin-bottom:0 !important; padding:.85rem 0 .4rem !important; text-align:center !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-wrap{ display:flex !important; justify-content:center !important; align-items:center !important; margin:0 !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-cutout{ margin:0 auto !important; }

/* Nav icons + page labels use the theme's soft card-fill color */
body.editorial-v4.nav-sidebar #sidebar .nav-item,
body.editorial-v4.nav-sidebar #sidebar .nav-item:hover,
body.editorial-v4.nav-sidebar #sidebar .nav-item.active,
body.editorial-v4.nav-sidebar #sidebar .nav-item[aria-current="page"]{ color:var(--v4-soft,#F4EEE3) !important; }
