body.editorial-v4.nav-sidebar #sidebar .nav-item:hover .material-symbols-sharp,
body.editorial-v4.nav-sidebar #sidebar .nav-item.active .material-symbols-sharp,
body.editorial-v4.nav-sidebar #sidebar .nav-item[aria-current="page"] .material-symbols-sharp{ color:var(--v4-soft,#F4EEE3) !important; }

/* Profile photo aligned to where the page-label text starts (68px) */
body.editorial-v4.nav-sidebar #sidebar .side-brand{ text-align:left !important; padding:.85rem 12px .5rem 68px !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-wrap{ justify-content:flex-start !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-cutout{ margin:0 !important; }

/* Remove the + edit badge, align photo to label start (68px), unbold labels */
body.editorial-v4.nav-sidebar #sidebar .side-photo-edit{ display:none !important; }
body.editorial-v4.nav-sidebar #sidebar .side-brand{ padding:.85rem 12px .5rem 0 !important; text-align:left !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-wrap{ justify-content:flex-start !important; margin:0 !important; padding:0 !important; }
body.editorial-v4.nav-sidebar #sidebar .side-photo-cutout{ margin:0 0 0 68px !important; }
body.editorial-v4.nav-sidebar #sidebar .nav-item{ font-weight:400 !important; }

/* Wedding Countdown as a full-width centered band across the top */
#panel-dashboard .ued-countdown-wide{ text-align:left; }
#panel-dashboard .ued-countdown-wide .ued-caption{ justify-content:flex-start; }
#panel-dashboard .ued-countdown-wide .ued-count-grid{ display:flex !important; flex-wrap:wrap; justify-content:flex-start; align-items:flex-end; gap:clamp(1.4rem,6vw,5rem) !important; grid-template-columns:none !important; }
#panel-dashboard .ued-countdown-wide .ued-count-sub,
#panel-dashboard .ued-countdown-wide .ued-count-date,
#panel-dashboard .ued-countdown-wide .ued-count-tz{ text-align:left; }

/* ============================================================
   Wedding Countdown — Option C (hairline tiles, editorial)
   Compact, centered; theme-driven colors.
   ============================================================ */
#panel-dashboard .ued-countdown-c{
  background:transparent !important; border:0 !important; box-shadow:none !important;
  text-align:center; padding:.5rem 0 1.25rem !important; margin-bottom:1.5rem !important;
}
#panel-dashboard .cdc-head{ margin:0 0 1.1rem; }
#panel-dashboard .cdc-eyebrow{ font-size:10.5px; letter-spacing:.22em; text-transform:uppercase; color:var(--gold,#b28a4c) !important; font-weight:600; margin:0; }
#panel-dashboard .cdc-title{ font-family:var(--font-serif,Georgia,serif); font-size:1.5rem; color:var(--forest,#2f5136) !important; margin:.25rem 0 0; font-weight:500; }
