#panel-dashboard .cdc-tile b{ display:block; font-family:var(--font-serif,Georgia,serif); font-weight:500; font-size:clamp(28px,4vw,38px); line-height:1; color:var(--forest,#2f5136) !important; font-variant-numeric:tabular-nums; }
