#panel-dashboard .cdc-tz{ font-size:10.5px; color:var(--muted,#8a857c) !important; margin-top:.2rem; }

/* ============================================================
   Split countdown hero — left numerals, right couple/date block.
   Left-aligned to match the page; balanced by the date counterweight.
   ============================================================ */
#panel-dashboard .dash-hero{
  display:flex; align-items:stretch; gap:1.9rem;
  background:transparent !important; border:0 !important; box-shadow:none !important; border-radius:0 !important;
  padding:.4rem 0 1.2rem !important; margin-bottom:.3rem;
}
