#panel-dashboard .dash-hero-scripture{
  text-align:center; font-family:var(--font-serif,Georgia,serif); font-style:italic; font-size:12px;
  color:var(--muted,#8a857c); border-top:0.5px solid #e6ddc9; margin:.2rem 0 1.1rem; padding-top:.9rem;
}
