#panel-dashboard .dash-hero-couple{ font-family:var(--font-serif,Georgia,serif); font-size:1.6rem; color:var(--forest,#2f5136); margin:.2rem 0 .55rem; line-height:1.12; }
#panel-dashboard .dash-hero-date{ font-size:13px; color:#5f5a52; font-family:var(--font-sans,Inter,system-ui,sans-serif); }
