  box-shadow:inset 0 0 0 1px #333 !important;
}
/* Dashboard bar graphs — uniform, thicker, rounded */
#panel-dashboard .ued-track,
#panel-dashboard .ued-bar-track{ height:9px !important; border-radius:999px !important; overflow:hidden !important; }
#panel-dashboard .ued-fill{ display:block !important; height:100% !important; border-radius:999px !important; }
#panel-dashboard .ued-bar-fill{ border-radius:999px !important; }

/* Dashboard bar graphs — square (no rounding) */
#panel-dashboard .ued-track,
#panel-dashboard .ued-bar-track,
#panel-dashboard .ued-fill,
#panel-dashboard .ued-bar-fill{ border-radius:0 !important; }

/* Smart Alerts — left-align the alert text (leave the Open box) */
#panel-dashboard .guide-alert{ text-align:left !important; align-items:center !important; }
#panel-dashboard .guide-alert > span{ text-align:left !important; }
#panel-dashboard .guide-alert-title,
#panel-dashboard .guide-alert-note{ display:block !important; text-align:left !important; }

/* Budget Snapshot — vertical bar chart, wrapped category names */
#panel-dashboard .ued-vbars{ display:flex; align-items:flex-end; gap:.7rem; overflow-x:auto; padding:.6rem .2rem .2rem; }
#panel-dashboard .ued-vbar{ flex:1 1 0; min-width:60px; display:flex; flex-direction:column; align-items:center; gap:6px; }
#panel-dashboard .ued-vbar-val{ font-size:.72rem; color:var(--ued-muted,#8a857c); font-variant-numeric:tabular-nums; white-space:nowrap; }
#panel-dashboard .ued-vbar-track{ width:100%; max-width:46px; height:170px; background:var(--ued-line,#e7e1d4); position:relative; }
#panel-dashboard .ued-vbar-fill{ position:absolute; left:0; right:0; bottom:0; background:var(--ued-forest,var(--forest,#2f5136)); }
#panel-dashboard .ued-vbar-name{ font-size:.68rem; color:var(--ued-ink,#2c2a26); text-align:center; line-height:1.2; overflow-wrap:anywhere; word-break:break-word; }

/* Budget Snapshot vertical bars — interactive */
#panel-dashboard .ued-vbar{ background:transparent; border:0; padding:4px 2px; font:inherit; cursor:pointer; border-radius:4px; transition:background .12s; }
#panel-dashboard .ued-vbar:hover{ background:color-mix(in srgb, var(--gold,#b28a4c) 12%, transparent); }
#panel-dashboard .ued-vbar:hover .ued-vbar-fill{ background:var(--gold,#b28a4c); }
#panel-dashboard .ued-vbar:hover .ued-vbar-name{ color:var(--forest,#2f5136); font-weight:600; }
#panel-dashboard .ued-vbar:hover .ued-vbar-val{ color:var(--forest,#2f5136); }
#panel-dashboard .ued-vbar:focus-visible{ outline:2px solid var(--gold,#b28a4c); outline-offset:1px; }
#panel-dashboard .ued-vbar.over .ued-vbar-fill{ background:#b54b3f; }
#panel-dashboard .ued-vbar.over .ued-vbar-val{ color:#b54b3f; }

/* ═══════════════════════════════════════════════════════════════════════
   DARK MODE  (toggled by body.dark-mode via toggleDarkMode())
   An OS-style dark appearance. Surfaces go dark, text goes light. Brand
   fills (forest headers/chips, gold accents) are preserved because they
   already read well as filled blocks on a dark page; only text-role colors
   are lifted for contrast. Scoped tightly to body.editorial-v4.dark-mode
   and appended last so it wins the cascade.
   ═══════════════════════════════════════════════════════════════════════ */

body.editorial-v4.dark-mode {
  /* Surface + text tokens the whole editorial system reads from */
  --ivory: #15171c;
  --ivory-dk: #0f1115;
  --v4-content: #15171c;
  --v4-page: #0f1115;
  --v4-soft: #20242b;
  --v4-ink: #e8e4db;
  --v4-muted: #9aa0a9;
  --v4-muted2: #7e848d;
  --v4-muted3: #b6bbc2;
  --v4-hair: #2b2f37;
  --charcoal: #e8e4db;
  color: #e8e4db;
  background: #15171c !important;
}

/* Page shell + content area */
body.editorial-v4.dark-mode #main { color: #e8e4db; }
body.editorial-v4.dark-mode #topbar {
  background: #14161b !important;
  border-bottom: 1px solid #2b2f37 !important;
}

/* Headings that use the theme green become a soft cream so they read on dark */
body.editorial-v4.dark-mode .page-title,
body.editorial-v4.dark-mode h1,
body.editorial-v4.dark-mode h2,
body.editorial-v4.dark-mode h3,
