/* ═══ DARK MODE — ued-scope text tokens (defined on #panel-*.ued-scope, so
   they must be overridden at that scope to beat the ID specificity) ═══ */
body.editorial-v4.dark-mode #panel-dashboard.ued-scope,
body.editorial-v4.dark-mode #panel-guests.ued-scope,
body.editorial-v4.dark-mode #panel-budget.ued-scope,
body.editorial-v4.dark-mode #panel-payments.ued-scope,
body.editorial-v4.dark-mode #panel-vendors.ued-scope,
body.editorial-v4.dark-mode #panel-tasks.ued-scope,
body.editorial-v4.dark-mode #panel-timeline.ued-scope,
body.editorial-v4.dark-mode #panel-contracts.ued-scope {
  --ued-paper:  #1a1a1a;
  --ued-panel:  #1a1a1a;
  --ued-ink:    #e6e6e6;
  --ued-muted:  #8a8a8a;
  --ued-muted2: #727272;
  --ued-line:   rgba(255,255,255,.07);
  --ued-line2:  rgba(255,255,255,.12);
  --ued-sage:   #222222;
}

/* Beat the ID-specificity !important stat-number rule in dark mode */
body.editorial-v4.dark-mode #main .panel .ued-stat b,
body.editorial-v4.dark-mode #main .panel .m-stat-val,
body.editorial-v4.dark-mode #main .panel .ued-stat-num,
body.editorial-v4.dark-mode #main .panel .cdc-tile b {
  color: #f0f0f0 !important;
}

/* Dark mode: headings → light greyscale */
body.editorial-v4.dark-mode #main .panel .cdc-title { color: #cfcfcf !important; }
body.editorial-v4.dark-mode #main .panel h1,
body.editorial-v4.dark-mode #main .panel .m-hero h1,
body.editorial-v4.dark-mode #main .panel .ued-hero h1 { color: #f0f0f0 !important; }
body.editorial-v4.dark-mode #main .panel .ued-donut text { fill: #ececec !important; }

/* ═══ DARK MODE — TABLES ═══ */
body.editorial-v4.dark-mode #main .panel .ued-table-wrap,
body.editorial-v4.dark-mode #main .panel .guest-table-wrap,
body.editorial-v4.dark-mode #main .panel .ued-table-card {
  background: var(--card-bg, #1a1a1a) !important;
}
body.editorial-v4.dark-mode #main .panel table,
body.editorial-v4.dark-mode #main .panel table tbody,
body.editorial-v4.dark-mode #main .panel table tbody tr { background: transparent !important; }
body.editorial-v4.dark-mode #main .panel table tbody td {
  background: transparent !important;
  color: #dfe3ec !important;
  border-color: rgba(255,255,255,.09) !important;
}
body.editorial-v4.dark-mode #main .panel table tbody tr:nth-child(even) td { background: rgba(255,255,255,.03) !important; }
body.editorial-v4.dark-mode #main .panel table tbody tr:hover td { background: rgba(255,255,255,.055) !important; }
body.editorial-v4.dark-mode #main .panel table thead th {
  background: #0f1524 !important;
  color: #c3cad8 !important;
  border-color: rgba(255,255,255,.10) !important;
}
/* In-cell inputs / selects */
