  color: #e6e6e6 !important;
  border-color: #2e2e2e !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   DARK MODE — NEUTRAL ACCENT (monochrome — no blue / green / gold)
   ═══════════════════════════════════════════════════════════════════════ */
body.editorial-v4.dark-mode:not([data-applied-theme]) {
  --forest:        #cfcfcf;
  --forest-lt:     #dcdcdc;
  --forest-deep:   #8a8a8a;
  --forest-deeper: #333333;
  --theme-primary: #222222;
  --theme-accent:  #cfcfcf;
  --gold:          #8a8a8a;
  --gold-lt:       #cfcfcf;
  --gold-pale:     #222222;
  --chart-1:       #9a9a9a;
  --chart-2:       #6f6f6f;
}

/* ═══ DARK MODE — mastheads, banners, guidance strips ═══ */
body.editorial-v4.dark-mode #main .panel .m-mast,
body.editorial-v4.dark-mode #main .panel .m-mast-wrap {
  background: #161616 !important;
  border-color: #2e2e2e !important;
}
body.editorial-v4.dark-mode #main .panel .m-mast * { color: #b8b8b8 !important; }
body.editorial-v4.dark-mode #main .panel .ued-scripture,
body.editorial-v4.dark-mode #main .panel .banner-scripture-card,
body.editorial-v4.dark-mode #main .panel .page-scripture-footer {
  background: #161616 !important;
  color: #cfcfcf !important;
  border-color: #2e2e2e !important;
}
body.editorial-v4.dark-mode #main .panel .ued-scripture *,
body.editorial-v4.dark-mode #main .panel .page-scripture-footer .psf-text,
body.editorial-v4.dark-mode #main .panel .page-scripture-footer cite,
body.editorial-v4.dark-mode #main .panel .page-scripture-footer .leaf-orn {
  color: #cfcfcf !important;
}
body.editorial-v4.dark-mode #main .panel .page-help-banner { background: rgba(255,255,255,.045) !important; }
body.editorial-v4.dark-mode #main .panel .page-help-body,
body.editorial-v4.dark-mode #main .panel .page-help-banner * { color: #b8b8b8 !important; }
body.editorial-v4.dark-mode #main .panel .guide-path-step,
body.editorial-v4.dark-mode #main .panel .guide-alert {
  background: #1a1a1a !important;
  border-color: #2e2e2e !important;
  color: #e0e0e0 !important;
}
body.editorial-v4.dark-mode #main .panel .guide-path-step.current { background: #222222 !important; }
body.editorial-v4.dark-mode #main .panel .guide-alert.urgent { background: rgba(210,90,90,.14) !important; }
/* Any stray text inputs on dark panels */
body.editorial-v4.dark-mode #main .panel input[type="text"],
body.editorial-v4.dark-mode #main .panel input[type="search"],
body.editorial-v4.dark-mode #main .panel input:not([type]) {
  background: #141414 !important;
  color: #e6e6e6 !important;
  border-color: #2a3446 !important;
}

/* ═══ DARK MODE — remaining forest/gold vars + stray white guidance cards ═══ */
body.editorial-v4.dark-mode:not([data-applied-theme]) {
  --er-forest: var(--dm-accent-text);
  --v4-forest: var(--dm-accent-text);
  --v4-gold:   var(--dm-muted);
}
body.editorial-v4.dark-mode #main .panel .next-step-card,
body.editorial-v4.dark-mode #main .panel .guide-privacy-card {
  background: #1a1a1a !important;
  border: 1px solid #2e2e2e !important;
  border-radius: 3px !important;
  box-shadow: none !important;
}
body.editorial-v4.dark-mode #main .panel .next-step-card *:not(button):not(.btn):not(.ued-btn),
body.editorial-v4.dark-mode #main .panel .guide-privacy-card *:not(button):not(.btn):not(.ued-btn) {
  color: #e0e0e0 !important;
}
/* Primary buttons → near-white fill, dark text */
body.editorial-v4.dark-mode #main .panel .ued-btn.primary,
body.editorial-v4.dark-mode #main .panel .btn-forest {
  background: var(--dm-accent, #ececec) !important;
  color: var(--dm-on-accent, #111111) !important;
}

/* ═══════════════════════════════════════════════════════════════════════
   LEGIT DARK MODE — FULL SYSTEM
   Locked to mockups/monochrome-dark-mode-mockup.html
   Charcoal surfaces, light-grey text, near-white primary — no navy/gold.
   ═══════════════════════════════════════════════════════════════════════ */
body.editorial-v4.dark-mode {
  /* ---- palette (mockup lock) ---- */
  --dm-bg:        #111111;
  --dm-page:      #111111;
  --dm-page-deep: #0a0a0a;
  --dm-surface:   #1a1a1a;
  --dm-surface-2: #222222;
  --dm-surface-3: #2a2a2a;
  --dm-elev:      #2a2a2a;
  --dm-elevated:  #2a2a2a;
  --dm-border:    #2e2e2e;
  --dm-border-soft:#262626;
  --dm-hair:      rgba(255,255,255,.07);
  --dm-text:      #e6e6e6;
  --dm-head:      #f0f0f0;
  --dm-muted:     #8a8a8a;
  --dm-muted2:    #727272;
  --dm-placeholder:#656565;
  --dm-accent:    #ececec;
  --dm-on-accent: #111111;
  --dm-accent-2:  #cfcfcf;
  --dm-accent-soft:#cfcfcf;
  --dm-accent-muted:#222222;
  --dm-accent-text:#cfcfcf;
  --dm-accent-bg: rgba(255,255,255,.08);
  --dm-accent-border: rgba(255,255,255,.18);
  --dm-danger:    #c4c4c4;
  --dm-ok:        #b8b8b8;
  --dm-success:   #b8b8b8;
  --dm-warning:   #cfcfcf;
  --dm-info:      #a8a8a8;
  --dm-radius:    3px;

  /* ---- base app tokens ---- */
  --ivory:        var(--dm-bg);
  --ivory-dk:     #0a0a0a;
  --charcoal:     var(--dm-text);

  /* ---- surface tokens (unified system) ---- */
  --page-bg:      var(--dm-bg);
  --section-bg:   var(--dm-bg);
  --card-bg:      var(--dm-surface);
  --card-border:  var(--dm-border);
  --card-radius:  3px;
  --table-header-bg: var(--dm-surface-2);
  --surface-chrome: #161616;
  --context-sidebar-surface: #161616;
  --context-sidebar-head: #161616;

  /* ---- v4 tokens ---- */
  --v4-content: var(--dm-bg);
  --v4-page:    #0a0a0a;
  --v4-soft:    var(--dm-surface);
  --v4-ink:     var(--dm-text);
  --v4-muted:   var(--dm-muted);
  --v4-muted2:  var(--dm-muted2);
  --v4-muted3:  #a0a0a0;
  --v4-hair:    var(--dm-border);
  --v4-card:    var(--dm-surface);

  /* neutralize theme green/gold */
  --forest:        var(--dm-accent-text);
  --forest-lt:     #dcdcdc;
  --forest-deep:   var(--dm-muted);
  --forest-deeper: #333333;
  --gold:          var(--dm-muted);
  --gold-lt:       var(--dm-accent-text);
  --gold-pale:     var(--dm-surface-2);
  --theme-primary: var(--dm-accent-muted);
  --theme-accent:  var(--dm-accent-text);
  --er-forest:     var(--dm-accent-text);
  --v4-forest:     var(--dm-accent-text);
  --v4-gold:       var(--dm-muted);
  --champagne-soft: var(--dm-surface-2);

  color: var(--dm-text);
  background: var(--dm-bg) !important;
}

body.editorial-v4.dark-mode:not([data-applied-theme]) {
  --forest:       var(--dm-accent-text);
  --forest-lt:    #dcdcdc;
  --forest-deep:  var(--dm-muted);
  --forest-deeper:#333333;
  --gold:         var(--dm-muted);
  --gold-lt:      var(--dm-accent-text);
  --theme-primary:var(--dm-accent-muted);
  --theme-accent: var(--dm-accent-text);
  --er-forest:    var(--dm-accent-text);
  --v4-forest:    var(--dm-accent-text);
  --v4-gold:      var(--dm-muted);
  --chart-1:      #9a9a9a;
  --chart-2:      #6f6f6f;
}

/* ued-scope tokens for EVERY panel that uses them */
body.editorial-v4.dark-mode [id^="panel-"].ued-scope {
  --ued-paper:  var(--dm-surface);
  --ued-panel:  var(--dm-surface);
  --ued-ink:    var(--dm-text);
  --ued-muted:  var(--dm-muted);
  --ued-muted2: var(--dm-muted2);
  --ued-line:   var(--dm-hair);
  --ued-line2:  rgba(255,255,255,.12);
  --ued-sage:   var(--dm-surface-2);
  --ued-forest: var(--dm-accent-text);
  --ued-gold:   var(--dm-muted);
}

/* ── Page shell ── */
body.editorial-v4.dark-mode,
body.editorial-v4.dark-mode #layout,
body.editorial-v4.dark-mode #main { background: var(--dm-bg) !important; }
body.editorial-v4.dark-mode #topbar {
  background: #161616 !important;
  border-bottom: 1px solid var(--dm-border) !important;
  color: var(--dm-text) !important;
}
body.editorial-v4.dark-mode #topbar,
body.editorial-v4.dark-mode #topbar * { color: var(--dm-text); }

/* ── Sidebar + icons ── */
body.editorial-v4.dark-mode #sidebar {
  background: #161616 !important;
  border-right: 1px solid var(--dm-border) !important;
}
body.editorial-v4.dark-mode #sidebar .nav-item { color: var(--dm-muted) !important; }
body.editorial-v4.dark-mode #sidebar .nav-item .material-symbols-sharp,
body.editorial-v4.dark-mode #sidebar .nav-item svg { color: currentColor !important; }
body.editorial-v4.dark-mode #sidebar .nav-item:hover {
  background: rgba(255,255,255,.05) !important;
  color: var(--dm-head) !important;
}
body.editorial-v4.dark-mode #sidebar .nav-item[aria-current="page"] {
  background: rgba(255,255,255,.08) !important;
  color: var(--dm-head) !important;
  box-shadow: inset 3px 0 0 var(--dm-accent-text, #cfcfcf) !important;
}

/* Broad surfaces */
body.editorial-v4.dark-mode #main .panel [class*="card"],
body.editorial-v4.dark-mode #main .panel [class*="-box"],
body.editorial-v4.dark-mode #main .panel [class*="-tile"],
body.editorial-v4.dark-mode #main .panel [class*="-panel"],
body.editorial-v4.dark-mode #main .panel [class*="-widget"],
body.editorial-v4.dark-mode #main .panel [class*="-well"],
body.editorial-v4.dark-mode #main .panel .ued-panel,
body.editorial-v4.dark-mode #main .panel > section {
  background: var(--dm-surface) !important;
  border-color: var(--dm-border) !important;
  border-radius: var(--card-radius, 3px) !important;
  box-shadow: none !important;
}

/* ── Broad text: readable, never pure white ── */
body.editorial-v4.dark-mode #main .panel,
body.editorial-v4.dark-mode #main .panel p,
body.editorial-v4.dark-mode #main .panel li,
body.editorial-v4.dark-mode #main .panel td,
body.editorial-v4.dark-mode #main .panel dd,
body.editorial-v4.dark-mode #main .panel dt,
body.editorial-v4.dark-mode #main .panel label,
body.editorial-v4.dark-mode #main .panel small,
body.editorial-v4.dark-mode #main .panel span:not(.material-symbols-sharp),
body.editorial-v4.dark-mode #main .panel strong,
body.editorial-v4.dark-mode #main .panel b { color: var(--dm-text) !important; }

body.editorial-v4.dark-mode #main .panel h1,
body.editorial-v4.dark-mode #main .panel h2,
body.editorial-v4.dark-mode #main .panel h3,
body.editorial-v4.dark-mode #main .panel h4,
body.editorial-v4.dark-mode #main .panel h5,
body.editorial-v4.dark-mode #main .panel .page-title,
body.editorial-v4.dark-mode #main .panel .ued-stat b,
body.editorial-v4.dark-mode #main .panel .cdc-tile b { color: var(--dm-head) !important; }

body.editorial-v4.dark-mode #main .panel th { color: var(--dm-muted) !important; }

/* Links / accent text (asserted after, so they win) */
body.editorial-v4.dark-mode #main .panel a,
body.editorial-v4.dark-mode #main .panel .link,
body.editorial-v4.dark-mode #main .panel [class*="-link"] { color: var(--dm-accent-2) !important; }

/* ── Tables ── */
body.editorial-v4.dark-mode #main .panel .ued-table-wrap,
body.editorial-v4.dark-mode #main .panel [class*="table-wrap"],
body.editorial-v4.dark-mode #main .panel [class*="table-card"] { background: var(--dm-surface) !important; }
body.editorial-v4.dark-mode #main .panel table,
body.editorial-v4.dark-mode #main .panel table tbody,
body.editorial-v4.dark-mode #main .panel table tr { background: transparent !important; }
body.editorial-v4.dark-mode #main .panel table td { background: transparent !important; border-color: var(--dm-hair) !important; }
body.editorial-v4.dark-mode #main .panel table tbody tr:nth-child(even) td { background: rgba(255,255,255,.025) !important; }
body.editorial-v4.dark-mode #main .panel table tbody tr:hover td { background: rgba(255,255,255,.05) !important; }
body.editorial-v4.dark-mode #main .panel table thead th {
  background: var(--dm-surface-2) !important;
  color: var(--dm-muted) !important;
  border-color: var(--dm-border) !important;
}

/* ── Inputs / selects / textareas ── */
body.editorial-v4.dark-mode #main .panel input,
body.editorial-v4.dark-mode #main .panel select,
body.editorial-v4.dark-mode #main .panel textarea {
  background: var(--dm-surface-2) !important;
  color: var(--dm-text) !important;
  border-color: var(--dm-border) !important;
}
body.editorial-v4.dark-mode #main .panel input::placeholder,
body.editorial-v4.dark-mode #main .panel textarea::placeholder { color: var(--dm-muted2) !important; }

/* ── Buttons ── */
body.editorial-v4.dark-mode #main .panel .btn,
body.editorial-v4.dark-mode #main .panel .ued-btn,
body.editorial-v4.dark-mode #main .panel button.btn-outline {
  background: var(--dm-surface-2) !important;
  color: var(--dm-text) !important;
  border-color: var(--dm-border) !important;
}
body.editorial-v4.dark-mode #main .panel .btn.primary,
body.editorial-v4.dark-mode #main .panel .ued-btn.primary,
body.editorial-v4.dark-mode #main .panel .btn-forest,
body.editorial-v4.dark-mode #main .panel .btn-primary {
  background: var(--dm-accent) !important;
  color: var(--dm-on-accent, #111111) !important;
  border-color: transparent !important;
}
body.editorial-v4.dark-mode #main .panel .btn:hover,
body.editorial-v4.dark-mode #main .panel .ued-btn:hover { filter: brightness(1.08); }

/* ── Dividers / hairlines ── */
body.editorial-v4.dark-mode #main .panel hr,
body.editorial-v4.dark-mode #main .panel [class*="divider"] { border-color: var(--dm-border) !important; background: var(--dm-border) !important; }

/* ── REMOVE the masthead box behind page titles ── */
body.editorial-v4.dark-mode #main .panel .m-mast,
body.editorial-v4.dark-mode #main .panel .m-mast-wrap {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* Table headers get an inline background-color:var(--forest)!important from JS.
   Inline !important can't be beaten by a stylesheet — but we CAN redefine the
   custom property ON the th so that inline var(--forest) resolves to a dark
   header colour instead of the gold accent. */
body.editorial-v4.dark-mode #main .panel table thead th,
body.editorial-v4.dark-mode #main .panel [class*="-table"] thead th {
  --forest:        var(--dm-surface-2);
  --er-forest:     var(--dm-surface-2);
  --theme-primary: var(--dm-surface-2);
  --v4-forest:     var(--dm-surface-2);
  --gold:          var(--dm-surface-2);
}

/* ═══ DARK MODE — tab bars (.m-tabbar and similar) ═══ */
body.editorial-v4.dark-mode #main .panel .m-tabbar,
body.editorial-v4.dark-mode #main .panel [class*="tabbar"],
body.editorial-v4.dark-mode #main .panel [class*="-tabs"] {
  background: var(--dm-surface) !important;
  border-color: var(--dm-border) !important;
}
body.editorial-v4.dark-mode #main .panel .m-tabbar [class*="tab"],
body.editorial-v4.dark-mode #main .panel [class*="tabbar"] [class*="tab"],
body.editorial-v4.dark-mode #main .panel [class*="-tabs"] > * {
  color: var(--dm-muted) !important;
  background: transparent !important;
}
body.editorial-v4.dark-mode #main .panel .m-tabbar .active,
body.editorial-v4.dark-mode #main .panel .m-tabbar [aria-selected="true"],
body.editorial-v4.dark-mode #main .panel [class*="tabbar"] .active,
body.editorial-v4.dark-mode #main .panel [class*="-tabs"] .active {
  background: rgba(255,255,255,.08) !important;
  color: var(--dm-head, #f0f0f0) !important;
}

/* ═══ DARK MODE — shared structural containers across pages ═══ */
/* Blend layout wrappers into the page */
body.editorial-v4.dark-mode #main .panel .m-head,
body.editorial-v4.dark-mode #main .panel .smart-layout,
body.editorial-v4.dark-mode #main .panel .smart-calendar-grid,
body.editorial-v4.dark-mode #main .panel .smart-agenda-list,
body.editorial-v4.dark-mode #main .panel .smart-source-strip,
body.editorial-v4.dark-mode #main .panel .smart-alert-row,
body.editorial-v4.dark-mode #main .panel .mood-gallery-section { background: transparent !important; }
/* Raised blocks / bands / cells → surface */
body.editorial-v4.dark-mode #main .panel .m-block,
body.editorial-v4.dark-mode #main .panel .smart-insight-band,
body.editorial-v4.dark-mode #main .panel .smart-day,
body.editorial-v4.dark-mode #main .panel .smart-weekday,
body.editorial-v4.dark-mode #main .panel .inst-guide-item,
body.editorial-v4.dark-mode #main .panel .tbl-wrap,
body.editorial-v4.dark-mode #main .panel [class*="tbl-wrap"] {
  background: var(--dm-surface) !important;
  border-color: var(--dm-border) !important;
}
/* Sub-header rows in tables/lists */
body.editorial-v4.dark-mode #main .panel .cat-table-head,
body.editorial-v4.dark-mode #main .panel .m-subhead { background: var(--dm-surface-2) !important; color: var(--dm-muted) !important; }
/* Progress / meter tracks → subtle dark, not white */
body.editorial-v4.dark-mode #main .panel .progress-track,
body.editorial-v4.dark-mode #main .panel [class*="-track"]:not([class*="fill"]) { background: rgba(255,255,255,.09) !important; }

/* ═══ DARK MODE — floor-plan canvas ═══ */
body.editorial-v4.dark-mode #main .panel #table-map { background-color: #191B21 !important; }
body.editorial-v4.dark-mode #main .panel .floor-fixture,
body.editorial-v4.dark-mode #main .panel [class*="floor-fixture"] {
  background: var(--dm-surface-2) !important;
  border-color: var(--dm-border) !important;
  color: var(--dm-text) !important;
}

/* ═══ DARK MODE — remaining per-page structural containers ═══ */
body.editorial-v4.dark-mode #main .panel .app-insight-band,
body.editorial-v4.dark-mode #main .panel .record-editor-section,
