.cwp-table th[data-t="lookup"], .cwp-table td[data-t="lookup"]  { min-width:130px; }

/* ═══ CWP engine — enforce column widths via cell CONTENT (auto table-layout
   honors intrinsic content min-width, unlike min-width on <td>) ═══ */
.cwp-table td[data-t="text"] > textarea,
.cwp-table td[data-t="text"] > input      { min-width:140px; }
.cwp-table td[data-t="longtext"] > textarea { min-width:205px; }
.cwp-table td[data-t="date"] > input       { min-width:128px; }
.cwp-table td[data-t="time"] > input       { min-width:104px; }
.cwp-table td[data-t="datetime"] > input   { min-width:172px; }
.cwp-table td[data-t="select"] > select,
.cwp-table td[data-t="ref"] > select       { min-width:132px; }
.cwp-table td[data-t="money"] > input,
.cwp-table td[data-t="number"] > input,
.cwp-table td[data-t="percent"] > input    { min-width:82px; }
.cwp-table td[data-t="status"] .cwp-status { min-width:122px; }
.cwp-table td[data-t="status"] .cwp-status select { min-width:106px; }

/* ═══ CWP engine — stars + review cell types (Vendors) ═══ */
.cwp-table th[data-t="stars"],  .cwp-table td[data-t="stars"]  { min-width:112px; }
.cwp-table th[data-t="review"], .cwp-table td[data-t="review"] { min-width:170px; }
.cwp-stars { display:inline-flex; gap:2px; white-space:nowrap; }
.cwp-star { background:none; border:0; padding:0 1px; cursor:pointer; font-size:15px; line-height:1; color:var(--v4-line, #d8d2c6); transition:color .12s; }
.cwp-star.on { color:var(--gold, #c19a4b); }
.cwp-star:hover { color:var(--gold, #c19a4b); }
.cwp-vname { display:flex; align-items:center; gap:6px; min-width:150px; }
.cwp-vname > textarea { flex:1; min-width:110px; }
.cwp-review-btn { display:block; width:100%; text-align:left; background:transparent; border:1px dashed var(--v4-line, #d8d2c6); border-radius:6px; padding:4px 8px; font:inherit; font-size:.78rem; color:var(--v4-muted, #8a8071); cursor:pointer; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.cwp-review-btn.has { border-style:solid; color:var(--v4-forest, #2f4032); }
.cwp-review-btn:hover { border-color:var(--gold, #c19a4b); }
body.editorial-v4.dark-mode .cwp-star { color:#3a3f49; }
body.editorial-v4.dark-mode .cwp-star.on, body.editorial-v4.dark-mode .cwp-star:hover { color:#e6e6e6; }
body.editorial-v4.dark-mode .cwp-review-btn { border-color:#32363F; color:#969AA4; }
body.editorial-v4.dark-mode .cwp-review-btn.has { color:#CDCFD6; }

/* ==========================================================================
   CWP engine — global table behaviours (selection everywhere, uniform inputs,
   per-column filters, column resizing, per-row button removal, dark-mode text)
   ========================================================================== */

/* Uniform field widths: every text/select/textarea fills its cell so rows line
   up regardless of any inline widths in bespoke row markup. Column width is then
   controlled by the header (and the drag-resize handle). */
.cwp-table td input:not([type="checkbox"]):not([type="radio"]),
.cwp-table td textarea,
.cwp-table td select { width:100% !important; min-width:0 !important; box-sizing:border-box; }

/* Per-row Edit / Delete columns are removed structurally by the engine
   (stripActions) and replaced by the toolbar's "Edit Selected" / "Delete
   Selected" bulk actions. Tables in the keep-list (Contacts, Day-of Timeline,
   Appointments) retain their action cell because it carries navigation or is
   their only delete affordance. */

/* Slim bulk bar for tables whose page owns its own heading/Add button */
.cwp-toolbar--bulk { display:flex; gap:.5rem; align-items:center; padding:.35rem 0 .55rem; flex-wrap:wrap; }
.cwp-toolbar--autofit { display:flex; gap:.5rem; align-items:center; justify-content:flex-end; padding:.35rem 0 .55rem; flex-wrap:wrap; }
.planner-autofit-bar { display:flex; justify-content:flex-end; margin:0 0 .45rem; }

.cwp-bulk-count { font-size:.74rem; color:var(--cwp-ink-soft); }

/* Column resize handle on the right edge of every header cell */
.cwp-table thead th { position:relative; }
.cwp-col-resizer { position:absolute; top:0; right:0; width:8px; height:100%; cursor:col-resize; user-select:none; touch-action:none; }
.cwp-col-resizer:hover { background:rgba(255,255,255,.28); }
.cwp-table.cwp-resizing { cursor:col-resize; user-select:none; }

/* Dark mode: engine cell text was near-black on a dark panel (invisible until
   focused). Give cells/inputs a light ink so typed text is always readable. */
body.editorial-v4.dark-mode .cwp-table tbody td { color:#e8e4da; }
body.editorial-v4.dark-mode .cwp-table td input:not([type="checkbox"]):not([type="radio"]),
body.editorial-v4.dark-mode .cwp-table td textarea,
body.editorial-v4.dark-mode .cwp-table td select { color:#e8e4da; }
body.editorial-v4.dark-mode .cwp-table td input::placeholder,
body.editorial-v4.dark-mode .cwp-table td textarea::placeholder { color:#7c8088; }
body.editorial-v4.dark-mode .cwp-table td input:hover,
body.editorial-v4.dark-mode .cwp-table td textarea:hover { background:rgba(255,255,255,.06); }
body.editorial-v4.dark-mode .cwp-table td input:focus,
body.editorial-v4.dark-mode .cwp-table td textarea:focus,
body.editorial-v4.dark-mode .cwp-table td select:focus { background:#1b1e24; color:#fff; border-color:var(--cwp-accent); }
body.editorial-v4.dark-mode .cwp-table td select option { background:#1b1e24; color:#e8e4da; }
body.editorial-v4.dark-mode .cwp-table tbody tr:hover { background:rgba(255,255,255,.035); }
body.editorial-v4.dark-mode .cwp-table td.cwp-readonly,
body.editorial-v4.dark-mode .cwp-table .cwp-readonly { color:#b8bcc4; }

/* ═══ CWP engine — pagination controls ═══ */
.cwp-pager { margin-top:.6rem; }
.cwp-pager-inner { display:flex; align-items:center; justify-content:space-between; gap:1rem; flex-wrap:wrap; }
.cwp-pager-count { font-size:.75rem; color:var(--v4-muted, #8a8071); }
.cwp-pager-ctrls { display:inline-flex; align-items:center; gap:.35rem; }
.cwp-page-of { font-size:.75rem; color:var(--v4-muted, #8a8071); padding:0 .3rem; }
.cwp-page-btn { min-width:30px; height:30px; padding:0 .55rem; border:1px solid var(--v4-line, #d8d2c6); background:var(--card-bg, #fff); color:var(--v4-forest, #2f4032); border-radius:6px; font:inherit; font-size:.78rem; cursor:pointer; }
.cwp-page-btn:hover:not([disabled]) { border-color:var(--gold, #c19a4b); color:var(--gold, #c19a4b); }
.cwp-page-btn[disabled] { opacity:.4; cursor:default; }
