body.editorial-v4.dark-mode .cwp-page-btn:hover:not([disabled]) { border-color:#3a3a3a; color:#e6e6e6; }
body.editorial-v4.dark-mode .cwp-pager-count, body.editorial-v4.dark-mode .cwp-page-of { color:#969AA4; }

/* ═══ Payments in the engine table — carry over row-state highlights
   (originals were scoped to .payments-table, which the engine no longer uses) ═══ */
#panel-payments .cwp-table tbody tr.payment-overdue-row td { background: rgba(249,235,229,.32); }
#panel-payments .cwp-table tbody tr.payment-plan-active-row td { background: rgba(251,245,236,.48); }
