body.editorial-v4.dark-mode #panel-payments .cwp-table tbody tr.payment-overdue-row td { background: rgba(206,128,120,.12); }
body.editorial-v4.dark-mode #panel-payments .cwp-table tbody tr.payment-plan-active-row td { background: rgba(255,255,255,.06); }
