  box-shadow: 0 18px 48px rgba(42, 42, 42, .28);
  padding: 1.5rem 1.5rem 1.25rem;
  font-family: var(--font-sans, Inter, "Noto Sans", Arial, sans-serif);
  transform: translateY(6px) scale(.99);
  transition: transform .18s ease;
}
