.cov-modal__body {
  margin: 0;
  font-size: .95rem;
  line-height: 1.55;
  color: var(--charcoal, #2A2A2A);
  white-space: pre-wrap;
  overflow-wrap: break-word;
  word-break: break-word;
}

.cov-modal__field { margin-top: 1rem; }
.cov-modal__field[hidden] { display: none; }
.cov-modal__input {
  width: 100%;
  box-sizing: border-box;
  padding: .6rem .7rem;
