}

/* ══════════════════════════════════════════════════════════════════════════
   FULL-WIDTH TABLES — tables + sub-tables fill the content area; cell inputs
   stretch to column width. Appended last to win over legacy max-content rules.
   ══════════════════════════════════════════════════════════════════════════ */

/* Wrappers and card shells span the content column */
#main .panel [class*="-table-card"],
#main .panel [class*="-table-wrap"],
#main .panel .cwp-table-wrap,
#main .panel .ued-table-wrap,
#main .panel .tbl-wrap,
#main .panel .payment-plan-card,
#main .panel .payment-plan-table-wrap,
#main .panel .plan-sub-wrap {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box;
}

/* Data tables fill their wrapper (override legacy width:max-content shrink) */
#main .panel table:not(.party-table) {
  width: 100% !important;
  min-width: 100% !important;
  max-width: 100% !important;
  table-layout: fixed !important;
  box-sizing: border-box;
}

/* After Auto-fit / content-sized columns, allow the table to grow past the
   panel width so horizontal scroll works (otherwise max-width:100% clamps
   every column and auto-fit appears to do nothing). */
#main .panel table.planner-cols-autofit:not(.party-table) {
  width: auto !important;
  min-width: 100% !important;
  max-width: none !important;
}

/* Temporary unlock while measuring a cell for auto-fit — inputs are forced
   to width:100% !important, which otherwise makes scrollWidth = column width. */
#main .panel table td.planner-measure-cell,
#main .panel table th.planner-measure-cell {
  width: max-content !important;
  min-width: max-content !important;
  max-width: none !important;
  white-space: nowrap !important;
}
#main .panel table td.planner-measure-cell > input:not([type="checkbox"]):not([type="radio"]),
#main .panel table td.planner-measure-cell > textarea,
#main .panel table td.planner-measure-cell > select,
#main .panel table th.planner-measure-cell > * {
  width: max-content !important;
  min-width: max-content !important;
  max-width: none !important;
  white-space: nowrap !important;
}

#main table.planner-resizable-table,
#main .panel .cwp-table {
  width: 100% !important;
  min-width: 100% !important;
}

/* Sub / nested tables (payment installments, expanded plan rows) */
#main .panel .payment-plan-table,
#main .panel .plan-sub-wrap table,
#main .panel table table {
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  table-layout: fixed !important;
}

#main .panel .payment-plan-detail-row > td,
#main .panel .payment-plan-card {
  width: 100% !important;
  max-width: 100% !important;
}

/* Cells can shrink so fixed layout distributes space across the row */
#main .panel table:not(.party-table) th,
#main .panel table:not(.party-table) td {
  min-width: 0;
  box-sizing: border-box;
}

/* Inputs/selects/textareas fill their column (checkboxes/buttons excluded) */
#main .panel table td input:not([type="checkbox"]):not([type="radio"]):not([type="button"]):not([type="submit"]),
#main .panel table td select,
#main .panel table td textarea,
#main .panel .cwp-table td input:not([type="checkbox"]):not([type="radio"]),
#main .panel .cwp-table td select,
#main .panel .cwp-table td textarea,
#main .panel .payment-plan-table input,
#main .panel .payment-plan-table select,
#main .panel .payment-plan-table textarea {
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
}

#main .panel table td .cwp-status,
#main .panel table td .task-status-wrap,
#main .panel table td [class*="-status-wrap"] {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
}

/* Counseling: wide notes columns keep auto layout but still fill width */
body.editorial-v4 #panel-counseling table {
  table-layout: auto !important;
  min-width: 100% !important;
  width: 100% !important;
}

/* Seating-chart mockup tiles — not full-width data tables */
#panel-tables .table-card {
  max-width: 210px !important;
  width: 100%;
}

/* Mobile card-stack: preserve responsive field stretch */
body.layout-mobile #main .panel .cwp-table {
  width: 100% !important;
}

body.layout-mobile #main .panel .cwp-table tbody td > input,
body.layout-mobile #main .panel .cwp-table tbody td > select,
body.layout-mobile #main .panel .cwp-table tbody td > textarea {
  width: 100% !important;
  flex: 1 1 auto;
  min-width: 0;
}

